(window.GIM_TS=window.GIM_TS||{})["Menachot.6"]={"from":144,"a":[["\u0003מנחת חוטא של כהנים\u0004 שיהא דינה \u0003כמנחת חוטא של ישראל,\u0004 \u0003מה מנחת חוטא של ישראל נקמצת, אף מנחת חוטא של כהנים\u0004 \u0003נקמצת.\u0004","ויש לשאול: \u0003אי\u0004 \u0005[או]\u0006 שמא תלמד באופן זה: \u0003מה מנחת חוטא של ישראל\u0004 — \u0003נקמצת ושיריה נאכלין\u0004 על ידי הכהנים, \u0003אף מנחת חוטא של כהנים\u0004 — \u0003נקמצת ושיריה נאכלין?\u0004","\u0003תלמוד לומר\u0004 (מלמדנו האמור) \u0003\"לכהן כמנחה\"\u0004 (ויקרא ה, יג), כי רק \u0003ל\u0004ענין עבודת ה\u0003כהן\u0004 הושוותה מנחת חוטא של כהן \u0003כמנחה\u0004 של ישראל, \u0003ולא ל\u0004ענין ה\u0003אשים\u0004 (ההקרבה על אש המזבח) \u0003כמנחה\u0004. אלא שיירי מנחת חוטא כהן קרבים על אש המזבח. \u0003הא\u0004 \u0005[הרי]\u0006 מעתה יש לשאול: \u0003כיצד\u0004 הוא דינה של מנחת חוטא כהן — ה\u0003קומץ\u0004 של מנחת חוטא כהן \u0003קרב בעצמו\u0004 (ובכך דומה דין מנחת חוטא כהן לדין מנחת חוטא ישראל) \u0003ו\u0004אילו ה\u0003שירים\u0004 של מנחת חוטא כהן \u0003קריבין בעצמן\u0004 על אש המזבח (ובכך אין דינם דומה לדין מנחת חוטא ישראל).","בברייתא ששנינו למעלה, הובאו דברי חכמים שהכתוב \"והיתה לכהן כמנחה\" מלמדנו שרשאי הכהן לעבוד בעבודות מנחת חוטא שלו עצמו. ושואלים על כך: וכי \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 \u0003שתהא עבודתה כשרה בו, מהכא\u0004 \u0005[מכאן]\u0006 מפסוק זה \u0003נפקא\u0004 \u0005[יוצאת,\u0006 נלמדת\u0005]?\u0006","והרי \u0003מהתם\u0004 \u0005[משם]\u0006 ממקום אחר \u0003נפקא\u0004 \u0005[יוצאת,\u0006 נלמדת\u0005],\u0006 וכמו ששנינו בברייתא: \u0003מנין ל\u0004דינו של \u0003כהן ש\u0004הוא \u0003בא ומקריב\u0004 (רשאי לבוא ולהקריב) את \u0003קרבנותיו\u0004 שלו \u0003בכל עת ובכל שעה שירצה,\u0004 גם אם באותה עת עובדים במקדש בני משמרת כהונה שאין הוא נמנה עליה? \u0003תלמוד לומר\u0004 בדינם של העובדים במקדש: \u0003\"ובא בכל אות נפשו\u0004 אל המקום אשר יבחר ה'. \u0003ושרת\u0004 בשם ה' אלהיו ככל אחיו הלוים העומדים שם לפני ה' \" (דברים יח, ו—ז)!","ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 נלמד דין זה רק \u0003מהתם\u0004 \u0005[משם],\u0006 מהכתוב \"ובא בכל אות נפשו\" \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 רק ב\u0003דבר\u0004 (קרבן) \u0003שאין בא על חטא\u0004 שחטא בו הכהן, \u0003אבל\u0004 ב\u0003דבר שבא על חטא\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יעבוד הכהן בקרבנו, ולכך בא הכתוב \"והיתה לכהן כמנחה\", ללמד שאף בקרבן הבא על חטא רשאי הכהן לעבוד.","ושואלים על כך: \u0003ו\u0004כי \u0003הא נמי\u0004 \u0005[\u0006הלכה \u0005זו גם כן]\u0006 שהכהן רשאי לעבוד אף בקרבנו הבא על חטא, \u0003מהכא\u0004 \u0005[מכאן],\u0006 מהפסוק \"והיתה לכהן כמנחה\" \u0003נפקא\u0004 \u0005[יוצאת,\u0006 נלמדת\u0005]?\u0006 והלא \u0003מהתם\u0004 \u0005[משם],\u0006 ממקום אחר היא \u0003נפקא\u0004 \u0005[יוצאת,\u0006 נלמדת\u0005]:\u0006 שכן נאמר \u0003\"וכפר הכהן על הנפש השגגת בחטאה בשגגה\u0004 לפני ה' לכפר עליו ונסלח לו\" (במדבר טו, כח), שהכתוב \"על הנפש השוגגת\" — אף על נפשו שלו השוגגת מדבר, הרי כתוב זה \u0003מלמד שהכהן מתכפר\u0004 אף בקרבן הבא על חטא \u0003על ידי\u0004 עבודתו בהם ב\u0003עצמו!\u0004","ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 נלמד את דינו של הכהן העובד בקרבנותיו הבאים על חטא רק \u0003מ\u0004הכתוב \u0003ההוא\u0004 \"על הנפש השוגגת\", \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 רק בקרבן הבא על חטא שנעשה \u0003בשוגג, אבל\u0004 בקרבנו הבא על חטא שנעשה \u0003במזיד\u0004 — \u0003לא\u0004 עובד הכהן, לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 הכתוב \"והיתה לכהן כמנחה\" \u0005משמיע לנו]\u0006 שאף בקרבנו הבא על חטא במזיד עובד הכהן.","ושואלים: קרבן הבא על חטא \u0003במזיד, היכי משכחת לה\u0004 \u0005[היכן אתה מוצא אותה]?\u0006 ומשיבים: \u0003ב\u0004מנחת חוטא הבאה על שבועת העדות (שנשבע העד לשקר שאינו יודע עדות לענין הנוגע לחבירו), שבאה אף ב\u0003זדון שבועה,\u0004 ואף בקרבן כזה הכהן עובד בקרבנו.","ועוד בדעת ר' שמעון שמנחת חוטא של כהנים נקמצת ושייריה קרבים על המזבח לעצמם, ובדעות נוספות \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת],\u0006 \u0003ר' שמעון אומר:\u0004 \u0003מנחת חוטא של כהנים נקמצת, והקומץ קרב בפני עצמו, והשירים קריבין בפני עצמן, ר' אלעזר בר' שמעון,\u0004 בנו, \u0003אומר: הקומץ\u0004 ממנחת החוטא של כהנים \u0003קרב ב\u0004פני \u0003עצמו, ו\u0004אולם \u0003השירים מתפזרין על\u0004 פני \u0003בית הדשן.\u0004","ובעקבות הלכה זו של ר' אלעזר בנו של ר' שמעון, \u0003אמר ר' חייא בר אבא\u0004 כי \u0003הוי\u0004 \u0005[היה מתקשה]\u0006 \u0003בה,\u0004 בפירושה, \u0003ר' יוחנן\u0004 כך: \u0003בית הדשן\u0004 הנזכר בדברי ר' אלעזר בנו של ר' שמעון \u0003דהיכא\u0004 \u0005[של היכן]\u0006 הוא, באיזה מבתי הדשן שבמקדש כוונתו. \u0003אי\u0004 \u0005[אם]\u0006 הכוונה לבית הדשן ש\u0003למעלה\u0004 (שעל המזבח), שניתנים השירים על האפר הצבור שם — \u0003היינו אבוה\u0004 \u0005[זהו\u0006 שיטת \u0005אביו,\u0006 ר' שמעון\u0003],\u0004 שהרי אחר שקרבים השיריים (כדעת ר' שמעון) גורפים אותם ל\"תפוח\" שעל המזבח, ונמצא שתוך כדי כך הם מתפזרים על בית הדשן! ו\u0003אי\u0004 \u0005[אם]\u0006 הכוונה היא לבית הדשן ש\u0003למטה\u0004 (מתחת למזבח) — האם \u0003יש לך דבר שקרב\u0004 במקום שהוא \u0003למטה\u0004 מהמזבח?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא\u0004 לר' חייא בר אבא: \u0003דלמא\u0004 \u0005[שמא]\u0006 כוונת ר' אלעזר בנו של ר' שמעון שמפזרים את השיריים בבית הדשן כדי להוליכם בכך \u0003לאיבוד.\u0004 ומסופר כי כשאמר ר' אבא דברים אלה בבית המדרש, \u0003אחיכו\u0004 \u0005[צחקו]\u0006 החכמים היושבים שם \u0003עליה\u0004 \u0005[עליו],\u0006 אמרו: \u0003וכי יש לך\u0004 בקדשים \u0003דבר\u0004 שנעבדה בו עבודה \u0003קרב לאיבוד?\u0004","ומתרצים: אכן יש מן הקדשים שהולך לאיבוד, שכן הוא הדין במנחת חוטא של כהנים, שכך \u0003תני אבוה\u0004 \u0005[שנה אביו]\u0006 של \u0003ר' אבין:\u0004 נאמר במנחת חוטא \u0003\"ו\u0004 \u0003כל מנחת כהן כליל תהיה לא תאכל\"\u0004 (ויקרא ו, טז). ולשון הכתוב תמוהה, שאחר שכבר השמיענו הכתוב כי \"כליל תהיה\" מה לימדנו הנאמר בו \"לא תאכל\"? אלא לומר: דווקא \u0003לאכילה הקשתיה\u0004 את מנחת חוטא של כהנים למנחת חביתין, וללמדנו שאף מנחת חוטא של כהנים אינה נאכלת, \u0003ולא\u0004 הקשתיה למנחת חביתין \u0003לדבר אחר,\u0004 שתוקטר כולה כדרך שמוקטרת מנחת חביתין.","ושואלים על דרשה זו: \u0003מאי קא\u0004 \u0003אמר\u0004 \u0005[מה הוא אומר],\u0006 מה כוונתו, שהרי אין לומר \u0005שמנחת כהנים אינה מוקטרת כולה, שהרי בה נאמר \"כליל תהיה\"!\u0006 \u0003אמר אביי: הכי קא אמר\u0004 \u0005[כך הוא אומר,\u0006 כך כוונתו\u0005],\u0006 שכך לדעתו יש לקרוא את הכתוב, בסירוס, ובשינוי מקום חלקי הנאמר בו: \"ו \u0003כל מנחת כהן... לא תאכל\"\u0004 — בקרבן \u0003חובתו\u0004 של כהן, כגון מנחת חוטא, שאינה נאכלת, אך גם אינה מוקטרת כולה, אלא הולכת לבית הדשן (וכשיטת ר' אלעזר בנו של ר' שמעון). \"וכל מנחת \u0005כהן\u0006 \u0003כליל תהיה\"\u0004 — בקרבן \u0003נדבתו\u0004 של כהן, \u0005שאינה נאכלת ומוקטרת כולה, כמנחת חביתין.\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לאביי: איך אתה יכול לומר כך, הרי זו כמו \u0003סכינא חריפא מפסקא קראי\u0004 \u0005[סכין חדה\u0006 ש\u0005פוסקת,\u0006 קוטעת את \u0005הפסוקים]!\u0006","\u0003אלא אמר רבא\u0004 הסבר אחר, שכך לדעתו יש לקרוא את הכתוב: \"ו \u0003כל מנחת כהן כליל תהיה\"\u0004 — זו מנחת \u0003נדבתו\u0004 של כהן, שמוקטרת כולה. \u0003\"לא תאכל\"\u0004 — זו מנחת \u0003חובתו\u0004 של כהן, כמנחת חוטא, שאינה נאכלת אבל אינה מוקטרת כולה.","ושואלים: \u0003ו\u0004מנין לך לדרוש כך את הכתוב, שמא \u0003איפוך אנא\u0004 \u0005[אהפוך אני]\u0006 את דרך הדרשה, ואומר כי הכתוב \"כליל תהיה\" מתייחס למנחת חובתו של כהן, וזו מוקטרת כולה, ואילו הכתוב \"לא תאכל\" מתייחס למנחת נדבתו, שאינה נאכלת, אך אינה מוקטרת כולה! ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 יותר לומר שאת מנחת \u0003נדבתו\u0004 של כהן \u0003הוה ליה\u0004 \u0005[היה לו]\u0006 \u0003לרבויי\u0004 \u0005[לרבות]\u0006 שמוקטרת כולה, ולא את מנחת חובתו של כהן. \u0003שכן\u0004 דומה היא מנחת נדבתו של כהן למנחת חביתין, ובדברים הבאים: הריהי \u0003תדירה\u0004 (באה תמיד, בכל זמן שרוצה הכהן להביא \u0005מנחה), ובדומה למנחת חביתין הבאה בכל יום; וכמו כן הריהי באה על ידי כהן ש\u0006\u0003לא חטי\u0004 \u0005[לא חטא]\u0006 וכמנחת חביתין: וכמו כן הריהי \u0003בסים ריחיה\u0004 \u0005[ריחו מבושם,\u0006 מתובל ומרוקח\u0005]\u0006 כמנחת חביתין, שכן זו וזו בלולות בשמן וניתנת עליהם לבונה. וכל אלה אינם במנחת חוטא.","ודוחים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 דווקא את מנחת \u0003חובתו\u0004 של כהן \u0003הוה ליה לרבויי\u0004 \u0005[היה לו לרבות],\u0006 \u0003שכן\u0004 דומות הן בצדדים הבאים: שמנחת חובתו באה מ\u0003עשרון\u0004 אחד בלבד, וכמנחת חביתין (בעוד שלמנחת \u0005נדבה אין שיעור קבוע. ועוד, ששתיהן באות כ\u0006\u0003חובה\u0004 (מה שאין כן במנחת נדבה)! ומשיבים: מאחר ש\u0003הנך\u0004 \u0005[אלה]\u0006 צדדי הדמיון בין מנחת נדבה למנחת חביתין \u0003נפישן\u0004 \u0005[מרובים]\u0006 יותר, ודאי הקיש הכתוב למנחת החביתין דווקא את מנחת הנדבה.","עד כה התבארו שיטותיהם של ר' שמעון (שמנחת חוטא של כהנים נקמצת והקומץ קרב לעצמו והשיריים קרבים לעצמם), ושל ר' אלעזר בנו של ר' שמעון (שבמנחת חוטא של כהנים הקומץ קרב לעצמו והשיריים מתפזרים על בית הדשן). \u0003ו\u0004מבררים: \u0003רבנן\u0004 \u0005[חכמים],\u0006 שלדעתם כל מנחות הכהנים אינן נקמצות ומוקטרות כליל, \u0003האי\u0004 \u0005[זה]\u0006 הפסוק \u0003\"כל מנחת כהן כליל תהיה לא תאכל\" מאי עבדי ליה\u0004 \u0005[מה עושים בו,\u0006 כיצד הם דורשים אותו\u0005]?\u0006","ומשיבים: \u0003מיבעי להו לכדתניא\u0004 \u0005[צריכים הם\u0006 אותו \u0005ל\u0006דרשה \u0005כמו ש\u0006היא \u0005שנויה\u0006 בברייתא\u0005]:\u0006 נאמר \"כליל\" הן במנחת חביתין (\"כליל תקטר\"), והן במנחת כהן (\"כליל תהיה לא תאכל\"), ללמד שיש להקישן. אכן מן הכתוב עצמו \u0003אין לי אלא\u0004 שדין המנחה ה\u0003עליונה\u0004 (הנזכרת קודם, מנחת חביתין) \u0003ב\"כליל תקטר\"\u0004 (שהיא מוקטרת כולה), \u0003ו\u0004שדין המנחה ה\u0003תחתונה\u0004 (הנזכרת אחריה, מנחת כהנים) שהיא \u0003ב\u0004\"כליל תהיה \u0003לא תאכל\"\u0004 (שאסורה כולה באכילה).","ו\u0003מנין\u0004 שיש \u0003ליתן את האמור של זה בזה,\u0004 שאף מנחת כהנים תוקטר כולה כמנחת חביתין, \u0003ואת האמור של זה בזה,\u0004 שיהא דין איסור אכילה נוהג אף מנחת חביתין תהא אסורה באכילה כמנחת כהנים? \u0003תלמוד לומר\u0004 הכתוב בשתי המנחות הללו \u0003\"כליל\" \"כליל\" לגזירה שוה: נאמר כאן\u0004 (במנחת כהנים) \u0003\"כליל\", ונאמר להלן\u0004 (במנחת חביתין) \u0003\"כליל\",\u0004","\u0003מה להלן\u0004 (במנחת חביתין) — \u0003ב\"כליל תקטר\", אף כאן\u0004 (במנחת חביתין) — \u0003ב\"כליל תקטר\". ומה כאן\u0004 (במנחת כהנים) — בא הכתוב \u0003ליתן\u0004 איסור \u0003לא תעשה על אכילתו, אף להלן\u0004 (במנחת חביתין) — בא הכתוב \u0003ליתן לא תעשה על אכילתו.\u0004","ועוד בענין איסור אכילה הנלמד מ\"כליל תהיה לא תאכל\", \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבינא: כהן שאכל מן האימורין\u0004 (חלקי הקרבן הקרבים על המזבח) \u0003מה הוא\u0004 דינו? ומסביר רבינא את שאלתו: לענין לעבור באכילתו זו על \u0003לאו\u0004 של \u0003זרות\u0004 (\"וכל זר לא יאכל קודש\"."],["\u0003לא קא מיבעיא\u0004 \u0005[לא נשאלה,\u0006 נסתפקה\u0005]\u0006 \u0003לי,\u0004 שברור הוא שהוא נחשב כזר לאכילה זו. ומוסיף רבינא ומסביר: \u0003כי קא מבעיא\u0004 \u0005[כאשר נשאלה]\u0006 \u0003לי\u0004 שאלתי, הרי זה ביחס לאיסור \u0003לאו\u0004 של \u0003\"כליל תהיה\u0004 לא תאכל\" (ויקרא ו, טז) הנאמר במנחת חביתין, \u0003מאי\u0004 \u0005[מה]\u0006 דינו של כהן זה, האם אף שאיסור זה נאמר במנחת חביתין, יהא כן הדין אף באכילת אימורים מן הקרבן, או מאחר שלא נאמר בהם איסור זה, לא יעבור עליו הכהן.","\u0003אמר רב אהרן לרבינא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלתך ממה \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: כל\u0004 דבר בקדשים (ולא רק במנחת כהן) \u0003שהוא ב\u0004מצות \u0003\"כליל תהיה\"\u0004 (שמצוה לשורפו), וכגון האימורים שדינם לשריפה, בא הכתוב \u0003ליתן\u0004 בו אף \u0003איסור\u0004 \u0003לא תעשה על אכילתו.\u0004","כל \u0003מנחת כהנים,\u0004 של חובה או של נדבה, ובמנחת חינוך (מנחתו של הכהן ביום בו הוא נחנך לעבודה במקדש), \u0003ומנחת כהן משיח\u0004 (\"מנחת חביתין\", אותה מקריב הכהן הגדול בכל יום), \u0003ומנחת נסכים\u0004 (שמביאים עמה יין לנסך), הבאה עם קרבנות שונים — כל אלה עולות כולן \u0003למזבח\u0004 בלא שנקמצות תחילה, \u0003ואין בהן\u0004 דבר כלשהו הניתן \u0003לכהנים. ובזה\u0004 (בסוג קדשים זה) \u0003יפה\u0004 (חזק) \u0003כח\u0004 ה\u0003מזבח\u0004 שמוקטרים עליו כל אלה, \u0003מכח הכהנים\u0004 שאין להם דבר בקדשים הללו. ואילו \u0003שתי הלחם\u0004 המובאים בחג השבועות, \u0003ולחם הפנים\u0004 אותם עורכים בכל שבת על שולחן הזהב הנמצא בהיכל, \u0003נאכלין\u0004 \u0003לכהנים\u0004 בלבד, \u0003ואין בהם למזבח\u0004 כל חלק, שאין דבר מהם העולה על המזבח להקטרה. \u0003ובזה יפה\u0004 (חזק) הוא \u0003כח הכהנים מכח המזבח.\u0004","ותוהים: \u0003ותו\u0004 \u0005[ועוד]\u0006 קדשים אחרים מלבד אלה המוזכרים במשנתנו שעולים כולם למזבח ואין לכהנים חלק בהם \u0003ליכא\u0004 \u0005[אין]?\u0006 \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 קרבן ה\u0003עולה,\u0004 שהריהו קרב כולו על המזבח! ומשיבים: מכל מקום \u0003איכא\u0004 \u0005[יש]\u0006 \u0003עורה\u0004 של הבהמה שניתן \u0003לכהנים\u0004 ואינה עולה איפוא כולה על המזבח. ושואלים עוד: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 קרבן \u0003עולת העוף\u0004 שעולה כולו על המזבח, ואין עורו ניתן לכהנים! ומשיבים: \u0003איכא\u0004 \u0005[יש]\u0006 \u0003מוראה\u0004 (הזפק) \u0003ונוצה\u0004 שעליה, שאינן קרבות על המזבח. ושואלים עוד: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003נסכים\u0004 של יין, אותם מנסכים על המזבח כולם, ואין נותנים מהם כלל לכהנים! ומשיבים: הנסכים אינם מוקרבים על המזבח, אלא \u0003לשיתין\u0004 (חללים שמתחת למזבח) הריהם \u0003אזלי\u0004 \u0005[הולכים],\u0006 ושואלים עוד:","\u0003ומאי\u0004 \u0005[ומה]\u0006 באה ללמדנו הלשון המדגישה כי \u0003\"בזו\u0004 יפה כח מזבח מכח הכהנים\", שניתן להסיק ממנה כי יש דבר אחר, שהיה מקום לומר בו שאף הוא ניתן כולו למזבח ואינו ניתן לכהנים? ומסבירים: הרי זה בא \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 לשלול\u0005]\u0006 \u0003מ\u0004דברי \u0003שמואל,\u0004 שכן \u0003אמר שמואל: המתנדב יין\u0004 (בלא קרבן) לבית המקדש, מה יעשה בו? הריהו \u0003מביאו\u0004 למקדש, \u0003ומזלפו על גבי אישים\u0004 (אש המזבח), ולדעת שמואל יש עוד מקרה בו דבר ניתן כולו למזבח ואין לכהנים חלק בו. לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 התנא במשנתנו, \u0005משמיע לנו]\u0006 שרק בשלושת המקרים הללו כך הדין, והמתנדב יין, אותם נסכי יין \u0003לשיתין אזלי\u0004 \u0005[הולכים]\u0006 ולא על המזבח.","ומוסיפים: ואולם יש במשנתנו גם דין ש\u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לשמואל,\u0004 בהלכה אחרת שאמר, שכן \u0003אמר שמואל: המתנדב שמן\u0004 לבית המקדש, מה יעשה בו? הריהו \u0003קומצו,\u0004 ומקריב קומץ זה על המזבח, \u0003ושיריו\u0004 של השמן \u0003נאכלין\u0004 לכהנים. וממשמעות דברי משנתנו יש להוכיח כי אף בנדבת שמן אין כולו קרב על המזבח, אלא רק חלק ממנו, והשאר ניתן לכהנים.","שנינו במשנתנו כי ב\u0003שתי הלחם ו\u0004ב\u0003לחם הפנים\u0004 יפה כח כהנים מכח מזבח, שבאלה הכל ניתן לכהנים, ואין למזבח כל חלק בהם. ותוהים: \u0003ותו\u0004 \u0005[ועוד]\u0006 קדשים אחרים שניתנים כולם לכהנים ואין למזבח חלק בהם \u0003ליכא\u0004 \u0005[אין]?\u0006 \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 קרבן \u0003חטאת העוף,\u0004 שכולו נאכל לכהנים, ואין למזבח כל חלק בו! ומשיבים: אין קרבן חטאת העוף נחשב כמי שאין למזבח חלק בו, שכן \u0003איכא\u0004 \u0005[יש]\u0006 למזבח \u0003את\u0004 \u0003דמה\u0004 של חטאת זו שמזים אותם על המזבח.","ושואלים עוד: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003לוג שמן של\u0004 ה\u0003מצורע\u0004 המובא ביום טהרתו, שניתן לכהנים, ולא למזבח! ומשיבים: אין כולו ניתן לכהנים, שכן \u0003איכא\u0004 \u0005[יש]\u0006 בתחילה \u0003מתנותיו\u0004 (הנתינות) שניתנות מהשמן כשבע הזאות \"לפני ה' \" (ויקרא יד, טז), ולאחר מכן מיתר השמן נותן הכהן על תנוך אוזנו הימנית של המיטהר ועל בוהן ידו הימנית ועל בוהן רגלו הימנית (שם יז).","ושואלים עוד: \u0003ומאי\u0004 \u0005[ומה]\u0006 אם כן באה ללמדנו הלשון המדגישה כי \u0003\"בזו\u0004 יפה כח הכהנים מכח מזבח\"? הרי זה בא \u0003לאפוקי ממאן דאמר\u0004 \u0005[להוציא,\u0006 לשלול, \u0005מ\u0006דעתו של \u0005מי שאומר]\u0006 כי \u0003שתי הלחם הבאות בפני עצמן\u0004 בלי כבשים — אינם קרבים, שכן הקרבת הכבשים מעכבת את אכילת הלחמים, ו\u0003לשריפה אתיין\u0004 \u0005[הולכים],\u0006 לכך \u0003קמשמע לן\u0004 \u0005[הוא,\u0006 התנא במשנתנו, \u0005משמיע לנו]\u0006 ש\u0003בזו\u0004 בשתי הלחם \u0003יפה כח כהנים\u0004 מכח מזבח \u0003לעולם\u0004 (בכל האופנים), ואף כשאין עימם כבשים — הריהם כולם לכהנים, ואין למזבח בהם כלום.","\u0003כל המנחות הנעשות בכלי\u0004 (כמנחת המחבת והמרחשת), הריהן \u0003טעונות\u0004 (חייבות) \u0003שלשה מתנות\u0004 (נתינות) \u0003שמן\u0004 עליהן. ואלו הן (בסדר מן הסוף אל ההתחלה): ה\u0003יציקה, ו\u0004ה\u0003בלילה, ומתן שמן בכלי קודם לעשייתן\u0004. שנותן בתחילה מעט מן השמן אל תוך הכלי, ולאחריה נותן את הסולת אל תוך הכלי. ולאחר מכן נותן עוד מעט מן השמן, לצורך בלילת הסולת בשמן (\"בלילה\"). ולאחר הבלילה, לשים את הבצק במים פושרים, ואופים את המנחה עשר מצות (במחבת או במרחשת, כפי נדרו). ולאחר אפייתן ופתיתתם לפתיתים, הריהו נותן עליהם שוב שמן (\"יציקה\").","ונחלקו חכמים בדרך הבלילה, יש האומרים כי את המנחות הבאות \u0003חלות\u0004 מצות (מנחת מאפה תנור, מנחת מחבת, ומנחת מרחשת) \u0003בוללן\u0004 הכהן כשהן כבר חלות, שבלילתן נעשית בפתיתתן. אלו \u0003דברי רבי. ו\u0004אילו \u0003חכמים אומרים\u0004 כי אף במנחות הללו הבלילה נעשית בעודן \u0003סולת.\u0004 ועוד: \u0003החלות\u0004 של מנחת מאפה תנור \u0003טעונות\u0004 (חייבות) \u0003בלילה\u0004 בשמן. \u0003ו\u0004אולם מנחת \u0003רקיקין\u0004 — אינה חייבת בבלילה בשמן, אלא ב\u0003משיחה\u0004 של הרקיקים בשמן לאחר אפייתם. ו\u0003כיצד\u0004 הוא \u0003מושחן?\u0004 — בצורה שהיא \u0003כמין\u0004 (כעין) האות היוונית \u0003כי,\u0004 \u0003והשאר\u0004 מן השמן לאחר המשיחה, הריהם \u0003נאכלין לכהנים.\u0004","שנינו במשנתנו כי \"כל המנחות הנעשות בכלי טעונות שלושה מתנות שמן\", ושואלים: מלשון זו משמע שאין דין זה נוהג אלא במנחות הללו, ואם כן \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 היא באה? \u0003אמר רב פפא:\u0004 \u0003למעוטי\u0004 \u0005[למעט]\u0006 את \u0003מנחת מאפה\u0004 תנור, שאין כל מעשיה בכלי (שהרי היא נאפית בתנור), שאינה חייבת ביציקה.","שנינו במשנתנו דין שלש נתינות שמן במנחת מחבת ומנחת מרחשת, ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 ממשמעות הכתוב במנחת המרחשת \u0003\"ואם מנחת מרחשת קרבנך סלת בשמן תעשה\"\u0004 (ויקרא ב, ז), נראה שהסולת ניתנת בשמן, \u0003ו\u0004\u0003מלמד\u0004 הכתוב \u0003שטעונה\u0004 מנחת המרחשת בתחילה \u0003מתן שמן בכלי,\u0004 ולאחר מכן ניתנת הסולת על השמן הזה. ומאחר ונאמרה לשון \u0003\"קרבנך\"\u0004 במנחת המרחשת (\"ואם מנחת מרחשת קרבנך...\") וכן נאמרה הלשון \u0003\"קרבנך\"\u0004 במנחת המחבת (\"ואם מנחה על המחבת קרבנך סולת בלולה בשמן מצה תהיה\". שם ה), הרי זה בא \u0003ל\u0004למדנו ב\u0003גזירה שוה,\u0004"],["כי \u0003מה כאן\u0004 במנחת מרחשת — הריהי טעונה \u0003מתן שמן בכלי\u0004 קודם עשייתה (כדרך שנאמר בה \"ואם מנחת מרחשת קרבנך סולת בשמן תעשה\". ויקרא ב, ז). \u0003אף להלן\u0004 במנחת מחבת הנלמדת ממנה בגזירה שווה — יש \u0003מתן שמן בכלי. ו\u0004מצד אחר, \u0003מה להלן\u0004 במנחת מחבת — יש \u0003יציקה ובלילה\u0004 (שכן נאמר בה \"ואם מנחה על המחבת קרבנך סולת בלולה בשמן מצה תהיה. פתות אותה פתים ויצקת עליה שמן מנחה היא\". שם ה— ו), \u0003אף כאן\u0004 במנחת מרחשת — \u0003יש\u0004 \u0003יציקה ובלילה.\u0004","שנינו במשנתנו כי נחלקו רבי וחכמים בדרך בלילת המנחות הבאות חלות מצות (מנחת מאפה תנור, מנחת מחבת, מנחת מרחשת), אם כאשר הן \u0003חלות\u0004 הריהו \u0003בוללן\u0004 בפתיתיהן, אלו \u0003דברי רבי, ו\u0004אילו \u0003חכמים אומרים\u0004 שאף במנחות הללו נעשית הבלילה בעודן \u0003סולת.\u0004","ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 מה שנאמר במנחת מחבת \u0003\"סלת בלולה\u0004 בשמן\" (שם ה), \u0003מלמד ש\u0004מנחת המחבת \u0003נבללת\u0004 כשהיא עדיין \u0003סולת,\u0004 וכשיטת חכמים. \u0003רבי אומר:\u0004 כשהיא \u0003חלות\u0004 הריהו \u0003בוללן\u0004 בשמן ולא כשהיא עדיין סולת, וטעמו: \u0003ש\u0004כן \u0003נאמר\u0004 בפסוק הקודם, במנחת מאפה תנור \u0003\"חלות בלולות\"\u0004 (שם ד), ומכאן שמנחה הבאה חלות נבללת כשהיא חלות. \u0003אמרו לו\u0004 חכמים לרבי בפירכה על שיטתו: ומכאן אתה למד? \u0003והלא\u0004 אף \u0003לחמי תודה\u0004 הבאים עם בהמת השלמים \u0003נאמר בהן\u0004 כלשון הזו \u0003\"חלות\u0004 מצות בלולות בשמן... וסולת מורבכת חלות בלולות בשמן\" (שם ז, יב), \u0003ו\u0004הן ודאי נבללות בעודן סולת, שהרי \u0003אי אפשר לבוללן כשהן\u0004 כבר \u0003חלות, אלא\u0004 בעודן \u0003סולת!\u0004","ומסבירים: \u0003כיצד\u0004 בדיוק הוא \u0003עושה\u0004 לשיטת חכמים בבלילת המנחה? בתחילה הריהו \u0003נותן\u0004 מעט \u0003שמן בכלי\u0004 בו תיעשה המנחה \u0003קודם לעשייתן\u0004 (וזו היא נתינה ראשונה משלוש נתינות השמן), \u0003ו\u0004לאחר מכן הריהו \u0003נותנה\u0004 את הסולת לאותו כלי, \u0003ונותן\u0004 פעם נוספת מעט \u0003שמן עליה ובוללה\u0004 (וזו היא נתינה שניה מנתינות השמן). \u0003ולשה\u0004 במים פושרים, \u0003ואופה\u0004 אותה (במחבת או במרחשת, כפי נדרו) עשר מצות. \u0003ו\u0004לאחר שנאפו החלות, \u0003הריהו\u0004 \u0003פותתה\u0004 את החלה האפויה לפתיתים, \u0003ונותן עליה\u0004 שוב \u0003שמן\u0004 (וזו היא נתינה שלישית, \u0003וקומץ\u0004 ממנה את הקומץ העולה להקטרה.","ואילו לשיטת \u0003רבי\u0004 ה\u0003אומר\u0004 כי בהיותן \u0003חלות\u0004 הריהו \u0003בוללן, ש\u0004כן \u0003נאמר\u0004 בלחמי תודה \u0003\"חלות בלולת בשמן\", כיצד\u0004 הוא \u0003עושה\u0004 את הבלילה? בתחילה הריהו \u0003נותן שמן בכלי קודם לעשייתה\u0004 (וזו היא נתינה ראשונה של שמן), \u0003ונותנה\u0004 את הסולת באותו כלי, \u0003ולשה\u0004 במים פושרים, \u0003ואופה\u0004 אותה בכלי (כנדרו, מחבת או מרחשת), \u0003ופותתה\u0004 את החלה האפויה לפתיתים, \u0003ונותן עליה שמן\u0004 (וזו היא נתינת שמן שניה, הבלילה), \u0003ובוללה\u0004 בפתיתיה, \u0003וחוזר ונותן עליה שמן\u0004 (וזו היא נתינת שמן שלישית, היציקה), \u0003וקומץ\u0004 ממנה את קומצה, ומקטירה.","ומבררים: \u0003\"אי אפשר\u0004 לבוללן כשהן חלות אלא סולת\", \u0003דקאמרי ליה רבנן\u0004 \u0005[שאמרו לו חכמים]\u0006 \u0003לרבי\u0004 בענין לחמי התודה, כפירכה על הוכחתו, \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא,\u0004 מה ההסבר לדבריהם, מדוע אין אפשרות לבלול את לחמי התודה לאחר שנאפו? \u0003אמר ר' שמואל בר רב יצחק\u0004 בהסבר דברי חכמים: \u0003רביעית\u0004 לוג \u0003שמן\u0004 בלבד \u0003היא\u0004 הניתנת לעשר חלות ולעשרה רקיקים, ו\u0003היאך מתחלקת\u0004 מידה כה מועטה של שמן \u0003לכמה חלות\u0004 שתיבללנה בו? אלא ודאי הוא שהן נבללות כשהן עדיין סולת.","שנינו במשנה ש\u0003החלות\u0004 של מנחת מאפה תנור \u0003טעונות\u0004 (חייבות) \u0003בלילה\u0004 בשמן, \u0003ו\u0004אילו ה\u0003רקיקין\u0004 אינם חייבים בלילה בשמן, אלא \u0003ב\u0004\u0003משיחה\u0004 של שמן עליהם. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: מה שנאמר במנחת מאפה התנור \"וכי תקריב קרבן מנחה מאפה תנור סולת חלות מצות בלולות בשמן ורקיקי מצות משוחים בשמן\" (שם ב, ד), בא ללמדנו: דווקא כשהמנחה באה \u0003חלות\u0004 מצוותן שיהיו \u0003בלולות\u0004 בשמן, \u0003ולא\u0004 כשהיא באה \u0003רקיקין\u0004 יהיו \u0003בלולין\u0004 בשמן. ונצרכים אנו ללימוד זה, \u0003ש\u0004כן \u0003יכול\u0004 אדם לטעון: \u0003והלא דין\u0004 (קל וחומר) \u0003הוא: ומה חלות\u0004 הקלות בדינן מרקיקים, \u0003ש\u0004הרי \u0003אינן טעונות משיחה\u0004 בשמן כרקיקים — בכל זאת הריהן \u0003טעונות בלילה,\u0004 ה\u0003רקיקין\u0004 החמורים בדינם מן החלות, \u0003ש\u0004הרי הם \u0003טעונין משיחה\u0004 — \u0003אינו דין ש\u0004יהיו אף הם \u0003טעונין בלילה!\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) \u0003\"חלות\u0004 מצות \u0003בלולות\u0004 בשמן\" — דווקא חלות הן המצוות להיבלל בשמן, \u0003ולא רקיקין בלולין.\u0004","ומצד שני מה שנאמר \u0003\"ורקיקי מצות משוחים בשמן\" בא\u0004 ללמדנו שדווקא ה\u0003רקיקין\u0004 מצוותם שיהיו \u0003משוחין\u0004 בשמן, \u0003ולא\u0004 ה\u0003חלות משוחות\u0004 בשמן. ונצרכים אנו ללימוד זה, שכן \u0003יכול\u0004 אדם לטעון: \u0003והלא דין\u0004 (קל וחומר) \u0003הוא: ומה רקיקין\u0004 הקלים מחלות, \u0003ש\u0004הרי \u0003אינן טעונין בלילה\u0004 כחלות — בכל זאת הריהם \u0003טעונין משיחה.\u0004 מעתה, ה\u0003חלות\u0004 החמורות בדינן מרקיקים, \u0003ש\u0004הרי הן טעונות בלילה — \u0003אינו דין ש\u0004יהיו אף \u0003טעונות משיחה!\u0004 לכך \u0003תלמוד לומר\u0004 \"ורקיקי מצות משוחים בשמן\" — ללמדנו: דווקא ה\u0003רקיקין\u0004 הם המצווים להיות \u0003משוחים\u0004 בשמן, \u0003ולא\u0004 ה\u0003חלות\u0004 מצוות להיות \u0003משוחות\u0004 בשמן.","ושואלים על דרשה זו: \u0003מאי תלמודא\u0004 \u0005[מה הלימוד,\u0006 מה ההכרח לדרוש באופן זה\u0005],\u0006 והרי אפשר לומר שהכתוב \"בלולות\" מוסב על שניהם, כשם שהכתוב \"משוחים\" מוסב על שניהם! \u0003אמר רבא\u0004 בתשובה: אין מקום לומר כן, שהרי בכל המקומות בתורה \u0003לא לישתמיט\u0004 \u0005[לא נשמט,\u0006 סוטה\u0005]\u0006 הכתוב מדרכו, ותמיד נאמר במקרא שהחלות הן הבלולות, והרקיקים הם המשוחים, שאם לא כן \u0003ולכתוב\u0004 \u0005[ושיכתוב]\u0006 \u0003\"חלות משוחות ורקיקין בלולין\".\u0004","עוד שנינו במשנה בתיאור משיחתם של הרקיקים: \u0003כיצד מושחן? כמין כי, והשאר\u0004 (מן השמן) \u0003נאכל\u0004 לכהנים. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כמין כי\"? אמר רב כהנא\u0004 בהסבר דברי המשנה: \u0003כמין\u0004 האות \u0003כי\u0004 שבלשון \u0003יווני.\u0004","ועוד בענין בלילת החלות ומשיחת הרקיקים \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מנחה\u0004 (מאפה תנור) \u0003הבאה מחצה\u0004 (חמש) \u0003חלות ומחצה\u0004 (וחמישה) \u0003רקיקין\u0004 (כשיטת ר' שמעון, שאפשר להביא מנחת מאפה תנור אף באופן זה), כיצד נוהגים בשמן הניתן בהם? הריהו \u0003מביא לוג שמן,\u0004 כשיעור השמן הניתן לעשרון סולת, \u0003וחוצהו\u0004 לשני חצאי לוג. \u0003חציו\u0004 האחד מיועד \u0003לחלות, וחציו\u0004 האחר מיועד \u0003לרקיקין. ו\u0004את ה","\u0003חלות\u0004 \u0003בוללן\u0004 בשמן, כדינן. \u0003ו\u0004את ה\u0003רקיקין\u0004 \u0003מושחן\u0004 בשמן, כדינם. \u0003ומושח את הרקיק על פני כולו,\u0004 ולא כצורת האות היוונית כי. \u0003ו\u0004את \u0003שאר השמן\u0004 שנשאר אחרי המשיחה הריהו \u0003מחזירו ל\u0004בלילת ה\u0003חלות. ר' שמעון בן יהודה משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון אומר:\u0004 הריהו \u0003מושחן\u0004 לרקיקים \u0003כמין\u0004 האות היוונית \u0003כי, ושאר השמן נאכל לכהנים.\u0004","ובענין זה \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 עשרה \u0003רקיקין הבאים בפני עצמן\u0004 כמנחת מאפה תנור, כיצד נוהגים בנתינת השמן עליהם? \u0003מביא לוג שמן, ומושחן, ו\u0004מן הנשאר מהשמן הריהו \u0003חוזר ומושחן\u0004 שוב ושוב, \u0003עד שיכלה כל\u0004 ה\u0003שמן שבלוג.\u0004 ואילו \u0003ר' שמעון בן יהודה אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון: מושחן כמין כי, ושאר השמן נאכל לכהנים.\u0004","\u0003כל המנחות הנעשות בכלי טעונות פתיתה\u0004 (שבירה), וכדרך שתתבאר במשנה הבאה.","שנינו במשנתנו כי כל המנחות הנעשות בכלי טעונות פתיתה, ולשון זו באה למעט את הקדשים שאינם נעשים בכלי שאינם טעונים פתיתה. ומבררים: \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 באו הדברים? \u0003אמר רב פפא: למעוטי\u0004 \u0005[למעט]\u0006 את \u0003שתי הלחם ו\u0004את \u0003לחם הפנים,\u0004 שאין הם נאפים בכלי אלא בתנור, ואינם טעונים פתיתה.","למדנו למעלה, כי אין שתי הלחם ולחם הפנים טעונים פתיתה. ובענין זה מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: מה שנאמר בדין מנחת המחבת \u0003\"פתות אתה פתים\u0004 ויצקת עליה שמן \u0003מנחה\u0004 היא\" (ויקרא ב, ו) בלשון הפותחת בדין הפתיתה, ומסיימת בלשון כוללת \"מנחה היא\", מורה כי דין הפתיתה נוהג בכל מנחה, ולמדנו \u0003לרבות\u0004 דין \u0003כל המנחות ל\u0004חיוב \u0003פתיתה.\u0004 ומעתה יש מקום לומר: \u0003יכול\u0004 שמכאן \u0003אני מרבה אף\u0004 את \u0003שתי הלחם ולחם הפנים\u0004 לפתיתה? לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) באותו כתוב \"פתות \u0003אתה\"\u0004 — דווקא היא ולא אחרת, ולמעט את שתי הלחם ואת לחם הפנים.","ובדומה לכך, דורשים עוד: מה שנאמר בכתוב זה \u0003\"ויצקת\u0004 עליה \u0003שמן מנחה\u0004 היא\" — \u0003הרי בלשון הפותחת בדין היציקה, ומסיימת בלשון הכוללת\u0004 \"מנחה היא\", מורה כי דין היציקה נוהג בכל מנחה, ולמדנו מכאן \u0003לרבות\u0004 את דינן של \u0003כל המנחות ליציקה.\u0004 ומעתה יש מקום לומר: \u0003יכול ש\u0004מכאן \u0003אני מרבה אף\u0004 את \u0003מנחת מאפה\u0004 לדין היציקה? לכך \u0003תלמוד לומר\u0004 באותו כתוב \"ויצקת \u0003עליה שמן\"\u0004 כי דווקא היא ולא אחרת, ולמעט את מנחת המאפה מדין היציקה.","ועדיין יש מקום לשאול: האם \u0003אוציא\u0004 מכלל דין היציקה \u0003את החלות\u0004 של מנחת מאפה תנור, \u0003ולא אוציא\u0004 מכלל דין היציקה \u0003את הרקיקין?\u0004 לכך \u0003תלמוד לומר\u0004 אותו כתוב \"מנחה \u0003היא\",\u0004 למעט גם את הרקיקים מכלל דין היציקה. ושואלים: \u0003מאי תלמודא\u0004 \u0005[מה הלימוד,\u0006 מה ההכרח \u0005ללמוד באופן זה\u0006\u0005],\u0006 שבא המיעוט \"היא\" למעט רקיקים, שמא \u0003אימא\u0004 \u0005[אמור]\u0006 כי הריהו בא \u0003להוציא מנחת כהנים\u0004 מכלל דין היציקה!"],["\u0003אמר רבה\u0004 בתשובה: אין הכתוב הזה, שיש בו שני מיעוטים (\"עליה\", \"היא\") בא אלא למעט דבר הנצרך לשני מיעוטים, שכן יש בו שני מינים שונים. ו\u0003איזהו\u0004 ה\u0003דבר שצריך שני מיעוטין? הוי אומר: זו מנחת מאפה,\u0004 שיש בה גם חלות וגם רקיקים.","שנינו במשנה הקודמת כי כל המנחות הנעשות בכלי טעונות פתיתה. ומסבירים כיצד נעשית הפתיתה: \u0003מנחת ישראל,\u0004 כיצד פותתים אותה? \u0003קופל\u0004 (כופל) כל \u0003אחד\u0004 מן החלות לאחר אפייתן \u0003לשנים,\u0004 ושב \u0003ו\u0004כופל אותן \u0003שנים,\u0004 ובכך נכפלו \u0003לארבעה, ומבדיל\u0004 (מחלק, שובר) את החלה במקום בו נכפלה. וכיצד פותתים את \u0003מנחת כהנים?\u0004 — \u0003קופל\u0004 כל \u0003אחד\u0004 מן החלות \u0003לשנים,\u0004 ושב \u0003ו\u0004כופל אותן \u0003שנים\u0004 \u0003לארבעה\u0004 כבמנחת ישראל, ובכך הוא מקיים בה מצות פתיתה. \u0003ו\u0004אולם במנחת כהנים \u0003אינו מבדיל\u0004 (שוברה במקום שנכפלה), שכיון שאינה נקמצת (שהריהי עולה כולה למזבח), אין צריך הבדלה זו. ואילו \u0003ב\u0004\u0003מנחת כהן משיח\u0004 (הנקראת גם \"מנחת חביתין\", מנחתו של הכהן הגדול המוקרבת בכל יום) — \u0003לא היה מקפלה.\u0004 אלו דברי חכמים, ואילו \u0003ר' שמעון\u0004 חולק ו\u0003אומר\u0004 כי \u0003מנחת כהנים ומנחת כהן משיח אין\u0004 נוהגת \u0003בהן\u0004 כלל מצות \u0003פתיתה,\u0004 \u0003מפני שאין\u0004 נוהגת \u0003בהן\u0004 מצות \u0003קמיצה, ו\u0004כלל הוא: \u0003כל שאין בהן קמיצה\u0004 \u0003—\u0004 \u0003אין בהן פתיתה. וכולן,\u0004 כל המנחות הנזכרות למעלה הריהו \u0003פותתן\u0004 לפתיתים שגודלם \u0003כזיתים.\u0004","שנינו במשנתנו כי מנחת ישראל נכפלת אחד לשנים ושנים לארבעה ומבדיל, בעוד שמנחת כהנים נכפלת אחד לשנים ושנים לארבעה ואינו מבדיל בה. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: נאמר במנחת מחבת \"פתות אותה פתים ויצקת עליה שמן מנחה היא\" (ויקרא ב, ו), ומן האמור בה \u0003\"פתות\"\u0004 — \u0003יכול\u0004 אתה לומר כי הכוונה שיש לחלקה פעם אחת, \u0003לשנים\u0004 בלבד, ולא יותר. לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) הנוסף בכתוב זה \u0003\"פתים\"\u0004 — שיהיו השנים שנפתתו, נפתתים שוב, לארבעה. ועדיין יכול אתה לשאול: \u0003אי\u0004 \u0005[אם]\u0006 למדים אנו מהכתוב הנוסף \u0003\"פתים\"\u0004 שיש לחזור ולפותת את השנים שנפתתו כבר, \u0003יכול\u0004 יהא הדין שהריהו חוזר ופותת אותה עד ש\u0003יעשנה פירורין?\u0004 לכך \u0003תלמוד לומר\u0004 עוד בכתוב זה בין \"פתות\" לבין \"פתים\" \u0003\"אתה\"\u0004 (\"פתות אותה פתים\") — להדגיש: דווקא \u0003אותה\u0004 את המנחה עצמה הריהו פותת \u0003לפתיתים, ולא\u0004 עושה \u0003פתיתה לפתיתים.\u0004","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 יעשה? ב\u0003מנחת ישראל\u0004 — הריהו \u0003קופל אחד לשנים ושנים לארבעה, ו\u0004לאחר מכן הריהו \u0003מבדיל.\u0004 ואילו \u0003מנחת כהנים\u0004 היה מקפלה אחד לשנים ושנים לארבעה, ולא היה מבדיל. \u0003ו\u0004מנחת \u0003כהן משיח\u0004 — \u0003היה מקפלה\u0004 לשנים (שכן נאמר בה \"...תופיני מנחת פתים תקריב\". ויקרא ו, יד — שהריהי נפתתת). ותוהים על הנאמר בברייתא שאת מנחת כהן משיח היה מקפל לשנים, \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו]\u0006 במשנתנו במפורש כי \u0003לא היה מקפלה! אמר רבה\u0004 בתשובה: מה שנאמר במשנה שלא היה מקפלה, הכוונה היא ש\u0003אינו מקפלה לארבעה\u0004 (שהרי לא נאמר בה, כדרך שנאמר במנחת ישראל \"פתות... פתים\"), \u0003אבל מקפלה לשנים.\u0004","עוד שנינו במשנתנו כי \u0003ר' שמעון אומר\u0004 ש\u0003מנחת כהנים ומנחת כהן משיח אין בהן פתיתה,\u0004 ובהמשך הדברים נאמר כי בכל המנחות הטעונות פתיתה — פותתים אותן לפתיתים שיש בהם כשיעור זית לפחות. \u0003אמר רב יוסף: האי\u0004 \u0005[זו]\u0006 ה\u0003חביצא\u0004 (תבשיל קדירה שבו פירורי לחם) \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה פירורין\u0004 של לחם ששיעורם \u0003כזית\u0004 — \u0003מברכינן\u0004 \u0005[מברכים אנו]\u0006 \u0003עליה\u0004 לפני אכילתה \u0003\"המוציא לחם מן הארץ\",\u0004 כמו על הלחם. ואולם \u0003אי לית\u0004 \u0005[אם אין]\u0006 \u0003בה פירורין\u0004 ששיעורם \u0003כזית\u0004 — \u0003מברכינן\u0004 \u0005[מברכים אנו]\u0006 \u0003עליה\u0004 לפני אכילתה ברכת \u0003\"בורא מיני מזונות\".\u0004","\u0003אמר רב יוסף: מנא אמינא לה\u0004 \u0005[מנין אני אומר,\u0006 למד \u0005אותה]\u0006 הלכה? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 אדם מישראל שלא הקריב מנחה מימיו, ש\u0003היה עומד ו\u0004מוסר לכהן שיהיה \u0003מקריב\u0004 עבורו \u0003מנחות בירושלים,\u0004 הריהו \u0003אומר: \"ברוך\u0004 אתה ה' אלקינו מלך העולם, \u0003שהחיינו וקימנו\u0004 והגיענו לזמן הזה\". ולאחר שנקמצו המנחות, ואת שיירי המנחה \u0003נטלן\u0004 הכהן על מנת \u0003לאכלן,\u0004 בטרם שיאכלן \u0003אומר\u0004 הכהן: \"ברוך אתה ה' אלקינו מלך העולם \u0003המוציא לחם מן הארץ\". ו\u0004הרי \u0003תנן\u0004 \u0005[שנינו]\u0006 במשנתנו כי המנחות שנפתתות \u0003וכולן\u0004 ה\u0003פתיתים\u0004 הריהם \u0003ב\u0004שיעור \u0003כזית\u0004 לפחות. ומכאן, שכאשר יש פתיתי לחם בגודל של כזית מברכים עליהם \"המוציא\".","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף בקושיה על דבריו: \u0003ול\u0004דברי \u0003תנא דבי\u0004 \u0005[חכם בית\u0006 המדרש\u0005]\u0006 של \u0003ר' ישמעאל\u0004 ש\u0003אמר\u0004 כי כל המנחות שדינן בפתיתה, לאחר אפייתן הכהן \u0003מפרכן\u0004 (משברן) שוב ושוב, \u0003עד ש\u0004הוא \u0003מחזירן ל\u0004מצב שהיו בו בתחילתן, כשהן ב\u0003סלתן\u0004 (קמחן), האם \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003לא מברך\u0004 הכהן על אכילתן ברכת \u0003\"המוציא\"!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003הכי נמי\u0004 \u0005[אכן כך\u0006 הוא הדין \u0005גם כן]\u0006 לשיטת חכם זה, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 שאם \u0003ליקט\u0004 אדם \u0003מכולן,\u0004 מפירורים שאין בכל אחד מהם שיעור כזית, וצברם לכלל \u0003כזית, ואכלו\u0004 — הרי זו נחשבת כאכילה, ולכך \u0003אם\u0004 מפירורי \u0003חמץ הוא\u0004 ואכלם בפסח — הריהו \u0003ענוש כרת\u0004 על כך, ככל האוכל כזית חמץ בפסח. ו\u0003אם\u0004 מפירורי \u0003מצה הוא\u0004 זה — \u0003אדם יוצא בהן ידי חובתו\u0004 לאכול מצה \u0003בפסח.\u0004 הרי שנחשבים אף הפירורים שאין בהם כזית לענין אכילה, ומכאן שיש לברך אף עליהם \"המוציא\"!","ענה לו רב יוסף: \u0003הכא\u0004 \u0005[כאן],\u0006 בברייתא זו המלמדת שאף בפירורים שאין בהם כזית נחשבת האכילה, \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו]?\u0006 \u0003ב\u0004מקרה שלא רק ליקט את הפירורים לכדי שיעור כזית, אלא \u0003ש\u0004אף \u0003עירסן\u0004 (לש וצירף אותם לכלל יחידה אחת), ולכך נחשבת אכילתם כאכילה.","הקשה אביי על תירוץ זה: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא, יש להקשות: \u0003היינו דקתני עלה\u0004 \u0005[זהו,\u0006 אותו משפט מסייג \u0005ששנינו עליה,\u0006 כתוספת הסבר לאותה ברייתא\u0005]:\u0006 \u0003\"והוא\u0004 (אין דין זה אמור אלא בזמן) \u0003שאכלן\u0004 את אותם פירורים \u0003ב\u0004שיעור זמן שהוא \u0003כדי אכילת פרס\u0004 (מחצית ככר לחם)\". \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר, כהסברך \u0003ב\u0004מקרה \u0003שעירסן\u0004 את פירורי הלחם — \"והוא \u0003שאכלו\u0004 בכדי אכילת פרס\" \u0003מיבעי ליה\u0004 \u0005[נצרך היה לו]\u0006 לומר, שהרי המדובר בלחם אחד! \u0003אלא\u0004 יש לומר תירוץ אחר: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה עוסקים אנו]?\u0006 \u0003ב\u0004פירורי לחם ה\u0003בא מלחם גדול.\u0004 ולכן אף שכשלעצמם אין בהם חשיבות אכילה (בהיותם פחות מכשיעור כזית), ואולם משום שבאו מלחם גדול הריהם נחשבים ויש לברך עליהם ברכת \"המוציא\".","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה,\u0006 מה סוכם בה\u0005]\u0006 על ברכתה של החביצה שיש בה פירורים שהם פחות מכזית? \u0003רב ששת אמר:\u0004 מברכים על אכילתה ברכת \"המוציא\" \u0003אפילו\u0004 כשיש בה \u0003פירורין שאין בהן כזית. אמר רבא\u0004 בתוספת הגדרה: \u0003והוא\u0004 (ובלבד) \u0003דאיכא תוריתא\u0004 \u0003דנהמא עלייהו\u0004 \u0005[שיש תואר,\u0006 מראה \u0005של לחם עליהם,\u0006 על אותם פירורים שבה\u0005].\u0006"],["\u0003כל המנחות טעונות\u0004 (צריכות) שתיעשנה בהן \u0003שלש מאות\u0004 פעם \u0003שיפה\u0004 (שפשוף) ביד, \u0003וחמש מאות\u0004 פעם \u0003בעיטה\u0004 (הטחה בכח) בפס היד או אגרוף. ופעולות אלה, ה\u0003שיפה ו\u0004ה\u0003בעיטה\u0004 נעשות \u0003ב\u0004גרגרי ה\u0003חיטין\u0004 מהם יבוא הקמח למנחה, כדי להסיר את קליפותיהם קודם טחינתם לקמח. \u0003ו\u0004אילו \u0003ר' יוסי אומר:\u0004 השיפה והבעיטה נעשות \u0003בבצק,\u0004 שהן מועילות לגיבולו של הבצק. \u0003כל המנחות באות\u0004 כשמכל עשרון סולת עושים \u0003עשר\u0004 חלות או \u0003עשר\u0004 רקיקים, \u0003חוץ מלחם הפנים ו\u0004מ\u0003חביתי כהן גדול שהם באות\u0004 כשמכל עשרון עושים \u0003שתים עשרה\u0004 חלות או רקיקים, \u0003אלו\u0004 \u0003דברי ר' יהודה. ר' מאיר אומר:\u0004 המנחות \u0003כולם באות שתים עשרה\u0004 חלות, \u0003חוץ מ\u0004ארבעת מיני ה\u0003חלות\u0004 הבאות עם קרבן ה\u0003תודה,\u0004 \u0003ו\u0004חוץ משני מיני החלות של \u0003נזירות\u0004 \u0003שהן\u0004 (חלות התודה וחלות הנזיר) \u0003באות עשר עשר.\u0004","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא באיזה סדר נעשו השיפות והבעיטות: \u0003שף\u0004 פעם \u0003אחת,\u0004 ו\u0003בועט שתים.\u0004 חוזר ו\u0003שף שתים,\u0004 ו\u0003בועט שלש\u0004 פעמים. וכך היו עושים מאה פעמים, ובסך הכל היו שלוש מאות שיפות וחמש מאות בעיטות. ובענין השיפה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 האם השיפה היא פעולה המורכבת משני חלקים, \u0003אמטויי\u0004 \u0005[הולכת]\u0006 היד על פני הדבר המשתפשף \u0003ואתויי\u0004 \u0005[והשבתה]\u0006 שוב על פני אותו הדבר, שפעולה זו נחשבת מעשה שיפה \u0003חד\u0004 \u0005[אחד].\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 שיפה היא הולכת היד או השבת היד, ולכך \u0003אמטויי ואתויי\u0004 \u0005[הולכת והשבת]\u0006 היד תיחשבנה כ\u0003תרי\u0004 \u0005[שתי]\u0006 שיפות, \u0003מאי\u0004 \u0005[מה]\u0006 התשובה לכך? לשאלה זו לא נמצאה תשובה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 ללא \u0005פתרון.\u0006","שנינו במשנה כי לדעת חכמים ה\u0003שיפה ובעיטה\u0004 נעשות \u0003ב\u0004גרגרי ה\u0003חיטין,\u0004 ואילו \u0003ר' יוסי אומר\u0004 כי הן נעשות \u0003בבצק. איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]:\u0006 האם כוונת ר' יוסי לומר שרק \u0003בבצק\u0004 עושים את השיפות והבעיטות, \u0003ולא בחיטין,\u0004 וחולק לגמרי על דברי חכמים. \u0003או דלמא\u0004 \u0005[שמא]\u0006 אף ר' יוסי סבור שעושים את השיפות ואת הבעיטות בגרגרי החיטים, אלא שמוסיף הוא ש\u0003אף בבצק\u0004 עושים את השיפות ואת הבעיטות? \u0003ואומרים:\u0004 \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בענין זה: ה\u0003שיפה ו\u0004ה\u0003בעיטה\u0004 נעשות \u0003בחיטין, ר' יוסי אומר: שיפה ובעיטה בבצק,\u0004 ולא בחיטים.","שנינו במשנתנו כי לדעת ר' יהודה \u0003כל המנחות באות\u0004 במנין עשר, מלבד לחם הפנים וחביתי כהן גדול שכל אחד מאלה בא ב\u0003שתים עשרה\u0004 לחמים. ומסבירים את מקור הדברים: \u0003לחם הפנים\u0004 — שכן \u0003בהדיא כתיב ביה\u0004 \u0005[במפורש נאמר בו]\u0006 (\"ולקחת סולת ואפית אותה שתים עשרה חלות, שני עשרונים יהיה החלה האחת\". שם).","ו\u0003חביתי כהן גדול\u0004 באים שתים עשרה — שכן \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 מגזירה שווה של המלה \u0003\"חקה\"\u0004 האמורה בחביתי כהן גדול (\"והכהן המשיח תחתיו מבניו יעשה אותה חוק עולם לה' כליל תקטר\". שם ו, טו), והמלה \u0003\"חקה\"\u0004 שנאמרה ב\u0003לחם הפנים\u0004 (\"והיתה לאהרן ולבניו ואכלוהו במקום קדוש כי קודש קדשים הוא לו מאשי ה' חוק עולם\". שם כד, ט), וללמד כי כשם שלחם הפנים בא שנים עשר, אף חביתי כהן גדול באים שנים עשר.","במשנתנו שנינו כי לדעת ר' יהודה \u0003כל המנחות\u0004 כולן \u0003באות עשר עשר,\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שכך הוא? ומסבירים: \u0003גמר\u0004 \u0005[למד]\u0006 ר' יהודה \u0003מ\u0004השוואתן של כל המנחות ל\u0003לחמי תודה. מה להלן\u0004 \u0005[שם,\u0006 בלחמי תודה\u0005]\u0006 הריהם \u0003עשר, אף כאן\u0004 בשאר המנחות — הריהן באות \u0003עשר. ו\u0004מקשים: מדוע לא \u0003לילף\u0004 \u0005[שילמד]\u0006 את דין שאר המנחות \u0003מלחם הפנים,\u0004 ונאמר: \u0003מה להלן\u0004 \u0005[שם,\u0006 בלחם הפנים\u0005]\u0006 הריהם באים \u0003שתים עשרה, אף כאן\u0004 בשאר המנחות — \u0003שתים עשרה!\u0004","ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 יותר לומר כי \u0003מלחמי תודה הוה ליה למילף\u0004 \u0005[היה לו,\u0006 לר' יהודה, \u0005ללמוד]\u0006 את דין שאר המנחות. \u0003שכן\u0004 דומות שאר המנחות ללחמי תודה בצדדים מרובים, ואלו הם: \u0003יחיד\u0004 — שאר כל המנחות, כלחמי תודה, מובאות על ידי אדם יחיד. מה שאין כן לחם הפנים, שהיא מנחת ציבור; \u0003המתנדב\u0004 — שאר כל המנחות, כלחמי תודה, באות בנדבה. מה שאין כן לחם הפנים, שבא חובה; \u0003שמן\u0004 — שאר כל המנחות, כלחמי תודה, חייבות בנתינת שמן בהן. מה שאין כן בלחם הפנים. \u0003נפסל\u0004 — שאר כל המנחות, כלחמי תודה, נפסלות בלינה, מה שאין כן בלחם הפנים, שאינו נפסל בלינה (שהרי הוא מונח על שולחן הפנים שמונה ימים); \u0003שלא בשבת\u0004 — שאר כל המנחות, כלחמי תודה, אינן קרבות בשבת, ואילו לחם הפנים, דוחה את השבת; \u0003ושלא בטומאה\u0004 — שאר כל המנחות, כלחמי תודה, אינן קרבות בטומאה, מה שאין כן לחם הפנים, הקרב אף בטומאה. והרי איפוא לנו צדדי דמיון בין שאר המנחות ללחמי תודה שאינם בלחם הפנים, ולכן יש להעדיף ללמוד את שאר המנחות מלחמי תודה.","ודוחים: \u0003אדרבה\u0004 \u0005[להיפך]\u0006 אמור, ש\u0003מלחם הפנים הוה ליה למילף\u0004 \u0005[היה לו,\u0006 לר' יהודה, \u0005ללמוד]\u0006 את דינן של שאר המנחות, \u0003שכן\u0004 דומות הן ללחם הפנים בצדדים אחרים, ואלו הם: \u0003הקדש\u0004 — שאר כל המנחות, כלחם הפנים, הריהן קדשי קדשים. מה שאין כן לחמי תודה שהם קדשים קלים; \u0003ולבונה\u0004 — שאר המנחות, חייבות בנתינת לבונה עליהם. מה שאין כן לחמי תודה; \u0003מצה\u0004 — שאר כל המנחות, כלחם הפנים, באות אך כמצה, מה שאין כן בלחמי תודה, שיש מהם חמץ; \u0003ועצם\u0004 — שאר המנחות, באות כקרבן לעצמו, מה שאין כן לחמי תודה הבאים כנספח לקרבן התודה. וילמד איפוא ר' יהודה את דין שאר המנחות מלחם הפנים, ולא מלחמי תודה!","ומשיבים: מסתבר יותר ללמוד את דין שאר המנחות מלחמי תודה ולא מלחם הפנים, שכן \u0003הנך\u0004 \u0005[אלה]\u0006 צדדי הדמיון בין שאר המנחות לבין לחמי תודה \u0003נפישן\u0004 \u0005[מרובים]\u0006 יותר מצדדי הדמיון שבין שאר המנחות ללחם הפנים. ושואלים עוד על שיטת ר' יהודה: למדנו למעלה כי הדין שחביתי כהן גדול הריהם שנים עשר אינו נאמר במפורש בתורה, אלא נלמד בגזירה שווה (\"חק\" \"חק\") מן האמור בלחם הפנים.","\u0003ו\u0004יש לשאול: \u0003אי סבירא לן\u0004 \u0005[אם סבורים אנו]\u0006 כשיטה האומרת כי \u0003דבר הלמד\u0004 (שנלמד דינו) \u0003בגזירה שוה\u0004 מדבר אחר, הריהו \u0003חוזר ומלמד\u0004 דברים אחרים \u0003ב\u0004דרך \u0003בנין אב\u0004 (במה מצינו, בהשוואתם של אותם דברים אחרים לדינו של זה), ולכן אחר שנלמד בגזירה שווה דין חביתי כהן גדול שהם שנים עשר, \u0003נילף\u0004 \u0005[נלמד]\u0006 את דינן של שאר מנחות \u0003מחביתי כהן גדול,\u0004 ונאמר כך: \u0003מה להלן\u0004 \u0005[שם,\u0006 בחביתי כהן \u0003גדול\u0004\u0005]\u0006 — הריהם באים \u0003שתים עשרה. אף כאן\u0004 (בשאר מנחות) — הריהן באות \u0003שתים עשרה!\u0004","ודוחים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 יותר לומר כי \u0003מלחמי תודה הוה ליה למילף\u0004 \u0005[היה לו,\u0006 לר' יהודה, \u0005ללמוד]\u0006 את דין שאר המנחות, ולא מחביתי כהן גדול. \u0003שכן\u0004 דומות שאר המנחות ללחמי תודה בצדדים רבים ואלו הם: \u0003הדיוט\u0004 — שאר כל המנחות, כלחמי תודה, באות אף על ידי כהן הדיוט, מה שאין כן מנחת חביתין שאינה באה אלא על ידי כהן גדול; \u0003שהתנדב\u0004 — שאר כל המנחות, כלחמי תודה, באות בנדבה, מה שאין כן מנחת חביתין שהיא באה כחובה; \u0003חצאין\u0004 — שאר כל המנחות, כלחמי תודה, באות כדבר שלם, מה שאין כן חביתי כהן גדול הבאים מחציתם בבוקר ומחציתם בערב;","\u0003לפיגול\u0004 — בשאר כל המנחות, כמו בלחמי תודה, נוהג דין פיגול, מה שאין כן בחביתי כהן גדול, שאין נוהג בה דין פיגול (שאין דין פיגול בקדשים שאינם ניתרים לאכילה); \u0003שלא בשבת\u0004 — שאר כל המנחות, כלחמי תודה, אינן באות ביום השבת, מה שאין כן חביתי כהן גדול הקרבים אף בשבת; \u0003ושלא בטומאה\u0004 — שאר כל המנחות, כלחמי תודה, אינן קרבות בטומאה, מה שאין כן חביתי כהן גדול הקרבים אף בטומאה.","ודוחים: \u0003אדרבה\u0004 \u0005[להיפך]\u0006 אמור, שדווקא \u0003מחביתי כהן גדול,\u0004 ולא מלחמי תודה, \u0003הוה ליה למילף\u0004 \u0005[היה לו,\u0006 לר' יהודה, \u0005ללמוד]\u0006 את דין שאר מנחות\u0005,\u0006 \u0003שכן\u0004 יש צדדי דמיון בין שאר המנחות ולחביתי כהן גדול, שאינם בלחמי תודה, ואלו הם: \u0003עשרון\u0004 — שאר המנחות, כחביתי כהן גדול, באות מעשרון סולת אחד. מה שאין כן לחמי תודה הבאים מכמה עשרונים; \u0003כלי\u0004 — שאר כל המנחות, כחביתי כהן גדול, מתקדשות בכלי שרת. מה שאין כן לחמי תודה המתקדשים בשחיטת קרבן התודה; \u0003הקדש\u0004 — שאר כל המנחות, כחביתי כהן גדול, הריהן קדשי קדשים. מה שאין כן לחמי תודה, שהם קדשים קלים; \u0003ולבונה\u0004 — בשאר כל המנחות, כבחביתי כהן גדול, ניתנת לבונה, מה שאין כן בלחמי תודה:","\u0003מצה\u0004 — שאר כל המנחות, כחביתי כהן גדול, באות כמצה ולא כחמץ. מה שאין כן לחמי תודה שיש בהם הבאים חמץ. \u0003ועצם\u0004 — שאר כל המנחות, כחביתי כהן גדול, באות מחמת עצמם, ולא כנספחות לקרבן אחר. מה שאין כן לחמי תודה הבאים אגב קרבן התודה; \u0003הגשה\u0004 — שאר כל המנחות, כבחביתי כהן גדול, יש להגישן אל הקרן הדרומית מערבית של המזבח. מה שאין כן בלחמי תודה; \u0003ואישים\u0004 — משאר כל המנחות \u0003מקטירים קומץ על אש המזבח, וכן מוקטרים חביתי כהן גדול. מה שאין כן לחמי תודה הנאכלים לכהנים;\u0004 \u0003ו\u0004הרי \u0003הני\u0004 \u0005[אלה]\u0006 צדדי הדמיון שבין שאר כל המנחות לחביתי כהן גדול הינם \u0003נפישן\u0004 \u0005[מרובים]\u0006 יותר מצדדי הדמיון שבין שאר המנחות ללחמי תודה, ויש איפוא ללומדן מחביתי כהן גדול ולא מלחמי תודה!","ודוחים: מכל מקום, השיקול שיש ללמוד את דין שאר מנחות, שהן קרבנו של מי שהוא \u0003הדיוט\u0004 (שאינו כהן גדול) \u0003מ\u0004דינם של לחמי תודה, שאף הם קרבנו של \u0003הדיוט\u0004 — \u0003עדיף ליה\u0004 \u0005[לו]\u0006 לר' יהודה, ולכך למד את דינן דווקא מלחמי תודה.","שנינו במשנתנו כי \u0003ר' מאיר\u0004 חולק על ר' יהודה ו\u0003אומר\u0004 שכל המנחות \u0003כולן באות שתים עשרה,\u0004 ואומרים: אפשר להסביר בשני אופנים \u0003מאי קסבר\u0004 \u0005[מה הוא,\u0006 ר' מאיר, \u0005סבור],\u0006 \u0003אי סבירא ליה\u0004 \u0005[או\u0006 ש\u0005סבור הוא]\u0006 כעיקרון כולל כי \u0003דבר הלמד בגזירה שוה\u0004 (ובענייננו, חביתי כהן גדול, הנלמדים בגזירה שווה מלחם הפנים, הבאים בשנים עשר לחמים) \u0003חוזר ומלמד\u0004 דברים אחרים, \u0003ב\u0004דרך הלימוד של \u0003בנין אב\u0004 — \u0003יליף\u0004 \u0005[לומד]\u0006 ר' מאיר את דין שאר המנחות שאף הן באות שתים עשרה \u0003מחביתי\u0004 ה\u0003כהן גדול\u0004 הבאים שנים עשר. ומעדיף ר' מאיר ללמוד את דין שאר המנחות מחביתי כהן גדול ולא מלחמי תודה, משום שצדדי הדמיון בין שאר המנחות ובין \u0003הני\u0004 \u0005[אלה,\u0006 חביתי כהן גדול\u0005],\u0006 הם יותר \u0003נפישן\u0004 \u0005[מרובים].\u0006 וכדרך שהוסבר למעלה.","\u0003ו\u0004\u0003אי סבירא ליה\u0004 \u0005[אם סבור הוא,\u0006 ר' מאיר\u0005]\u0006 ש\u0003דבר הלמד בגזירה שוה אינו חוזר ומלמד\u0004 בדרך הלימוד של \u0003בנין אב\u0004 — \u0003יליף\u0004 \u0005[לומד]\u0006 ר' מאיר את שאר מנחות, שאף הן קרבות בשנים עשר לחמים, \u0003מלחם הפנים\u0004 הבא בשתים עשרה לחמים, משום שלימוד של \u0003הקדש\u0004 (קדשי קדשים, שאר מנחות) \u0003מהקדש\u0004 (מקדשי קדשים, לחם הפנים) \u0003עדיף ליה\u0004 \u0005[לו]\u0006 ללמוד מאשר ללמוד את דין שאר מנחות שהן קדשי קדשים מלחמי תודה שהם קדשים קלים.","שנינו במשנתנו שלשיטת ר' מאיר כל המנחות באות שתים עשרה לחמים, \u0003חוץ מלחמי תודה ו\u0004חוץ מהמנחה אותה מביא הנזיר בתום ימי ה\u0003נזירות ש\u0004שתי אלה בלבד \u0003הן באות עשר עשר,\u0004 ולא שתים עשר. ומסבירים מה מקור הדברים: \u0003לחמי תודה\u0004 — \u0003בהדיא כתיב בהו\u0004 \u0005[במפורש נאמר בהם]\u0006 שכך דינם. שכן נלמד דינם מגזירה שווה של המלה \"תרומה\" האמורה בלחמי תודה (\"והקריב ממנו אחד מכל קרבן תרומה לה' \". ויקרא ז, יד), ובתרומת מעשר (\"והרמותם ממנו תרומת ה' מעשר מן המעשר\". במדבר יח, כו).","וללמדנו: כשם שתרומת מעשר באה כאחד מעשרה — אף לחמי תודה באים בעשרה. והמקור לכך שלחמי ה\u0003נזירות\u0004 באים עשרה — שכן \u0003אמר מר\u0004 \u0005[החכם]\u0006 על הכתוב בלחמי תודה הבאים עם קרבן התודה (שהריהו מכלל השלמים) \"על חלות לחם חמץ יקריב קרבנו על זבח תודת שלמיו\" (ויקרא ז, יג). ובאה המלה \u0003\"שלמיו\"\u0004 — \u0003לרבות\u0004 (להוסיף) לדין זה שהלחמים באים בעשרה אף ב\u0003שלמי נזיר.\u0004","כיון שהוזכר דינם של לחמי תודה, מביאים עוד מה ש\u0003אמר רב טובי בר קיסנא, אמר שמואל\u0004 בענין מספר \u0003לחמי\u0004 ה\u0003תודה:\u0004 אף שדינם שהם באים עשרה לחמים, ובארבעה מינים שונים (עשרה — חמץ, ובמצה שלושה מינים: עשרה — חלות מצות, עשרה — רקיקי מצות, ועשרה — רבוכה), אם אירע \u0003שאפאן\u0004 כ\u0003ארבע חלות\u0004 גדולות, שכל אחת מהן שיעורה כשיעור עשרה לחמים — \u0003יצא\u0004 בכך ידי חובתו. ושואלים על כך: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 שיביא \u0003ארבעים\u0004 לחמים, והוא לא הביא אלא ארבעה! ומשיבים: הבאת ארבעים לחמי תודה אינה אלא \u0003למצוה,\u0004 אבל אינה מעכבת.","ושואלים עוד: \u0003והא בעי אפרושי\u0004 \u0005[והרי צריך\u0006 המביא לחמי תודה \u0005להפריש]\u0006 \u0003תרומה מינייהו\u0004 \u0005[מהם,\u0006 מכל אחד מארבעת המינים שבתודה\u0005]\u0006 אחד מעשרה (ככתוב \"והקריב ממנו אחד מכל קרבן תרומה לה' \"), ואילו המביא ארבעה לחמים, כיצד יפריש אחד מעשרה? \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שהוא \u0003מפריש\u0004 חתיכה מהלחם שהיא בשיעור עשירית \u0003מכל חדא וחדא\u0004 \u0005[אחד ואחד]\u0006 מארבעת הלחמים הללו — הלא \u0003\"אחד\"\u0004 (\"והקריב ממנו אחד מכל קרבן תרומה לה' \") \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 והרי זה מורה \u0003שלא יטול\u0004 לתרומה לחם \u0003פרוס,\u0004 אלא לחם שלם! ומשיבים: מדובר באופן \u0003דאפרשינהו\u0004 \u0005[שהפריש אותן,\u0006 את התרומות מארבעת הלחמים\u0005]\u0006 כבר \u0003ב\u0004זמן ה\u0003לישה,\u0004 ובשלב זה אין זה נחשב כנטילה מן הפרוס.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת שמואל זו ממה ששנינו בברייתא: \u0003כל המנחות שריבה במדת חלתן, או שמיעט במדת חלתן\u0004 — הרי אלה \u0003כשרות\u0004 להקרבה. \u0003חוץ מלחם הפנים\u0004 (שחייבים לבוא דווקא בשנים עשר לחמים), \u0003וחביתי כהן גדול\u0004 (שאף הם חייבים לבוא בשנים עשר לחמים), \u0003ולחמי תודה\u0004 (שחייבים לבוא מעשרה עשרה לחמים), \u0003ו\u0004לחמי \u0003נזירות\u0004 (הבאים עשרה לחמים). ובכלל המנין המעכב נזכרו בברייתא זו אף לחמי תודה, שאם באו פחות מעשרה — אין הם כשרים, ושלא כדברי שמואל! ומתרצים: אין להקשות על שמואל מדברי ברייתא זו, שכן \u0003הוא\u0004 (שמואל),"],["","ש\u0003אמר\u0004 שאף לחמי תודה שבאו כארבעה לחמים הריהם כשרים, סבור \u0003כי האי\u0004 \u0005[כמו זה]\u0006 ה\u0003תנא\u0004 שדבריו מובאים בברייתא אחרת. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כל המנחות שריבה במדת חלתן או שמיעט במדת חלתן\u0004 — הריהן \u0003כשרות, חוץ מלחם הפנים וחביתי כהן גדול\u0004 בלבד, שאם ריבה בהם או מיעט בהם הריהם פסולים. \u0003ויש אומרים\u0004 כי הוא הדין לפסול בריבוי או במיעוט \u0003אף\u0004 ב\u0003לחמי תודה ו\u0004ב\u0003נזירות.\u0004 הרי שלדברי התנא הראשון בברייתא זו, אין נפסלים לחמי תודה שמיעט בהם, וסבור שמואל כתנא זה. ועוד \u0003אמר רב הונא: מנחת מאפה שאפה\u0004 אותה \u0003חלה אחת,\u0004 ולא הביאה במספר הראוי — \u0003יצא\u0004 ידי חובתו. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם,\u0006 מה מקור הדבר\u0005]?\u0006 — שכן נאמר בדין מנחת מאפה תנור \"וכי תקריב קרבן מנחת מאפה תנור סולת חלות \u0003מצת\u0004 בלולות בשמן...\" (ויקרא ב, ד). ומכיון \u0003ש\u0004\u0003\"מצות\"\u0004 בכתיב חסר \u0003כתיב\u0004 \u0005[כתוב],\u0006 שיכולה להיקרא גם בלשון יחיד, הרי זה להורות, שגם אם באה כמצה אחת, הריהי כשרה.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על הסבר זה\u0005]\u0006 \u0003רב פפא:\u0004 לפי דברים אלה, \u0003טעמא\u0004 \u0005[הטעם]\u0006 להכשיר את מנחת המאפה הבאה כחלה אחת, הריהו רק משום \u0003דכתיב\u0004 \u0005[שכתוב]\u0006 \u0003\"מצת\"\u0004 בכתיב חסר. ומכאן נסיק: \u0003הא\u0004 \u0005[הרי]\u0006 אם היה \u0003כתיב\u0004 \u0005[כתוב]\u0006 \u0003\"מצות\"\u0004 בכתיב מלא — \u0003לא\u0004 היה דינה כך. \u0003ו\u0004אולם \u0003הא\u0004 \u0005[הרי]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003לחמי תודה דכתיב\u0004 \u0005[שכתוב]\u0006 בהם \u0003\"מצות\"\u0004 בכתיב מלא (\"והקריב על זבח התודה חלות מצות בלולות בשמן\", שם ז, יב), \u0003ו\u0004בכל זאת \u0003אמר\u0004 \u0003רב טובי בר קיסנא, אמר שמואל\u0004 ש\u0003לחמי תודה שאפאן ארבע חלות\u0004 — \u0003יצא\u0004 בכך ידי חובתו! ומשיבים: אין להקשות מדברי שמואל על דברי רב הונא, שכן ההלכה \u0003ההיא\u0004 \u0005של שמואל\u0006 \u0003פליגא\u0004 \u0005[חולקת]\u0006 על דברי רב הונא ולשיטתו אכן לחמי תודה שאפאן ארבע חלות לא יצא.","\u0003העומר\u0004 הקרב בחג הפסח, בט\"ז בניסן, מיבול השעורים החדש, \u0003היה בא\u0004 (נעשה) מסולת בשיעור \u0003עשרון\u0004 שהיה נלקח לאחר שניפוהו והכינוהו \u0003מ\u0004תוך תבואת שעורים בשיעור \u0003שלש סאין.\u0004 בעוד ש\u0003שתי הלחם\u0004 הקרבות בחג השבועות מתבואת החיטים החדשה, היו נעשים \u0003שתי עשרונים\u0004 שהיו נלקחים \u0003מ\u0004תוך תבואת חיטים בשיעור \u0003שלש סאין.\u0004 ואילו \u0003לחם הפנים\u0004 הקרב בכל שבוע ושבוע, ביום השבת, ובו שנים עשר לחמים, היה נעשה מסולת בשיעור \u0003עשרים וארבע עשרונים,\u0004 שהיו נלקחים \u0003מ\u0004תוך \u0003עשרים וארבע סאין.\u0004 שנינו במשנתנו כי את העומר ששיעורו היה \u0003עשרון סולת היו מביאים מתוך שלוש סאים של שעורים. ושואלים:\u0004 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 נזקקים למידה כה רבה של שעורים (שלוש סאים), לצורך עשרון אחד בלבד? ומשיבים: \u0003כיון\u0004 שהעומר מן היבול ה\u0003חדש\u0004 הוא \u0003אתי\u0004 \u0005[בא],\u0006 ויש ביבול החדש סובין מרובים שצריך להוציאם כדי שתהיה סולת נקיה, \u0003ו\u0004כמו כן, \u0003משעורין\u0004 הוא \u0003אתי\u0004 \u0005[בא],\u0006 ולא מחיטים, והשעורים הריהם חומר גס יותר, משום כך, \u0003עשרון מובחר לא אתי\u0004 \u0005[לא בא]\u0006 \u0003אלא מ\u0004תוך \u0003שלש סאין,\u0004 ולא מפחות. ומה טעם \u0003שתי הלחם\u0004 ששיעורם \u0003שתי עשרונות\u0004 מובאים \u0003מ\u0004תוך \u0003שלש סאין\u0004 — \u0003כיון\u0004 ש\u0003מחיטין\u0004 הם \u0003אתיין\u0004 \u0005[באים],\u0006 שמשובחים הם מהשעורים, \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003מ\u0004היבול \u0003ה\u0004\u0003חדש אתיין\u0004 \u0005[באים]\u0006 וצריכים הם ניפוי, ואולם כמות הסובין בהם פחותה מזו של השעורים, ולכך \u0003שתי עשרונות\u0004 מובחרים \u0003אתו\u0004 \u0005[באים]\u0006 \u0003משלש סאין.\u0004 ו\u0003לחם הפנים\u0004 שיש בו \u0003עשרים וארבעה עשרונות,\u0004 מובא \u0003מעשרים וארבעה סאין, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003כיון\u0004 ש\u0003מחיטין אתו\u0004 \u0005[באים],\u0006 \u0003ו\u0004כמו \u0003כן\u0004 \u0003מ\u0004היבול ה\u0003ישן\u0004 (שאין בו סובין כה רבים, כבחדש) \u0003אתו\u0004 \u0005[\u0006הם \u0005באים],\u0006 לכך \u0003עשרון מובחר אתי\u0004 \u0005[בא]\u0006 \u0003מסאה\u0004 אחת בלבד.","","","","שנינו במשנתנו מספר העשרונים המובאים בעומר ובשתי הלחם ובלחם הפנים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003כל המנחות\u0004 \u0003שריבה במדת עשרונן\u0004 (שמדדן במידת עשרון גדול) \u0003או שמיעט במדת עשרון\u0004 (שמדדן במידת עשרון קטן) — הרי אלה \u0003פסולות.\u0004 ואולם אם \u0003ריבה במדת סאין שלהן,\u0004 כגון שהביא את העשרון לעומר \u0003מארבע סאים ולא משלוש,\u0004 \u0003או שמיעט במדת סאין שלהן,\u0004 כגון שהביא עשרון סולת לעומר משתי סאים בלבד — הרי אלה \u0003כשרות,\u0004 אם עשרון הסולת עשוי ומנופה כהלכתו, שכן מספרן של הסאים אינו אלא לכתחילה, ואינו מעכב.","ובתיאור מעשה העומר, לאחר שנקצרו שלוש סאים שעורים מן היבול החדש, ונטחנו לקמח: \u0003העומר היה\u0004 עשרון הקמח שהתקבל \u0003מנופה בשלש עשרה נפה,\u0004 שכל אחת שונה מחברתה. והקמח שהתקבל מן הנפה האחרונה, היה משמש לעומר. ואילו שני העשרונים קמח ששימשו ל\u0003שתי הלחם\u0004 היו מנופים \u0003בשתים עשרה\u0004 נפות, \u0003ו\u0004עשרים וארבעת העשרונים קמח ששימשו לשנים עשר \u0003לחם הפנים\u0004 היו מנופים \u0003באחת עשרה\u0004 נפות. \u0003ר' שמעון\u0004 חולק ו\u0003אומר\u0004 כי \u0003לא היה להן\u0004 (לכל אלה) \u0003קצבה\u0004 (מספר קצוב, קבוע) של נפות, \u0003אלא\u0004 את כל אחד מאלה היו מנפים עד שיהיה \u0003סולת מנופה כל צרכה,\u0004 ואותה \u0003היה מביא, ש\u0004כן \u0003נאמר\u0004 במעשה לחם הפנים \u0003\"ולקחת סלת ואפית אתה\"\u0004 (ויקרא כד, ה) לומר: \u0003עד שתהא מנופה כל צרכה.\u0004","ועוד בדרך הניפוי של קמח העומר ושתי הלחם ולחם הפנים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: בתחילה היו משתמשים \u0003ב\u0004נפה \u0003דקה\u0004 (בעלת חורים קטנים), ולאחר מכן היו נוטלים את הקמח שהתקבל מניפוי זה ומנפים אותו \u0003ב\u0004נפה \u0003גסה\u0004 (בעלת חורים גדולים יותר). ושוב היו מנפים את הקמח שהתקבל מנפה זו, \u0003ב\u0004נפה שהיא \u0003דקה\u0004 יותר מהנפה הדקה הראשונה, ולאחר מכן חוזרים ומנפים את הקמח שהתקבל ממנה \u0003ב\u0004נפה \u0003גסה\u0004 שהיא דקה יותר מהנפה הגסה הראשונה. וכך היו ממשיכים מדקה לגסה, ומגסה לדקה. \u0003ר' שמעון בן אלעזר אומר: שלש עשרה נפות היו במקדש, זו למעלה\u0004 (קודמת) \u0003מזו וזו למעלה מזו.\u0004 הנפה ה\u0003עליונה קולטת\u0004 (אוספת אליה) את ה\u0003סובין\u0004 (חלקי הגרעין המכילים את החומרים הנספחים לקמח הטהור), ואילו הנפה ה\u0003תחתונה קולטת\u0004 את ה\u0003סולת\u0004 (הקמח המובחר). ועוד בדרך הניפוי, שנינו במשנתנו כי \u0003ר' שמעון\u0004 חולק על דעת חכמים ו\u0003אומר\u0004 כי \u0003לא היה להן קצבה,\u0004 אלא היו מנפים ככל שנצרכו עד שהיה הקמח מנופה כל צרכו. ולמד זאת ר' שמעון מן האמור בלחם הפנים \"סולת ואפית אותה\", ועוד בדרשת כתוב זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שאמר הכתוב \"ולקחת \u0003סולת ואפית אותה\"\u0004 — \u0003מלמד\u0004 שהתבואה לצורך לחם הפנים \u0003נקחת\u0004 (נקנית) מן הסוחרים בשוק, כשהיא כבר \u0003סולת,\u0004","","\u0003ומנין\u0004 לנו \u0003ש\u0004היא נקנית \u0003אפילו\u0004 בשלב מוקדם יותר, כשהתבואה עדיין \u0003חיטין? תלמוד לומר\u0004 (מלמדנו האמור) \u0003\"ולקחת\"\u0004 — \u0003מכל מקום\u0004 (בכל אופן). ומעתה יש מקום לשאול: \u0003יכול\u0004 יהא \u0003אף בשאר מנחות\u0004 הדין \u0003כן\u0004 שיקנה תבואתו בעודה חיטים מן השוק? \u0003תלמוד לומר\u0004 בכתוב זה, בלשון מיעוט \u0003\"אתה\"\u0004 — דווקא לחם הפנים הוא הנקנה מהשוק בעודו חיטים, ולא מנחה אחרת. וטעם הדבר: \u0003מפני החיסחון\u0004 (החסכון). וכדרך ש\u0003אמר ר' אלעזר\u0004 בפירוש דבר זה: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מפני החיסחון\"? אמר ר' אלעזר: התורה חסה על ממונן של ישראל\u0004 שלא יתבזבז, ולכך הקילה עליהם לקנות ללחם הפנים (שהוא בא בכמות מרובה, עשרים וארבעה עשרונים, בכל שבוע) אף מן החיטים מידי הסוחרים בשוק. מה שאין כן בשאר מנחות, הבאות ממעט סולת שלא ראו חכמים צורך להקל. ומסבירים: \u0003היכא רמיזא\u0004 \u0005[היכן נרמז]\u0006 עקרון זה, שהתורה חסה על ממונם של ישראל? \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 לאחר מות מרים, בהיות ישראל במדבר בצמא, \u0005\"ודברתם אל הסלע לעיניהם ונתן מימיו והוצאת להם מים מן הסלע\u0006 \u0003והשקית את העדה ואת בעירם\"\u0004 (במדבר כ, ח) — שאף להשקייתו של הצאן נזקק נס הוצאת המים מן הסלע.","","","הסולת לארבעים לחמי \u0003התודה היתה באה\u0004 בשיעור של \u0003חמש סאין ירושלמיות, שהן\u0004 שוות בגודלן ל\u0003שש\u0004 סאים \u0003מדבריות\u0004 (שנהגו בהיות בני ישראל במדבר סיני) ובירושלים שינו את המדות והוסיפו במדתן. ומפרטים עוד את הרכב מידת הסולת שבלחמי התודה: יש בשש הסאים (המדבריות) \u0003שתי איפות,\u0004 ו\u0003האיפה\u0004 יש בה \u0003שלש סאין,\u0004 ובכל איפה יש עשרה עשרונים. נמצא איפוא כי בשתי האיפות יש \u0003עשרים עשרון.\u0004 ומתוך עשרים העשרונים הללו, \u0003עשרה\u0004 מהם מיועדים \u0003ל\u0004עשר חלות ה\u0003חמץ, ועשרה\u0004 העשרונים האחרים מיועדים \u0003ל\u0004שלושים לחמי ה\u0003מצה\u0004 השונים, המורכבים משלשה מינים (חלות, רקיקים, ורבוכה. כל אחד מהם בא בעשרה."],["ומפרטים: \u0003עשרה\u0004 עשרונים מיועדים \u0003ל\u0004עשר החלות הבאות \u0003חמץ\u0004 שבארבעים לחמי התודה, \u0003עשרון\u0004 אחד \u0003ל\u0004הכנת כל \u0003חלה. ועשרה\u0004 העשרונים האחרים מיועדים \u0003ל\u0004חלות הבאות \u0003מצה, ו\u0004כיון ש\u0003ב\u0004חלות הבאות כשהן \u0003מצה\u0004 היו \u0003שלש מינין\u0004 (שכל אחד מהם עשוי מעשרה לחמים), שהם: \u0003חלות\u0004 מצות, \u0003רקיקין\u0004 מצות, \u0003ו\u0004לחמי \u0003רבוכה\u0004 (החלוטה במים רותחים), \u0003נמצאו\u0004 איפוא כי בסך \u0003הכל\u0004 \u0003שלשה עשרונים ושליש\u0004 עשרון סולת מיועדים \u0003לכל מין ומין\u0004 משלוש המינים הללו, \u0003ו\u0004לפיכך שיעור הסולת להכנת \u0003שלש חלות\u0004 מצות עולה \u0003ל\u0004כלל \u0003עשרון\u0004 אחד (שכל חלה משלושים החלות הללו נעשית משליש עשרון).","עד כאן תיאור \u0003שיעורי הסולת הבאה בלחמי תודה, על פי המידות המדבריות (שהיו חלוקות לעשרונים),\u0004 \u0003ו\u0004אילו \u0003במדה\u0004 ה\u0003ירושלמית\u0004 (שהיתה חלוקה לקבים) היו שתי האיפות שוות לחמש סאים ירושלמיות, וכל סאה ירושלמית הריהי בת ששה קבים. נמצא איפוא כי חמש הסאים הירושלמיות סולת שהובאו ללחמי התודה, \u0003היו שלשים קב. חמשה עשר\u0004 מהם מיועדים \u0003ל\u0004חלות התודה הבאות \u0003חמץ, וחמשה עשר\u0004 מהם \u0003ל\u0004חלות התודה הבאות \u0003מצה.\u0004 ומעתה נמצא כי ב\u0003חמשה עשר\u0004 הקבים המשמשים \u0003ל\u0004חלות הבאות \u0003חמץ,\u0004 כל \u0003קב ומחצה\u0004 משמש \u0003ל\u0004הכנת \u0003חלה\u0004 חמץ אחת. \u0003ו\u0004\u0003חמשה עשר\u0004 קבים משמשים \u0003ל\u0004הכנת שלושים החלות הבאות \u0003מצה. ו\u0004הרי \u0003ב\u0004שלושים חלות ה\u0003מצה\u0004 יש \u0003שלש מינין,\u0004 שהם \u0003חלות ורקיקין ורבוכה, נמצאו חמשת קבין\u0004 סולת \u0003לכל מין ומין. ו\u0004מכיון שבכל מין ומין יש עשרה לחמים, נמצא כי שיעור הסולת ממנה נעשות \u0003שתי חלות\u0004 עולה \u0003לקב\u0004 אחד.","שנינו במשנתנו כי הסולת המשמשת ללחמים הבאים עם קרבן \u0003התודה היתה באה חמש סאין ירושלמיות\u0004 שהן שש סאים מדבריות, ושש סאים מדבריות הן שתי איפות, שכל איפה היא בת שלוש סאים. ועל כך שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שהאיפה מכילה שלוש סאים? \u0003אמר רב חסדא:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"האיפה והבת תכן\u0004 (=שיעור תכולה) \u0003אחד\u0004 (=זהה) \u0003יהיה לכם\".\u0004 (יחזקאל מה, יא). הרי ששוות האיפה (מידת היבש) והבת (מידת הלח) בשיעורן. ומכאן נלמד לענייננו, \u0003מה\u0004 שיעורה של מידת ה\u0003בת\u0004 \u0005—\u0006 הוא \u0003שלש סאין, אף\u0004 שיעור מידת ה\u0003איפה\u0004 \u0005—\u0006 הוא \u0003שלש סאין.\u0004","ושואלים: \u0003ו\u0004שיעור מידתה של ה\u0003בת גופא\u0004 \u0005[עצמה]\u0006 שהוא שלוש סאים, \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שנלמד הדבר \u0003מדכתיב\u0004 \u0005[מ\u0006מה \u0005שנאמר]\u0006 באותו הפסוק \"האיפה והבת תוכן אחד יהיה, \u0003לשאת את מעשר החמר\u0004 (שהיא מידה המכילה שלושים סאים) \u0003הבת\",\u0004 ו\u0005הרי איפוא ששיעור מידת הבת הוא שלוש סאים —\u0006 אין זו הוכחה. שהרי במידת ה\u0003איפה\u0004 עצמה הנזכרת באותו הפסוק \u0003נמי הכתיב\u0004 \u0005[גם כן הרי נאמר]\u0006 בה \u0003\"ועשירית החמר האיפה\",\u0004 שהיא עשירית ממידת החומר. ואין אנו נצרכים איפוא ללמוד את שיעור האיפה מתוך השוואתה לשיעור הבת! \u0003אלא\u0004 את שיעורה של מידת ה\u0003חומר לא ידענא\u0004 \u0005[אין אני יודע]\u0006 \u0003כמה\u0004 הוא, ולכך הנאמר באיפה שהיא עשירית ממידת החומר אינו מלמד מה מידתה של האיפה. \u0003הכא\u0004 \u0005[כאן],\u0006 בשיעורה של מידת הבת \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ידענא\u0004 \u0005[אין אני יודע]\u0006 \u0003כמה\u0004 הוא!","\u0003אלא\u0004 יש לומר כי \u0003מהכא\u0004 \u0005[מכאן],\u0006 מהפסוק הנאמר בהמשך למדים אנו לענין הפרשת התרומה. \u0003\"וחק השמן הבת השמן ומעשר הבת מן הכור עשרת הבתים חומר כי עשרת הבתים חומר\u0004\" (שם יד) למדים אנו. שכך מתפרש הפסוק: \u0005המשפט הראוי בנתינת תרומה מן השמן (\"וחוק השמן\"), הריהו\u0006 שתהא זו נתינה של מידת הבת, שהיא המידה הנהוגה בנוזלים (\"הבת השמן\"), והיא עשירית מתוך שלושים סאה שמן (\"מן הכור\", ששיעור הכור הוא שלושים סאה). ומסביר הכתוב כי כך הוא השיעור הראוי, שמידת עשרה בתים היא המידה הנקראת \"חומר\" (\"עשרת הבתים חומר\"), וה\"חומר\" הריהו שווה במידתו לכור. וחזר הכתוב ואמר שכן שיעור עשרת הבתים הינו כשיעור החומר (\"כי עשרת הבתים חומר\"). מכאן נמצאנו למדים כי שיעור מידת הבת הוא שלוש סאים, ומכאן שאף שיעור האיפה (השווה לה בשיעורה) הוא שלוש סאים.","שנינו במשנתנו כי חמש מידות ירושלמיות הינן כשש מידות מדבריות, שכן הוסיפו שישית על המידה הקדומה. ולמדנו בסוגיה הקודמת כי מהפסוקים הנאמרים בספר יחזקאל למדנו לענין שיעור הסאה. ומביאים עוד בענין תוספת על המידות מה ש\u0003אמר שמואל:\u0004 אם רוצים אנשי המקום לשנות את גודל המידות הנהוגות במקומם ולהגדיל אותן, \u0003אין מוסיפין על המדות יותר משתות\u0004 (שישית), \u0003ו\u0004כן \u0003לא\u0004 מוסיפים \u0003על\u0004 ערכו של \u0003המטבע יותר משתות. והמשתכר\u0004 במסחרו \u0003לא ישתכר יותר משתות.\u0004","ודנים בדברים האמורים: זה שאמר שמואל שאין להוסיף על המידות הנהוגות יותר משישית, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שטעם הדבר הוא \u0003משום\u0004 שתוספת מרובה על המידות עלולה להביא ל\u0003אפקועי תרעא\u0004 \u0005[הפקעת השער,\u0006 התייקרות מחירים\u0005]\u0006 \u0005—\u0006 \u0003אי הכי\u0004 \u0005[אם כך],\u0006 בתוספת \u0003שתות נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 נתיר, שהרי גם אז קיים חשש זה!","\u0003אלא\u0004 תאמר כי הסיבה היא \u0003משום\u0004 דין \u0003אונאה, כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא ליהוי\u0004 \u0005[לא יהיה]\u0006 בדבר כדי \u0003ביטול מקח,\u0004 אלא כדי אונאה. שכן אונאה עד שישית \u0005—\u0006 אף שמחזיר את האונאה, מכל מקום המקח קיים. אבל ביותר משישית — המקח כולו בטל. ואין לתקן דבר שבגללו יתבטלו הרבה מכירות. \u0003ו\u0004אולם אף הסבר זה יש לדחות, שכן \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר רבא\u0004 כי \u0003כל\u0004 אונאה שהיא ב\u0003דבר ש\u0004נמדד \u0003במדה וש\u0004נשקל \u0003במשקל וש\u0004נמנה \u0003במנין, אפילו\u0004 היא \u0003פחות מכדי\u0004 דין \u0003אונאה\u0004 \u0005—\u0006 \u0003חוזר.\u0004 וכאן מדובר בטעות במידה!","\u0003אלא\u0004 תאמר שטעם האיסור הוא \u0003משום תגרא\u0004 \u0005[הסוחר],\u0006 \u0003כי היכי דלא למטייה דיאנה\u0004 \u0005[כדי שלא יבוא לו הפסד].\u0006 שמא לא ישים לב להגדלת המידות, וימכור לפי המחיר הישן, והואיל ודרכו להרויח שישית, אם אין מוסיפים על המידות יותר משישית, נמצא שההפסד במידה ושיעור הרווח מתאזנים, ואינו מפסיד. ויש לתמוה: אמנם בכך \u0003דיאנה\u0004 \u0005[הפסד]\u0006 \u0003הוא דלא לימטייה\u0004 \u0005[שלא יבוא לו],\u0006 וכי \u0003רוחא\u0004 \u0005[רווח]\u0006 \u0003לא בעי\u0004 \u0005[לא צריך]?\u0006 וכפתגם העממי: \u0003זבן וזבין\u0004 \u0005[קנה ומכור,\u0006 בלי להרויח\u0005]\u0006 \u0005—\u0006 \u0003תגרא איקרי\u0004 \u0005[תגר ייקרא]?!\u0006","\u0003אלא אמר רב חסדא:\u0004 טעם האיסור להוסיף יותר משישית על המידות, אינו מן הסברה, אלא \u0003שמואל קרא אשכח\u0004 \u0005[פסוק מצא]\u0006 \u0003ו\u0004ממנו \u0003דרש,\u0004 שכן נאמר: \"ו \u0003השקל עשרים גרה עשרים שקלים חמשה ועשרים שקלים עשרה וחמשה שקל המנה יהיה לכם\"\u0004 (יחזקאל מה, יב). ואם מצרפים את המספרים הללו יחד (עשרים, עשרים וחמישה, עשרה, וחמישה) הרי אלו שישים שקלים, שעולים לפי הפסוק לשיעור של \u0003מנה\u0004 (\"המנה יהיה לכם\"). ויש לתהות: וכי שישים שקלים הינם מנה? והרי לפי חשבון זה \u0003מאתן וארבעין הוו\u0004 \u0005[מאתיים וארבעים\u0006 דינרים \u0005הם]!\u0006 שבכל שקל של מקרא יש ארבעה דינרים, ואם כן נמצא שבמנה בן שישים שקלים יש מאתים וארבעים דינרים. ואילו אנו יודעים שבמנה יש עשרים וחמישה שקלים, שהם מאה דינרים!","\u0003אלא שמע מינה תלת\u0004 \u0005[למד מכאן שלושה]\u0006 דברים: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003מנה של קודש\u0004 שאליו התייחס הנביא יחזקאל \u0005—\u0006 \u0003כפול היה,\u0004 ואף מתחילה היו בו חמישים שקלים (מאתים דינרים). \u0003ו\u0004עוד \u0003שמע מינה\u0004 \u0005[למד מכאן],\u0006 ממה שאמר הנביא שהמנה יהא מעתה בן שישים שקלים, ולא בן חמישים שקלים, כי \u0003מוסיפין על המדות\u0004 (או המטבעות), \u0003ו\u0004אולם \u0003אין מוסיפין\u0004 עליהם \u0003יותר משתות. ו\u0004עוד \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003שתותא\u0004 \u0005[שישית]\u0006 זו מחושבת \u0003מלבר\u0004 \u0005[מבחוץ],\u0006 כלומר, מן הסכום הסופי, הגדול יותר, שהוא חמישית מן הקטן. כגון כאן, שהוסיפו ארבעים על מאתים, והם שישית מהסכום הכולל מאתים וארבעים, וחמישית ממאתים.","ובדינו זה של שמואל, \u0003אמר רבינא\u0004 כי \u0003מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 כשיטה זו, \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנה בה]\u0006 כי \u0003תודה היתה באה חמש סאין ירושלמיות שהן שש מדבריות,\u0004 משמע שמוסיפים שישית ולא יותר, וכי תוספת השישית היא מבחוץ. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא."],["\u0003מכולם,\u0004 מכל אחד מארבעת המינים שבלחמי התודה \u0003היה\u0004 הכהן \u0003נוטל\u0004 לחם \u0003אחד מ\u0004כל \u0003עשרה\u0004 לחמים שבכל מין \u0003ל\u0004\u0003תרומה. ש\u0004כן \u0003נאמר\u0004 בדין לחמי התודה \u0003\"והקריב ממנו אחד מכל קרבן תרומה לה'\u0004 לכהן הזורק את דם השלמים לו יהיה\" (ויקרא ז, יב— יד), ונדרש כתוב זה כך: \u0003\"אחד\"\u0004 — שצריך הלחם להיות שלם, ללמדנו \u0003שלא יטול פרוס.\u0004 \u0003\"מכל קרבן\"\u0004 — \u0003שיהו כל הקרבנות\u0004 (כל ארבעת מיני החלות הקרבות) \u0003שוות\u0004 במספרן, עשרה לחמים בכל מין, ו\u0003שלא יטול\u0004 הכהן העובד במנחות שני לחמים \u0003מקרבן\u0004 (ממין) אחד \u0003על\u0004 מנת לפטור בכך \u0003את\u0004 \u0003חבירו\u0004 מתרומה. \u0003\"לכהן הזרק את דם השלמים לו יהיה\"\u0004 — שהחלה המורמת לתרומה היא שתיאכל על ידי הכהן, \u0003ו\u0004אילו \u0003השאר\u0004 (שאר החלות) \u0003נאכל לבעלים\u0004 של קרבן התודה.","שנינו במשנתנו דיני התרומה הניטלת מלחמי התודה הנלמדים מדרשת הכתוב \"והקריב ממנו אחד מכל קרבן תרומה לה'...\", ומביאים עוד מן הנדרש בכתוב זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"והקריב ממנו\"\u0004 בא להורות שיהו כל החלות כאחד, שאין נוטלים מהן את התרומה אלא \u0003מן המחובר\u0004 (כאשר הן נמצאות במקום אחד). \u0003\"אחד\"\u0004 — \u0003שלא יטול פרוס.\u0004 \u0003\"מכל קרבן\"\u0004 — \u0003שיהו כל הקרבנות\u0004 (לחמי המנחות) \u0003שוות, שלא יטול מן הקרבן\u0004 האחד שני לחמים כדי לפטור בכך גם \u0003על חבירו.\u0004 ואולם ממשמעות האמור \u0003\"תרומה לה' \" איני יודע\u0004 \u0003מכמה\u0004 לחמים \u0003היא\u0004 באה, מהו שיעורה של תרומה זו, ולכך","\u0003הריני דן: נאמר כאן\u0004 בפרשת לחמי התודה לשון \u0003\"תרומה\" ונאמר ב\u0004פרשת \u0003תרומת מעשר\u0004 לשון \u0003\"תרומה\"\u0004 (\"...והרמותם ממנו תרומת ה' מעשר מן המעשר\". במדבר יח, כו). \u0003מה להלן,\u0004 בתרומת המעשר, התרומה הניתנת היא \u0003אחד מעשרה,\u0004 \u0003אף\u0004 שיעור התרומה האמור \u0003כאן\u0004 בלחמי תודה הריהו \u0003אחד מעשרה.\u0004","כנגד זה אומרים: \u0003או\u0004 שמא \u0003כלך\u0004 (לך) \u0003לדרך זו\u0004 ותלמד מגזירה שווה אחרת: \u0003נאמר כאן\u0004 לשון \u0003\"תרומה\", ונאמר ב\u0004דין ה\u0003בכורים\u0004 לשון \u0003\"תרומה\"\u0004 (\"ותרומת ידך\", דברים יב, יז — אלה הביכורים). \u0003מה להלן\u0004 בדין הביכורים \u0003אין לה\u0004 לתרומה \u0003שיעור,\u0004 שהרי יכול להביא ביכורים ככל שירצה, \u0003אף כאן\u0004 התרומה מלחמי התודה \u0003אין לה שיעור?\u0004","ומעתה יש להכריע בין אפשרויות אלה: \u0003נראה למי\u0004 מבין תרומת מעשר וביכורים \u0003דומה\u0004 תרומת לחמי תודה: מצד אחד יש לומר שיהיו \u0003דנין\u0004 (למדים בגזירה שווה) דינה של ה\u0003תרומה שאין אחריה תרומה,\u0004 כתרומת לחמי התודה, שאין תרומה נוספת הבאה אחריה, \u0003מתרומה שאין אחריה תרומה,\u0004 כתרומת המעשר, \u0003ואל יוכיח\u0004 (נביא ראיה) לדינה \u0003של תרומת לחמי תודה מ\u0004\u0003בכורים, ש\u0004כן \u0003יש אחריהן תרומה\u0004 אחרת, שהרי אחרי הפרשת הביכורים יש להפריש שאר תרומות ומעשרות.","\u0003או\u0004 שמא \u0003כלך לדרך זו\u0004 ותאמר שיהיו \u0003דנין\u0004 דינה של ה\u0003תרומה הנאכלת במקום קדוש,\u0004 בירושלים, כתרומת לחמי תודה, \u0003מתרומה הנאכלת במקום קדוש,\u0004 מן הביכורים, שאף הם נאכלים בירושלים. \u0003ואל תוכיח\u0004 לדינה \u0003של תרומת לחמי תודה מ\u0004\u0003תרומת מעשר, ש\u0004כן הריהי \u0003נאכלת בכל מקום?\u0004","וכיון ששקולות הן שתי אפשרויות אלה, לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) עוד בפרשת לחמי תודה \u0003\"ממנו תרומה לה' \", ו\u0004בדומה לכך \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003ב\u0004פרשת \u0003תרומת מעשר\u0004 לשון זו \u0003\"ממנו תרומה\"\u0004 — \u0003ל\u0004למדנו \u0003גזירה שוה\u0004 בין לחמי תודה ותרומת מעשר, ומכאן נלמד שאף בלחמי תודה שיעור התרומה הוא אחד מעשרה, כבתרומת מעשר.","וממשיכים ודנים עוד: \u0003למדנו\u0004 עד כה \u0003ל\u0004ענין דין \u0003תרומה\u0004 של לחמי תודה \u0003ש\u0004שיעורה \u0003היא אחד מעשרה\u0004 כשיעור נתינת תרומת מעשר. \u0003אבל\u0004 עדיין \u0003איני יודע\u0004 מגזירה שווה זו \u0003מכמה\u0004 סולת \u0003היא\u0004 באה כל \u0003חלה.\u0004 ולכך \u0003הריני דן, נאמר כאן\u0004 בלחמי תודה לשון \u0003\"לחם\"\u0004 (\"על חלות לחם חמץ יקריב קרבנו\". \u0003ויקרא ז, יב),\u0004 \u0003ונאמר להלן בשתי הלחם\u0004 לשון \u0003\"לחם\"\u0004 (\"ממושבותיכם תביאו לחם תנופה שתים שני עשרונים\". שם כג, יז). ומעתה נלמד: \u0003מה להלן\u0004 בשתי הלחם, שיעור הקמח הניתן הריהו \u0003עשרון ל\u0004כל \u0003חלה\u0004 משתי החלות, \u0003אף כאן\u0004 בחלות החמץ של התודה שיעור הסולת הניתן הריהו \u0003עשרון לחלה.\u0004","\u0003או\u0004 שמא יש לומר כי \u0003כלך לדרך זו\u0004 ותלמד בגזירה שווה מהשוואת לחמי תודה ללחם הפנים, \u0003נאמר כאן\u0004 בלחמי תודה לשון \u0003\"לחם\", ונאמר בלחם הפנים\u0004 לשון \u0003\"לחם\"\u0004 (\"ולקחת סולת ואפית אותה שתים עשרה חלות שני עשרונים יהיה החלה האחת\". שם כד, ה—ז), \u0003מה להלן\u0004 בלחם הפנים כל לחם משתים עשרה החלות בא מ\u0003שני עשרונות\u0004 (\"שני עשרונים יהה החלה האחת\"), \u0003אף כאן\u0004 בחלות החמץ של התודה, כל לחם מהם בא מ\u0003שני עשרונות\u0004 סולת?","ומנסים להכריע בין אפשרויות אלה: \u0003נראה למי\u0004 מבין שתי הלחם ולחם הפנים \u0003דומה\u0004 לחמי התודה: מצד אחד יש לומר שיהיו \u0003דנין\u0004 דינן של חלות החמץ שבלחמי התודה דווקא משתי הלחם, שכן יש להעדיף וללמוד דינה של \u0003מנחה הבאה חמץ עם הזבח\u0004 (קרבן), כחלות החמץ של לחמי תודה הבאות עם קרבן התודה, ממנחה הבאה חמץ עם הזבח כשתי הלחם, שאף הם חמץ (\"ממושבותיכם תביאו לחם תנופה שתים שני עשרונים סולת תהיינה חמץ תאפינה\". שם כג, יז), ובאים עם הקרבנות (\"והקרבתם על הלחם שבעת כבשים ושני כבשים בני שנה לזבח שלמים\", שם יח). \u0003ואל יוכיח\u0004 ללחמי תודה \u0003מ\u0004\u0003לחם הפנים, ש\u0004כן \u0003אינו בא חמץ,\u0004 וכן אינו בא \u0003עם הזבח.\u0004","\u0003או\u0004 שמא יש לומר כי \u0003כלך לדרך זו\u0004 ותאמר שיהיו \u0003דנין\u0004 דינם של לחמי התודה דווקא מלחם הפנים, שכן יש להעדיף וללמוד דינה של ה\u0003מנחה הבאה מ\u0004כל סוגי התבואות: זו שגדלה ב\u0003ארץ\u0004 ישראל \u0003ו\u0004זו שגדלה ב\u0003חוצה לארץ,\u0004 \u0003מן\u0004 היבול \u0003החדש\u0004 שנקצר בשנה זו, \u0003ומן\u0004 היבול \u0003הישן\u0004 שנקצר בשנים קודמות. \u0003ממנחה\u0004 כלחם הפנים, שאף היא זו \u0003הבאה מ\u0004תבואת \u0003ארץ\u0004 ישראל \u0003ו\u0004מתבואת \u0003חוצה לארץ, מן\u0004 היבול \u0003החדש ומן\u0004 היבול \u0003הישן. ואל יוכיחו\u0004 מ\u0003שתי הלחם, ש\u0004כן \u0003אין\u0004 הן \u0003באות אלא מן\u0004 היבול \u0003החדש\u0004 בלבד, \u0003ו\u0004כן אין הן באות אלא \u0003מן ה\u0004תבואה שגדלה \u0003ב\u0004\u0003ארץ?\u0004","וכיון ששקולות שתי האפשרויות לכך \u0003תלמוד לומר\u0004 עוד בפרשת שתי הלחם \u0003\"ממושבתיכם תביאו לחם תנופה שתים\",\u0004 \u0003ש\u0004לכאורה \u0003אין תלמוד לומר \"תביאו\"\u0004 דבר, ומקרא יתר הוא, \u0003ומה תלמוד לומר \"תביאו\"?\u0004 — \u0003שכל מה שאתה מביא ממקום אחר\u0004 (במנחה אחרת הבאה חמץ, בדומה לשתי הלחם) ש\u0003הרי\u0004 אף \u0003הוא\u0004 צריך להיות \u0003כזה,\u0004 בדומה לשתי הלחם. ומכאן נסיק: \u0003מה להלן\u0004 בדין שתי הלחם — \u0003עשרון\u0004 סולת \u0003ל\u0004כל \u0003חלה, אף כאן\u0004 בחלות החמץ של לחמי תודה — \u0003עשרון ל\u0004כל \u0003חלה.\u0004","ויש לדון: \u0003אי\u0004 \u0005[או]\u0006 אולי נלמד באופן אחר, \u0003מה להלן\u0004 בדין שתי הלחם — הרי אלה \u0003שני עשרונות\u0004 שמהם באים שתי הלחם, \u0003אף כאן\u0004 בחלות החמץ של לחמי תודה — הרי אלה \u0003שני עשרונות\u0004 שמהם באים כל עשר חלות החמץ? \u0003לכך\u0004 \u0003תלמוד לומר\u0004 בכתוב בשתי הלחם \u0003\"תהיינה\",\u0004 וממנו","\u0003למדנו\u0004 שכל חלת חמץ באה מעשרון אחד, שבסך הכל הם \u0003עשרה\u0004 עשרונים \u0003ל\u0004חלות ה\u0003חמץ\u0004 שבלחמי תודה. ועדיין יש לברר: שיהיו \u0003עשרה\u0004 עשרונים סולת \u0003ל\u0004שלושים חלות ה\u0003מצה מנין\u0004 לנו? לכך \u0003תלמוד לומר\u0004 לשון הכתוב בלחמי תודה. שכן נאמר בדינן של חלות המצות \"אם על תודה יקריבנו והקריב על זבח התודה חלות מצות בלולות בשמן ורקיקי מצות משוחים בשמן וסולת מורבכת חלות בלולות בשמן\" (ויקרא ז, יב), ובפסוק שלאחריו נאמר \u0003\"על חלת לחם חמץ\u0004 יקריב קרבנו על זבח תודת שלמיו\", הרי זה בא להורות כי שקולים הם זה לזה: כ","\u0003נגד\u0004 (במקביל) ללחמי ה\u0003חמץ, הבא\u0004 לחמי \u0003מצה,\u0004 שכשם שכל לחמי חמץ באים מעשרה עשרונים סולת, אף כל לחמי המצה באים מעשרה עשרונים סולת. \u0003נמצאו\u0004 איפוא כי מ\u0003עשרים עשרונות\u0004 סולת באים כל \u0003לחמי תודה,\u0004 והם נחלקים: \u0003עשרה\u0004 מתוכם נועדים \u0003ל\u0004עשרת לחמי ה\u0003חמץ, ו\u0004אילו ה\u0003עשרה\u0004 האחרים נועדים \u0003ל\u0004שלושים לחמי ה\u0003מצה.\u0004","ועדיין יש מקום לברר: \u0003יכול\u0004 שמביאים \u0003עשרה\u0004 לחמים של מצה בלבד, ואותם עשרה \u0003שבמצה לא יהו כולן אלא ממין אחד?\u0004 לכך \u0003תלמוד לומר\u0004 האמור בדין לחמי התודה \u0003\"אם על תודה יקריבנו והקריב על זבח התודה חלות מצות בלולת בשמן ורקיקי מצות משחים בשמן סלת מרבכת\u0004 חלות בלולות בשמן\" — שחייב הוא בהבאת שלושת סוגים אלה של המצה, ובכללם הם שלושים לחמים. ומעתה נסכם: \u0003נמצאו\u0004 איפוא כי \u0003שלשה עשרונים ושליש\u0004 סולת ניתנים \u0003לכל מין ומין\u0004 משלושת לחמי המצה הבאים בלחמי תודה. \u0003ו\u0004שיעור הסולת בכל \u0003שלש חלות\u0004 של מצה \u0003הריהו עולה\u0004 \u0003ל\u0004כלל \u0003עשרון\u0004 אחד. \u0003ונמצאו\u0004 איפוא כי סך כל \u0003לחמי\u0004 ה\u0003תודה\u0004 הריהו \u0003ארבעים\u0004 לחמים. והבעלים \u0003נוטל מהן ארבע\u0004 לחמים, אחד מכל מין, \u0003ונותן\u0004 אותם \u0003לכהן, והשאר נאכלים לבעלים.\u0004 עד כאן הברייתא.","ומעתה דנים בדברי ברייתא זו. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בתחילת הברייתא כי מן הכתוב \u0003\"והקריב ממנו\"\u0004 למדים אנו שאין נוטלים את התרומה מן החלות אלא \u0003מן המחובר\u0004 שיהא הכל יחד בשעת התרומה. ושואלים: \u0003אלא מעתה,\u0004 לפי דרך דרשה זו מקרא זה שבהקרבת אימורי החטאת, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו \u0003\"ואת כל חלבו ירים ממנו\u0004 והקטיר המזבחה\" (שם ד, יט), \u0003התם מאי\u0004 \u0005[שם, מה\u0006 איזה\u0005]\u0006 \u0003מחובר איכא\u0004 \u0005[יש]?\u0006 ומשיבים: אף הקרבת אימורי החטאת צריך שתהא מן המחובר, ו\u0003כ\u0004דברי \u0003רב\u0004","\u0003חסדא\u0004 ש\u0003אמר\u0004 בשמו של החכם \u0003אבימי,\u0004 שכן \u0003אמר רב חסדא, אמר אבימי: שלא ינתח\u0004 הכהן את \u0003בשר\u0004 הקרבן, \u0003קודם שיטול\u0004 ממנו בתחילה את ה\u0003אימורין.\u0004 שכאשר נלקחים האימורים מן הקרבן, צריך הקרבן להיות שלם.","וממשיכים לדון בדברי הברייתא. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא שהמקור לכך שתרומת לחמי התודה הריהי אחת מעשרה הוא בגזירה שווה, שכן \u0003נאמר כאן\u0004 בלחמי תודה לשון \u0003\"תרומה\" ו\u0004כן \u0003נאמר בתרומת מעשר\u0004 לשון \u0003\"תרומה\"\u0004 (\"והרמות מכס לה' מאת אנשי המלחמה... ונתתה לאלעזר הכהן תרומת ה' \". שם כח). וכשם שתרומת מעשר היא אחד מעשרה כך גם בתרומת לחמי תודה.","ושואלים: \u0003ונילף\u0004 \u0005[ונלמד]\u0006 דינה של תרומת לחמי תודה בגזירה שווה \u0003מתרומת מדין\u0004 (התרומה שניתנה לאחר מלחמת ישראל במדיינים. במדבר לא), שאף בה נאמר לשון \"תרומה\", ושיעורה של התרומה לא היה אחד מעשרה (\"והרמות מכס לה' מאת אנשי המלחמה היוצאים לצבא אחד נפש מחמש מאות מן האדם ומן הבקר ומן החמורים ומן הצאן. ממחציתם תקחו ונתתה לאלעזר הכהן תרומת ה'. וממחצית בני ישראל תקח אחד אחוז מן החמישים מן האדם מן הבקר מן החמורים ומן הצאן מכל הבהמה ונתתה אותם ללויים...\". שם כח—ל)! ומשיבים: \u0003דנין\u0004 (למדים בגזירה שווה) דינה של \u0003תרומה הנוהגת לדורות\u0004 (כתרומת לחמי תודה) \u0003מתרומה הנוהגת לדורות\u0004 (כתרומת מעשר), \u0003ואל תוכיח\u0004 \u0003מ\u0004\u0003תרומת מדין שאינה נוהגת לדורות,\u0004 שהרי רק לשעתה נקבעה.","ושואלים עוד: \u0003ונילף\u0004 \u0005[ונלמד]\u0006 דינה של תרומת לחמי תודה \u0003מתרומת\u0004 (הפרשת) \u0003חלה,\u0004 שאף בה נאמרה הלשון \"תרומה\" (\"והיה באכלכם מלחם הארץ תרימו תרומה לה'. ראשית עריסותיכם תרימו תרומה כתרומת גורן כן תרימו אותה\", במדבר טו, יט—כ), ושיעורה של החלה הינו אחד מעשרים וארבעה! ומשיבים: \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005של בית]\u0006 מדרשו של \u0003ר' ישמעאל\u0004 בהסבר הדברים: \u0003דנין\u0004 דינו של \u0003דבר שנאמר בו\u0004 הלשון \u0003\"ממנו תרומת ה' \"\u0004(כנאמר בלחמי תודה, \"והקריב ממנו אחד מכל קרבן תרומה לה' \") \u0003מ\u0004דינו של \u0003דבר שנאמר\u0004 אף \u0003בו\u0004 הלשון \"ממנו \u0003תרומה לה' \"\u0004(כנאמר בתרומת מעשר \"והרמותם ממנו תרומת ה' מעשר מן המעשר\"). \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003תרומת חלה\u0004 שאין למדים ממנה בגזירה שווה לדינם של לחמי תודה, שכן \u0003לא נאמר בו \"ממנו תרומה לה' \".\u0004","לאחר שראינו כי דיני תרומת לחמי תודה נלמדים מתרומת מעשר, דנים בענין זה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 מי שאינם כהנים (\"זרים\") שאכלו במזיד \u0003תרומת לחמי תודה\u0004 האם \u0003חייבין\u0004 הם \u0003עליהן\u0004 (על אכילתם) \u0003מיתה\u0004 בידי שמים, וכדין הזר האוכל תרומת מעשר? ובדומה לכך, שאל רבא: זרים שאכלו תרומת לחמי תודה בשוגג, האם חייבים הם על כך בתשלום קרן \u0003וחומש\u0004 (חמישית) כדרך שחייבים הם על אכילת תרומת מעשר. \u0003או\u0004 שמא \u0003אין חייבין\u0004 הם \u0003עליהן\u0004 לא \u0003מיתה\u0004 האוכלים אותם במזיד, \u0003ו\u0004לא תשלום \u0003חומש.\u0004","ומסביר רבא את צדדי בעייתו: \u0003כיון דאיתקש\u0004 \u0005[שהוקשה,\u0006 הושוותה\u0005]\u0006 תרומת לחמי תודה \u0003לתרומת מעשר\u0004 — לכל ענין הוקש \u0003ו\u0004\u0003כתרומת מעשר דמי\u0004 \u0005[נחשב]\u0006 הדבר. ועל אכילתם חייבים הזרים במיתה או בתשלומים. \u0003או דלמא\u0004 \u0005[שמא]\u0006 כיון שנאמר באכילת תרומה על ידי זר במזיד \"ומתו בו כי יחללוהו\" (ויקרא כב, ט), וכן נאמר באכילת תרומה על ידי זר בשוגג \"ואיש כי יאכל קודש בשגגה ויסף חמישיתו עליו\" (שם יד). והמלים \u0003\"בו\"\u0004 האמור באכילת מזיד \u0003ו\"חמשיתו\"\u0004 האמור באכילת שגגה הן לשונות מיעוט, ושמא \u0003מיעט רחמנא\u0004 \u0005[הכתוב],\u0006 שרק בתרומת מעשר קיים דין זה, ולא בתרומת לחמי תודה?","ועוד יש לשאול מתוך השוואת תרומת לחמי תודה לתרומת מעשר: האם תרומת לחמי תודה שנפלה לפירות של חולין \u0003מדמעת\u0004 (אוסרת בתערובת) את כל הפירות, וכדינה של התרומה. \u0003או\u0004 שמא לא הושוותה לתרומה אלא לענין שיעורה, ובשאר דיניה אין היא כתרומה, ולכך \u0003אינה מדמעת\u0004 את תערובתה. אף שאלה זו לא נפתרה, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה, ללא תשובה.","ומבררים עוד את דברי הברייתא. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: שמא תאמר \u0005שכשם ששתי הלחם באים משני עשרונים קמח, אף חלות החמץ של לחמי התודה תבאנה משני עשרונים, ולא מעשרה עשרונים? לכך\u0006 \u0003תלמוד לומר \"תהיינה\",\u0004 שחלות החמץ תבאנה מעשרה עשרונים. ושואלים: \u0003מאי תלמודא\u0004 \u0005[מה הלימוד],\u0006 כיצד נלמד הדבר מהלשון \"תהיינה\"?"],["\u0003אמר רב יצחק בר אבדימי\u0004 בהסבר הדברים: בשתי הלחם \u0003\"תהיינה\"\u0004 (במדבר כ, יז) \u0003כתיב\u0004 \u0005[נאמר],\u0006 שיש בכתוב שתי יודי\"ם, ובאה היו\"ד \u0005היתירה לדרשה, שחלות החמץ שבקרבן התודה, יהיו מעשרה (כמנין האות יו\"ד בגימטריא) עשרונים. ומקשים על כך: ושמא\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 שהכוונה אמנם לעשר מידות, ואולם אין הכוונה אלא ל\u0003עשרה קפיזי\u0004 \u0005[קבים]\u0006 הקטנים בשיעורם מהעשרונים?! \u0003אמר רבא:\u0004 אין לומר כן, \u0003שהרי\u0004 \u0003ב\u0004מידת \u0003עשרונות דבר הכתוב,\u0004 ולא במידות אחרות.","ומבררים עוד את המשך דברי הברייתא. שנינו בה: \u0003למדנו\u0004 מייתור בכתוב \"תהיינה\" שבאים \u0003עשרה\u0004 עשרונים \u0003ל\u0004עשרת לחמי ה\u0003חמץ\u0004 שבתודה. ואולם שבאים \u0003עשרה\u0004 עשרונים אף \u0003ל\u0004שלושים החלות של \u0003מצה מנין\u0004 לנו? \u0003תלמוד לומר\u0004 בשלושת סוגי חלות המצה הבאות עם קרבן תודה \u0003\"על חלות לחם חמץ\"\u0004 (ויקרא ז, יג), ללמדנו כי \u0003כנגד\u0004 מספר ה\u0003עשרונים של לחמי ה\u0004\u0003חמץ,\u0004 כמספר הזה \u0003הבא\u0004 אף ללחמי ה\u0003מצה.\u0004","ושואלים על דרך דרשה זו: \u0003וכי דבר הלמד בהיקש\u0004 (הדין שלחמי חמץ שבתודה באים עשרה עשרונים, שנלמד מהיקש \"תביאו\" לשתי הלחם), \u0003חוזר ומלמד בהיקש\u0004 בקדשים, שנלמד דין לחמי המצה בקרבן התודה (שאף הוא בא מעשרה עשרונים) מדין לחמי החמץ? ומשיבים: אין דין עשרה עשרונים בלחמי חמץ שבתודה נלמד מהיקש משתי הלחם לבדו אלא \u0003הימנו\u0004 (ממנו) \u0003ודבר אחר הוא\u0004 נלמד. שאינו יכול להילמד מדין שתי הלחם עצמו, ולכן הוא נלמד מצירוף שני מקורות לימוד: משתי הלחם ומן האמור בלחמי תודה, שהם עשרה לחמים של חמץ. \u0003וכל\u0004 דבר הנלמד באופן זה של \u0003הימנו ודבר אחר\u0004 — \u0003לא הוי\u0004 \u0005[אין זה]\u0006 נחשב כנלמד על ידי \u0003היקש,\u0004 ולכך הריהו מלמד בהיקש גם בקדשים.","ומקשים על תירוץ זה: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 שאופן לימוד כגון זה \u0003לא הוי\u0004 \u0005[אין הוא\u0006 נחשב\u0005]\u0006 כ\u0003היקש, אלא ל\u0004שיטת \u0003מאן דאמר הוי\u0004 \u0005[מי שאומר\u0006 כי \u0005הריהו\u0006 נחשב\u0005]\u0006 \u0003היקש, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: לשיטה זו אין הדבר נלמד מהיקש אלא ממשמעות לשון הכתוב, שכן המלה \u0003\"תביאו\"\u0004 האמורה בשתי הלחם לשון \u0003רבויא\u0004 \u0005[ריבוי]\u0006 \u0003היא,\u0004 ומלמדת על לחמי חמץ שבתודה שבאים עשרה. ולפיכך אין לחמי חמץ נחשבים כדבר הנלמד מהיקש, ולכך הריהם מלמדים בהיקש לענין לחמי מצה שבתודה.","מיני הלחמים שבאו עם איל \u0003המילואים\u0004 (שקרב כאשר התחנכו אהרן ובניו לכהונה, במשך שבעת ימי המילואים) \u0003היו באין כ\u0004שלושת מיני ה\u0003מצה ש\u0004באים \u0003ב\u0004קרבן \u0003ה\u0004\u0003תודה,\u0004 שהם: \u0003חלות ורקיקין ורביכה,\u0004 ואולם לחמי חמץ (כדרך שבאים בקרבן התודה) לא באו עימו.","ואילו מנחת מיני הלחמים הבאים עם קרבן הנזיר ביום שמשלים את ה\u0003נזירות היתה באה\u0004 רק \u0003כ\u0004\u0003שתי ידות\u0004 (שני חלקים, שני שליש) \u0003כמצה של תודה,\u0004 שכן בלחמי הנזירות יש רק \u0003חלות\u0004 מצות \u0003ורקיקין\u0004 מצות, \u0003ואין בה\u0004 חלות מסולת \u0003רבוכה\u0004 (מורבכת). \u0003נמצא\u0004 איפוא שלחמי קרבן נזיר באים מסולת ששיעורה \u0003עשרה קבין\u0004 במידה \u0003ירושלמית\u0004 (כמבואר במשנה למעלה, עז,א כי כל מין מלחמי המצה בא מחמישה קבים), \u0003שהן\u0004 שווים (במידות מדבריות) ל\u0003ששה עשרונות ו\u0004שני \u0003עודיין\u0004 (פעמיים \"עוד\" = שני שליש). שהרי כפי ששנינו שם למעלה, כל מין ממיני המצה בא משלושה עשרונים ושליש עישרון.","שנינו במשנתנו כי לחמי איל המילואים היו באים שלושה מינים, כחלות המצה שבקרבן התודה, חלות מצות, רקיקי מצות, ורבוכה. ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין,\u0006 מה מקורם של \u0005הדברים הללו]?\u0006 \u0003אמר רב חסדא, אמר רב חמא בר גוריא:\u0004 הדבר נלמד ממה ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בתוך סדר המעשים שעשה משה באיל המילואים \u0003\"ומסל המצות אשר לפני ה' לקח חלת מצה אחת וחלת לחם שמן אחת ורקיק אחד\"\u0004 (שם ח, כו). \u0003בשלמא\u0004 \u0005[נניח]\u0006 משמעות הכתוב \u0003חלות\u0004 (\"חלת מצה\") הריהי כפשוטה — \u0003חלות\u0004 מצה. וכמו כן מובן הוא משמעות האמור \u0003\"רקיק\"\u0004 \u0003—\u0004 הרי זה \u0003רקיק\u0004 מצות. ואולם האמור עוד בכתוב זה \"וחלת לחם \u0003שמן\" מאי נינהו\u0004 \u0005[מה הן]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 הכוונה ל\u0003רבוכה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אויא:\u0004 ושמא \u0003אימא\u0004 \u0005[אמור]\u0006 כי פירוש הכתוב \"וחלת לחם שמן\" כך הוא: \u0003אנתא דמשחא\u0004 \u0005[חתיכת עיסה עבה המטוגנת בשמן]!\u0006 \u0003אלא\u0004 יש לומר כי מקור הדברים הריהו \u0003כ\u0004דרך ש\u0003דרש רב נחמן בר רב חסדא משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' טבלא:\u0004 נאמר במנחת הכהן הגדול (\"קרבן אהרן\") ביום שהתמנה לכהונה גדולה, קודם התחלת העבודה (\"מנחת חינוך\"), וכן במנחתו הבאה בכל יום (\"מנחת חביתין\"), ובכלל זה אף מנחת כל כהן הדיוט (\"ובניו\") המובאת ביום שמתחנך בו לעבודה בבית המקדש: \u0003\"זה קרבן אהרן ובניו אשר יקריבו לה' ביום המשח אתו\u0004 עשירית האיפה סולת מנחה תמיד מחציתה בבוקר ומחציתה בערב. על מחבת בשמן תיעשה מורבכת תביאנה תופיני מחנת פיתים תקריב ריח ניחוח לה'. והכהן המשיח תחתיו מבניו יעשה אותה...\" (ויקרא ו, יג— טו).","ויש לדון בכתובים הללו: \u0003וכי מה למדנו\u0004 \u0003ל\u0004דינם של הכהנים ההדיוטות, המכונים בכתוב \u0003\"בניו\",\u0004 מן האמור בדינו של כהן גדול \u0003ביום המשחו?\u0004 \u0003אלא מקיש\u0004 דין מנחת \u0003חינוכו\u0004 של כהן הדיוט \u0003ל\u0004מנחת \u0003המשחו\u0004 של כהן גדול (\"מנחת חביתין\"): \u0003מה\u0004 מנחת \u0003המשחו\u0004 של הכהן הגדול כוללת גם חלה \u0003רבוכה, אף\u0004 מנחת \u0003חינוכו\u0004 של כהן הדיוט כוללת גם \u0003רבוכה,\u0004 וכיוצא בזה אף חלות הבאות עם איל המילואים, יש בהן רבוכה.","ועוד בענין מנחתו של כהן גדול הבאה ביום שמתחנך לעבודה, \u0003אמר רב חסדא: כהן גדול המתקרב\u0004 (הנכנס בתחילה) \u0003לעבודה\u0004 במקדש ככהן גדול \u0003צריך\u0004 להביא ביום חינוכו שתי מנחות, הבאות מ\u0003שתי עשרונות האיפה\u0004 סולת. מנחה \u0003אחת\u0004 בת עשרון אחד \u0003להמשחו\u0004 לכהונה גדולה (\"מנחת כהן משיח\", הבאה בכל יום, מחציתה בבוקר ומחציתה בערב), \u0003ו\u0004מנחה \u0003אחת\u0004 ובה עשרון שני, הבאה \u0003לחינוכו\u0004 לכהונה (\"מנחת חינוך\"). \u0003מר בר רב אשי אמר: שלש\u0004 עשרונות סולת הוא מביא.","\u0003ו\u0004\u0003מסבירים:\u0004 רב חסדא ומר בר רב אשי \u0003לא פליגי\u0004 \u0005[אינם חולקים],\u0006 שכן \u0003הא\u0004 \u0005[זה]\u0006 שאמר רב חסדא שצריך הכהן הגדול להביא מנחה משני עשרונים סולת מדובר במקרה \u0003דעבד\u0004 \u0005[ש\u0006כבר \u0005עשה]\u0006 כהן גדול זה \u0003עבודה\u0004 במקדש \u0003כשהוא כהן הדיוט,\u0004 והביא מנחה לחינוכו ככהן הדיוט. ולכך עתה צריך הוא להביא רק שני עשרונים סולת, לחינוכו ככהן גדול ולמנחת חביתין הבאה בכל יום. ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר מר בר רב אשי שצריך להביא מנחה משלושה עשרונים, מדובר כאשר \u0003לא עבד\u0004 \u0005[לא עשה]\u0006 עדיין הכהן הגדול \u0003עבודה כשהוא כהן הדיוט,\u0004 ולכך צריך הוא להביא מנחה משלושה עשרונים, אחת לחינוכו ככהן הדיוט, ואחת לחינוכו ככהן גדול, ואחת למנחת חביתין.","שנינו במשנתנו כי מנחת ה\u0003נזירות היתה באה\u0004 ב\u0003שתי ידות\u0004 (שני חלקים, שני מינים) מתוך השלושה הבאים \u0003כמצה שבתודה,\u0004 שאינה באה אלא עשר חלות מצות ועשרה רקיקי מצות, אך לא מסולת מורבכת.","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 נאמר בלחמים הבאים עם קרבן התודה: \"וזאת תורת השלמים אשר יקריב לה'. אם על תודה יקריבנו והקריב על זבח התודה חלות מצות בלולות בשמן ורקיקי מצות משוחים בשמן וסולת מורבכת חלות בלולות בשמן. על חלות לחם חמץ יקריב קרבנו על זבח תודת שלמיו\" (שם ז, יא— יג). ובא המקרא היתר \"על זבח תודת \u0003שלמיו\"\u0004 — \u0003לרבות\u0004 אף \u0003את\u0004 \u0003שלמי נזיר ל\u0004ענין שאף מנחתם באה מסולת בשיעור \u0003עשרת קבין ירושלמיות\u0004 (כשיעור הסולת הבאה בחלות המצות וברקיקי המצות שבלחמי התודה\u0003)\u0004 \u0003ולרביעית\u0004 הלוג \u0003שמן\u0004 (כשיעור השמן הבא בחלות המצות וברקיקי המצות שבלחמי התודה).","ויש לדון בדרשה זו: \u0003יכול\u0004 יהא בא הכתוב ללמדנו שיהא דינה של מנחת שלמי הנזיר כדינה של מנחת התודה \u0003לכל מה שאמור בענין\u0004 התודה, ואף בשלמי נזיר יביאו חמישה עשר קבים ירושלמיות לשלושת מיני לחמים ומחצית הלוג שמן? \u0003לכך\u0004 \u0003תלמוד לומר\u0004 בקרבנות הנזיר \"וסל \u0003מצות\u0004 סולת חלות בלולות בשמן ורקיקי מצות משוחים בשמן...\" (במדבר ו, טו). ומן הכתוב \"מצות\" למדים אנו כי אין במנחת הנזיר אלא חלות מצות ורקיקי מצות, ולא רבוכה.","ומבררים: \u0003מאי תלמודא\u0004 \u0005[מה הלימוד,\u0006 כיצד למדים כן\u0005]\u0006 מן המלה \"מצות\"? \u0003אמר רב פפא:\u0004 מביא הנזיר במנחתו דווקא מן ה\u0003דבר שנאמר בו\u0004 בלחמי התודה הלשון \u0003\"מצות\"\u0004 (שהם חלות ורקיקים), \u0003ו\u0004\u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003רבוכה\u0004 ש\u0003לא נאמר בו\u0004 בקרבן התודה לשון \u0003\"מצות\"\u0004 (שכן נאמר בהם \"...וסולת מורבכת חלות בלולות בשמן\"). ועוד למדנו: מנין שאין במנחת הנזיר אלא חלות מצות ורקיקי מצות ולא רבוכה, שכן החכם \u0003דבי\u0004 \u0005[של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]\u0006 על הנאמר במנחת הנזיר \"וסל מצות סולת חלות בלולות בשמן ורקיקי מצות משוחים בשמן...\". \u0003\"מצות\"\u0004 — הרי זה \u0003כלל, \"חלות\u0004 בלולות בשמן\" \u0003ו\u0004כן \u0003רקיקין\u0004 (\"ורקיקי מצות משוחים בשמן\") — הרי זה \u0003פרט,\u0004 ומכלל המידות שהתורה נדרשת בהן הוא שבמקרא בו יש \u0003כלל ופרט\u0004 — \u0003אין בכלל אלא מה שבפרט,\u0004 ומעתה אף בענייננו נסיק כי \u0003חלות ורקיקין\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 כלולים במנחת הנזיר, ואולם \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 וכגון הרבוכה — \u0003לא\u0004 נכלל במנחת הנזיר."],["\u0003השוחט את\u0004 קרבן \u0003התודה לפנים\u0004 (בתוך העזרה), כדינה, \u0003ו\u0004אולם באותה שעה נמצאו \u0003לחומה\u0004 (לחמיה, ארבעים החלות הבאות עם קרבן התודה) מ\u0003חוץ לחומה,\u0004 במקום בו אסורות חלות התודה באכילה — \u0003לא קדש\u0004 (התקדש) בשחיטה זו \u0003הלחם.\u0004 וכן הוא הדין אם \u0003שחטה\u0004 לקרבן התודה \u0003עד שלא\u0004 (בטרם) \u0003קרמו\u0004 (העלו קרום, התקשו) \u0003פניה\u0004 (פני השטח החיצוני) של עיסת הלחמים הנאפית \u0003בתנור, ואפילו\u0004 אם שחט את קרבן התודה כאשר כבר \u0003קרמו\u0004 פניהם של כל לחמי התודה \u0003כולן חוץ מאחד מהן\u0004 שבאותה עת עדיין לא קרמו פניו — \u0003לא קדש\u0004 (התקדש) בכך כלל \u0003הלחם,\u0004 ואף לא הלחמים שקרמו פניהם קודם שחיטת התודה.","שנינו במשנתנו כי כאשר החלות הבאות עם התודה מחוץ לחומה בשעת שחיטת קרבן התודה לא התקדשו. ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש, מה הכוונה\u0005]\u0006 \u0003חוץ לחומה,\u0004 מחוץ לאיזו חומה מדובר? \u0003ר' יוחנן אמר:\u0004 \u0003חוץ לחומת בית פאגי\u0004 שבירושלים. \u0003ו\u0004אילו \u0003ריש לקיש אמר:\u0004 \u0003חוץ לחומת העזרה\u0004 שבהר הבית.","ומסבירים את שיטותיהם: \u0003ריש לקיש\u0004 ש\u0003אמר\u0004 כי הכוונה לתחום שמ \u0003חוץ לחומת העזרה,\u0004 טעמו הוא משום שנאמר בדינם של לחמי התודה שהריהם קרבים \"על זבח התודה\" (\"והקריב על זבח התודה חלות מצות בלולות בשמן\". ויקרא ז, יב), ולכך \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 בלחמי התודה המתקדשים בשחיטת זבח התודה, שתתקיים משמעות הלשון \u0003\"על\"\u0004 שהוא: \u0003בסמוך.\u0004 וכאשר נמצאים לחמי התודה מחוץ לחומת העזרה, שוב אין הם נחשבים סמוכים לקרבן הנשחט בתוך העזרה.","\u0003ור' יוחנן\u0004 ש\u0003אמר\u0004 כי הכוונה היא לתחום שמ \u0003חוץ לחומת בית פאגי,\u0004 טעמו הוא משום שבמקום זה אסורה אכילתו של הלחם, ונפסל הוא משום יוצא. ולכך הוא גם לא מתקדש במקום זה. \u0003אבל\u0004 אם היה הלחם בשטח שמ \u0003חוץ לעזרה,\u0004 ואולם הריהו נמצא במקום המותר באכילה \u0003—\u0004 הריהו \u0003קדוש\u0004 על ידי שחיטת זבח התודה, \u0003ולא בעינן\u0004 \u0005[ולא צריכים אנו]\u0006 שיתקיים משמע הלשון \u0003\"על\" בסמוך\u0004 ממש.","ושואלים: מדוע נצרכו ר' יוחנן וריש לקיש לחלוק בדין לחמי התודה הנמצאים מחוץ לחומה בשעת שחיטת הזבח, \u0003והא\u0004 \u0005[והרי]\u0006 כבר \u0003איפליגו\u0004 \u0005[נחלקו]\u0006 \u0003בה,\u0004 בשאלה דומה, \u0003חדא זימנא\u0004 \u0005[פעם אחת]!\u0006","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בדין שחיטת קרבן הפסח: \u0003השוחט את\u0004 קרבן \u0003הפסח על החמץ,\u0004 שעדיין יש חמץ ברשותו באותה עת — הריהו \u0003עובר בלא תעשה\u0004 האמור בתורה \"לא תשחט על חמץ דם זבחי ולא ילין לבוקר זבח חג הפסח\". שמות לד, כה). \u0003ר' יהודה אומר: אף\u0004 השוחט את קרבן \u0003התמיד\u0004 של בין הערביים בערב הפסח על החמץ עובר. \u0003ו\u0004בהגדרת איסור זה של שחיטה בעוד חמץ ברשותו, \u0003אמר ריש לקיש: לעולם אינו חייב\u0004 משום \"לא תשחט על חמץ\" \u0003עד שיהא או לשוחט\u0004 את קרבן הפסח, \u0003או\u0004 \u0003לזורק\u0004 את דמו של הקרבן, \u0003או לאחד מבני חבורה\u0004 שנמנו יחד על קרבן פסח זה, חמץ ברשותו באותה עת, ואינו חייב עד שיהא החמץ \u0003עמו בעזרה. ור' יוחנן אמר:\u0004 כל אחד מאלה האמורים \u0003אף על פי שאין עמו\u0004 חמץ \u0003בעזרה\u0004 אלא בביתו מתחייב על \"לא תשחט על חמץ\"! ואם כן, הרי זו אותה מחלוקת אם \"על\" משמעו דווקא בסמוך או שלא.","ומשיבים: אף שנחלקו ר' יוחנן וריש לקיש בשאלה דומה, עדיין \u0003צריכא\u0004 \u0005[צריך]\u0006 להשמיענו אף את מחלוקתם זו. משום \u0003דאי איתמר בההיא\u0004 \u0005[שאם היתה נאמרת\u0006 מחלוקתם רק \u0005באותה\u0006 הלכה, בקרבן הפסח\u0005],\u0006 ולא בדין לחמי התודה, הייתי אומר כי דווקא \u0003ב\u0004הלכה \u0003ההיא קא\u0004 \u0005[הוא]\u0006 ש\u0003אמר ר' יוחנן\u0004 שעוברים על האיסור אף בזמן שאין החמץ נמצא בעזרה, וטעם הדבר: משום ש\u0003כל היכא דאיתיה\u0004 \u0005[היכן שנמצא]\u0006 בו החמץ — \u0003באיסורא קאי\u0004 \u0005[באיסור\u0006 \"בל ימצא\" הוא \u0005עומד].\u0006 \u0003אבל לענין\u0004 שיהא \u0003מקדש\u0004 \u0005[מתקדש]\u0006 ה\u0003לחם\u0004 הבא עם קרבן התודה על ידי שחיטת קרבן התודה — שמא \u0003אימא\u0004 \u0005[אומר]\u0006 כי \u0003מודי ליה\u0004 \u0005[מודה לו]\u0006 ר' יוחנן \u0003לריש לקיש, דאי איתיה\u0004 \u0005[שאם ישנו]\u0006 הלחם בשעת השחיטה \u0003בפנים\u0004 — הריהו \u0003קדוש,\u0004 ואולם אם הוא נמצא \u0003אבראי\u0004 \u0005[מבחוץ]\u0006 למקדש — \u0003הוא\u0004 \u0003לא קדוש. ו\u0004","להיפך, \u0003אי איתמר בהא\u0004 \u0005[ואם היתה נאמרת\u0006 מחלוקת ר' יוחנן וריש לקיש רק \u0005ב\u0006הלכה \u0005זו,\u0006 בדין קידוש לחמי תודה\u0005]\u0006 היינו אומרים כי דווקא \u0003בהא קאמר\u0004 \u0005[ב\u0006הלכה \u0005זו אמר]\u0006 \u0003ריש לקיש\u0004 שאם היו הלחמים בשעת שחיטת הקרבן שלא בעזרה — הם לא התקדשו, \u0003אבל בהך\u0004 \u0005[בזו\u0006 בענין קרבן הפסח\u0005]\u0006 \u0003אימא\u0004 \u0005[אומר]\u0006 ש\u0003מודה\u0004 ריש לקיש \u0003ליה\u0004 \u0005[לו]\u0006 \u0003לר' יוחנן,\u0004 שהריהו עובר על איסור \"לא תשחט על חמץ\" אף שאין החמץ עמו בעזרה. על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שתובאנה שתי המחלוקות.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן: השוחט את\u0004 קרבן \u0003התודה\u0004 כדינה, כשהיא \u0003לפנים\u0004 (בעזרה), \u0003ו\u0004באותה עת היה \u0003לחמה חוץ לחומת בית פאגי\u0004 — \u0003לא קדש\u0004 בכך \u0003הלחם.\u0004","שנינו במשנתנו כי אם \u0003שחטה\u0004 לקרבן התודה \u0003עד שלא\u0004 (בטרם) \u0003קרמו פניה\u0004 של הלחמים \u0003בתנור\u0004 — אין הלחמים מתקדשים. וכן שנינו עוד שאם נשחט קרבן התודה שלא לשמו אין מתקדשים לחמי התודה.","ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין,\u0006 מה מקור \u0005הדברים הללו]?\u0006 — \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]\u0006 על הנאמר בלחמי התודה \u0003\"על חלות לחם חמץ יקריב קרבנו על זבח\u0004 תודת שלמיו\" (ויקרא ז, יג) — \u0003מלמד שאין הלחם קדוש\u0004 (מתקדש) בשחיטת קרבן התודה \u0003אלא אם כן\u0004 כבר \u0003קרמו פניה בתנור,\u0004 שרק לאחר שהם כבר מוגדרים כ\"חלות לחם\" — \"יקריב קרבנו\". והכתוב \u0003\"יקריב קרבנו על זבח\"\u0004 — \u0003מלמד שאין הלחם קדוש אלא בשחיטת הזבח.\u0004 והכתוב \u0003\"זבח תודת\u0004 שלמיו\" — \u0003מלמד שאם שחט\u0004 את קרבן התודה \u0003שלא לשמן\u0004 — \u0003לא קדש\u0004 בכך \u0003הלחם.\u0004","שנינו במשנתנו דינם של לחמי תודה שטרם נאפו בשעת שחיטת הקרבן, ומביאים עוד בענין דומה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יוצאין\u0004 ידי חובת אכילת מצה בחג הפסח אף \u0003במצה\u0004 שאינה אפויה כל צורכה, אלא \u0003נא\u0004 (אפויה חלקית), \u0003ו\u0004כן \u0003במצה העשויה ב\u0004כלי ה\u0003אילפס,\u0004 ולא נאפתה בתנור. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 ההגדרה של \u0003מצה נא\u0004 שיוצאים בה ידי חובת המצוה? \u0003אמר רב יהודה,\u0004 \u0003אמר שמואל: כל\u0004 מצה \u0003ש\u0004אף שנאפתה חלקית אדם \u0003פורסה\u0004 (חותך אותה). \u0003ואין חוטין\u0004 של בצק \u0003נמשכין הימנה,\u0004 הרי זו היא מצה נא הכשרה למצות מצה.","\u0003אמר רבא: וכן\u0004 הוא הדין \u0003לענין לחמי תודה,\u0004 שאם בשעת שחיטת קרבן התודה היו כבר לחמי התודה בשלב אפיה שכזה, הריהם מתקדשים בשחיטה זו. ושואלים: מדוע נזקק רבא להשמיענו זאת, \u0003והרי\u0004 \u0003פשיטא\u0004 \u0005[פשוט\u0006 הוא\u0005],\u0006 שכך הדין אף בלחמי תודה, \u0003שהרי\u0004 \u0003הכא\u0004 \u0005[כאן,\u0006 במצה\u0005]\u0006 \u0003\"לחם\" כתיב\u0004 \u0005[נאמר],\u0006 כנאמר \u0005\"לחם עוני\" (\"...שבעת ימים תאכל עליו מצות לחם עוני...\". דברים טז, ג),\u0006 \u0003ו\u0004כמו כן אף \u0003הכא\u0004 \u0005[כאן,\u0006 בלחמי תודה\u0005]\u0006 \u0003\"לחם\" כתיב\u0004 \u0005[נאמר],\u0006 ושווים הם בדינם\u0005!\u0006","ומשיבים: נצרך \u0003רבא להשמיענו, שכן\u0004 \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כיון שכלל הלכתי הוא בדין לחמי התודה: \u0003\"אחד\"\u0004 (\"והקריב ממנו אחד מכל קרבן תרומה לה' \". ויקרא ז, יד) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 — ומכאן הוראה, \u0003שלא יטול\u0004 ללחמי התודה חלק לחם שהוא \u0003פרוס,\u0004 אלא לחם שלם. \u0003ו\u0004אילו \u0003הא\u0004 \u0005[זו,\u0006 חלת נא\u0005],\u0006 אף היא הריהי \u0003כמאן דפריסא דמיא\u0004 \u0005[כמי שפרוסה דומה,\u0006 נחשבת\u0005],\u0006 ותהא פסולה ללחמי תודה. לכך \u0003קמשמע לן\u0004 \u0005[הוא,\u0006 רבא, \u0005משמיע לנו]\u0006 שמכיון שהיא אפויה עד כדי כך הריהי נחשבת כלחם אחד, וכשרה לתודה.","ועוד בדיני לחמי התודה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בדינה של \u0003תודה ששחטה על שמונים חלות,\u0004 ולא על ארבעים חלות, כראוי. \u0003חזקיה אמר: קדשו ארבעים\u0004 חלות \u0003מתוך\u0004 ה\u0003שמונים, ו\u0004אילו \u0003ר' יוחנן אמר: לא קדשו\u0004 אפילו \u0003ארבעים מתוך\u0004 ה\u0003שמונים.\u0004","ובהסבר מחלוקת זו \u0003אמר ר' זירא: הכל,\u0004 ואף ר' יוחנן, \u0003מודים\u0004 ש\u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003אמר\u0004 המקדיש את התודה בשעת הקדשתו אותה \u0003\"ליקדשו\u0004 \u0005[שיתקדשו]\u0006 \u0003ארבעים\u0004 חלות \u0003מתוך\u0004 ה\u0003שמונים\"\u0004 — אכן \u0003קדשו\u0004 ארבעים, אף שהיו בשעת השחיטה שמונים חלות. וכן הכל מודים, ואף חזקיה, שאם המקדיש את התודה אמר בשעת הקדשתו אותה \u0003\"אל יקדשו ארבעים\u0004 חלות, \u0003אלא אם כן יקדשו\u0004 כל ה\u0003שמונים\u0004 חלות\" — \u0003לא קדשו\u0004 כלל החלות. ו\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 חזקיה ור' יוחנן, הרי זה כשהביא \u0003בסתמא\u0004 \u0005[בסתם]\u0006 את קרבן התודה ושמונים חלות אתו. ונחלקו חכמים אלה בפירוש כוונתו של המקדיש: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חזקיה, \u0005סבור]\u0006 כי אף על פי שהביא שמונים חלות — לא התכוון אלא שיקדשו ארבעים מהן, ואילו הארבעים האחרות שהביא — \u0003לאחריות קא מיכוין\u0004 \u0005[הוא מתכוון],\u0006 שאם יאבדו הארבעים הראשונות, יבואו לחמי התודה מהארבעים הנוספים, אך לא התכוון לקדשם מלכתחילה, ולכך לא חלה קדושה עליהם, אלא על ארבעים מתוך השמונים. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 כי \u0003לקרבן גדול\u0004 של שמונים חלות \u0003קא מיכוין\u0004 \u0005[הוא מתכוון],\u0006 ומשום כך לא חלה קדושה עליהם כלל.","\u0003אביי אמר\u0004 הסבר אחר למחלוקת זו של חזקיה ור' יוחנן: דעתם \u0003דכולי עלמא\u0004 \u0005[של הכל],\u0006 ואף של ר' יוחנן, כי המביא שמונים חלות בתודתו במקום ארבעים, הרי זה משום ש\u0003לאחריות קא מיכוין\u0004 \u0005[הוא מתכוון],\u0006 ולא שתתקדשנה כל השמונים חלות\u0005,\u0006 \u0003ו\u0004אולם \u0003ב\u0004שאלה אחרת, האם \u0003כלי שרת\u0004 (כגון הסכין בו נשחט קרבן התודה, המקדש בשחיטתו את חלות התודה), הריהם \u0003מקדשין\u0004 אף \u0003שלא מדעת\u0004 מביא הקרבן, \u0003קא מיפלגי\u0004 \u0005[הם נחלקו].\u0006 שכך נחלקו: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חזקיה, \u0005סבור]\u0006 \u0003כלי שרת מקדשין\u0004 גם \u0003שלא מדעת\u0004 מביא הקרבן, שכיון שנעשתה בהם מלאכה בכלי שרת הרי נתקדשו, ולכך מתקדשות אף ארבעים החלות הנוספות (הגם שנועדו, לדעת המקדיש, לשמש רק כאחריות), שכן קידשן הסכין בשחיטת הקרבן. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 כי \u0003כלי שרת אין מקדשין שלא מדעת\u0004 המקדיש, ולכך אין מתקדשות אלא ארבעים חלות, וכדעת המקדיש.","\u0003רב פפא אמר\u0004 הסבר אחר למחלוקת זו של חזקיה ור' יוחנן: דעתם \u0003דכולי עלמא\u0004 \u0005[של הכל],\u0006 ואף של ר' יוחנן, כי \u0003כלי שרת מקדשין\u0004 גם \u0003שלא מדעת\u0004 המקדיש, \u0003ו\u0004אולם \u0003הכא\u0004 \u0005[כאן]\u0006 בדינו של \u0003סכין\u0004 השחיטה \u0003קא מיפלגי\u0004 \u0005[הם חלוקים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חזקיה, \u0005סבור]:\u0006 \u0003סכין מקדשת כ\u0004שאר \u0003כלי שרת,\u0004 ולכך מתקדשות כל השמונים חלות בשחיטת הקרבן, \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 כי \u0003סכין\u0004 שחיטה, \u0003כיון דלית ליה\u0004 \u0005[שאין לה]\u0006 \u0003תוך\u0004 (בית קיבול), שהרי היא שטוחה — \u0003אינה מקדשת,\u0004 ולענין זה אין הסכין \u0003ב\u0004כלל \u0003כלי שרת.\u0004","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שכך \u0003רב פפא אמר\u0004 בהסבר מחלוקת חזקיה ור' יוחנן, ובאופן אחר: דעתם \u0003דכולי עלמא\u0004 \u0005[של הכל],\u0006 ואף של חזקיה כי כל \u0003כלי\u0004 ה\u0003שרת\u0004 אכן \u0003אין מקדשין אלא מדעת\u0004 המקדיש, \u0003ו\u0004אולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004דינו של \u0003סכין\u0004 השחיטה לענין קידוש לחמי התודה \u0003קא מיפלגי\u0004 \u0005[הם,\u0006 חזקיה ור' יוחנן, \u0005חלוקים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חזקיה, \u0005סבור]\u0006 כי \u0003סכין אלימא\u0004 \u0005[תקיפה,\u0006 גדול כוחה\u0005]\u0006 יותר \u0003מכלי שרת,\u0004 ולכך הסכין מקדשת אף שלא מדעת המקדיש, ומשום כך התקדשו גם הארבעים החלות הנוספות. וטעם הדבר שגדול כח הסכין מכח שאר כלי שרת: שכן הסכין, \u0003אף על גב דלית ליה\u0004 \u0005[אף על פי שאין לה]\u0006 \u0003תוך,\u0004 בכל זאת הריהי \u0003מיקדשה\u0004 \u0005[מקדשת],\u0006 ושלא כשאר כלי השרת, שאמנם מקדשים, אבל רק בהיותם בעלי בית קיבול. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 כי \u0003סכין לא אלימא ליה\u0004 \u0005[אינה חזקה לו,\u0006 לדעתו\u0005]\u0006 יותר \u0003מ\u0004שאר \u0003כלי שרת,\u0004 וכשם ששאר כלי שרת אין מקדשים שלא מדעת, אף סכין השחיטה אינה מקדשת שלא מדעת, ולכך לא התקדשו אלא ארבעים חלות מתוך השמונים.","אם הכהן השוחט את קרבן התודה \u0003שחטה\u0004 במחשבה על מנת לאוכלה למחרת היום, או להקטיר את החלקים הקרבים על המזבח (אימורים), שהוא \u0003חוץ\u0004 (מעבר) \u0003לזמנה\u0004 הראוי (שכן התודה אינה נאכלת אלא ליום ולילה), או ששחטה הכהן על מנת לאכול מבשרה מ\u0003חוץ למקומה\u0004 הראוי לאכילה — \u0003קדש הלחם\u0004 (החלות הבאות עם התודה) והתפגלו (במחשבת חוץ לזמן) או נפסלו (במחשבת חוץ למקום). אם \u0003שחטה\u0004 את התודה \u0003ו\u0004לאחר מכן \u0003נמצאת\u0004 שהיא \u0003טריפה\u0004 (שיש בה מום מסויים שיביאנה לכלל מיתה, והריהי טריפה בכך, ופסולה להקרבה) — \u0003לא קדש הלחם\u0004 בשחיטה זו, שכן קדם פסולו של הקרבן לשחיטתו.","אם \u0003שחטה\u0004 לקרבן התודה, \u0003ו\u0004לאחר \u0003מכן\u0004 \u0003נמצאת\u0004 שהיא \u0003בעלת מום\u0004 (שדינה של בהמה שיש בה מום שכזה, שמלכתחילה אין היא קריבה על המזבח, ואולם אם העלוה למזבח — לא תורד ממנו, ותוקרב). ונחלקו חכמים בדינם של הלחמים. ש\u0003ר' אליעזר אומר: קידש\u0004 (התקדשו) לחמי התודה הזו, שהרי דינה הוא שאם עלתה — שוב לא תרד, ותוקרב. \u0003ו\u0004אילו \u0003חכמים אומרים\u0004 כי לחמי התודה \u0003לא קידש,\u0004 שכן דינה של זו, שלכתחילה אין היא קריבה על המזבח.","אם \u0003שחטה\u0004 לקרבן התודה \u0003שלא לשמה\u0004 (לשם קרבן תודה) אלא לשם קרבן אחר, \u0003וכן\u0004 הוא הדין בלחמים הבאים עם \u0003איל המילואים\u0004 (שהובא בשעה שנכנסו אהרן ובניו לעבודת כהונתם במשכן במדבר סיני), שנשחט שלא לשמו, אלא לשם קרבן אחר. \u0003וכן\u0004 הוא הדין בלחמים הבאים בחג השבועות עם \u0003שני כבשי עצרת ששחטן שלא לשמן\u0004 אלא לשם קרבן אחר — שבכל אלה \u0003לא קדש הלחם.\u0004","שנינו במשנתנו שאם שחט את התודה במחשבת אכילה חוץ לזמנה הראוי או חוץ למקומה הראוי — התקדשו לחמי התודה. ועוד שנינו כי אם נשחטה התודה ולאחר מכן נמצא שהיא טריפה — לא קדשו הלחמים, ואם נמצאה לאחר שנשחטה שהיא בעלת מום, נחלקו בדבר ר' אליעזר וחכמים, שר' אליעזר אומר שהתקדשו הלחמים, וחכמים אומרים שלא התקדשו. ושואלים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' מאיר,\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בדין התקדשותם של לחמי התודה בשחיטת הקרבן שנמצא פסול לאחר מכן, \u0003זה הכלל: כל שפיסולו\u0004 (גורם פסילתו) של קרבן התודה היה כבר קיים \u0003קודם\u0004 ה\u0003שחיטה\u0004 של הקרבן — \u0003לא קדש הלחם\u0004 בשחיטה. וכל ש\u0003פיסולו\u0004 של הקרבן אינו אלא \u0003ל\u0004\u0003אחר\u0004 ה\u0003שחיטה\u0004 — \u0003קדש הלחם.\u0004 ולכן, אם \u0003שחטה\u0004 במחשבת אכילה \u0003חוץ לזמנה וחוץ למקומה,\u0004 כיון שהשחיטה עצמה היתה כשרה — \u0003קדש הלחם.\u0004 אבל אם \u0003שחטה ונמצאת טריפה,\u0004 והרי איפוא סיבת הפסול היתה בקרבן קודם השחיטה — \u0003לא קדש הלחם.\u0004"],["ואם \u0003שחטה ונמצאת\u0004 לאחר מכן שהיא \u0003בעלת מום,\u0004 באופן זה נחלקו חכמים, ש\u0003ר' אליעזר אומר\u0004 כי \u0003קדש\u0004 הלחם, ואילו \u0003ר' יהושע אומר\u0004 כי הלחם \u0003לא קדש,\u0004 אלו \u0003דברי ר' מאיר,\u0004 וכדרך שבאו הדברים הללו במשנתנו.","ואילו ר' יהודה מעמיד באופן שונה את מחלוקת ר' אליעזר ור' יהושע, שכך \u0003אמר ר' יהודה: לא נחלקו ר' אליעזר ור' יהושע על\u0004 המקרה \u0003ששחטה ונמצאת טריפה\u0004 — \u0003ש\u0004כן באופן זה הכל מודים ש\u0003לא קדש\u0004 הלחם (וכדברי משנתנו, וכן הם דברי ר' מאיר). \u0003ו\u0004כן לא נחלקו ר' אליעזר ור' יהושע \u0003על\u0004 המקרה שבו נשחט התודה במחשבת \u0003חוץ לזמנו\u0004 — שכן באופן זה הכל מודים \u0003שקדש\u0004 הלחם (ואף בכך, כדברי משנתנו וכדברי ר' מאיר). \u0003ו\u0004כן לא נחלקו ר' אליעזר ור' יהושע \u0003על\u0004 המקרה ששחט את התודה, ונמצא לאחר מכן שהקרבן הוא \u0003בעל מום\u0004 — שכן באופן זה הכל מודים \u0003שלא קדש\u0004 הלחם (ושלא כדברי משנתנו ודברי ר' מאיר, שהעמידו בדבר זה את מחלוקת ר' אליעזר ור' יהושע). \u0003ועל מה נחלקו\u0004 ר' אליעזר ור' יהושע? \u0003על\u0004 המקרה שבו נשחט קרבן התודה במחשבת \u0003חוץ למקומו, שר' אליעזר אומר\u0004 כי במקרה זה \u0003קדש\u0004 הלחם, \u0003ו\u0004אילו \u0003ר' יהושע אומר\u0004 שבמקרה זה \u0003לא קדש\u0004 הלחם.","ובהסבר שיטתו \u0003אמר ר' אליעזר: הואיל ו\u0004קרבן שבשעת שחיטתו היתה בו מחשבת \u0003חוץ לזמנו\u0004 הריהו \u0003פסול, ו\u0004כמו כן אף קרבן שנחשבה בו בשעת שחיטתו מחשבת \u0003חוץ למקומו\u0004 הריהו \u0003פסול.\u0004 מעתה יש להשוותם עוד ולומר: \u0003מה\u0004 במקרה של מחשבת \u0003חוץ לזמנו\u0004 — \u0003קדש\u0004 הלחם, \u0003אף\u0004 במחשבת \u0003חוץ למקומו\u0004 — \u0003קדש\u0004 הלחם. \u0003אמר ר' יהושע\u0004 בהסבר שיטתו: \u0003הואיל ו\u0004הנשחט במחשבת \u0003חוץ למקומו\u0004 הריהו \u0003פסול, ו\u0004כמו כן אף הנשחט ונמצא שהוא \u0003בעל מום\u0004 הריהו \u0003פסול,\u0004 מעתה יש להשוותם עוד ולומר: \u0003מה\u0004 הנשחט ונמצא שהוא \u0003בעל מום\u0004 — \u0003לא קדש\u0004 הלחם, \u0003אף\u0004 הנשחט במחשבת \u0003חוץ למקומו\u0004 — \u0003לא קדש\u0004 הלחם.","\u0003אמר לו ר' אליעזר: אני דמיתיהו\u0004 את הנשחט במחשבת חוץ למקומו \u0003ל\u0004נשחט במחשבת \u0003חוץ לזמנו, ו\u0004אילו \u0003אתה דמיתו ל\u0004נשחט ונמצא שהוא \u0003בעל מום, נראה למי\u0004 הריהו \u0003דומה, אם\u0004 יתברר מתוך דיוננו שהריהו \u0003דומה לחוץ לזמנו,\u0004 כדעתי — \u0003נדוננו\u0004 (נלמד את דינו) \u0003מ\u0004השוואתו לשוחט במחשבת \u0003חוץ לזמנו,\u0004 ו\u0003אם\u0004 יתברר לנו שהריהו \u0003דומה ל\u0004נשחט ונמצא \u0003בעל מום,\u0004 כדבריך — \u0003נדוננו מבעל מום.\u0004","\u0003התחיל ר' אליעזר לדון: דנין\u0004 (יש ללמוד מהשוואה) של הדבר שהוא \u0003פסול מחשבה\u0004 (השוחט במחשבת חוץ למקומו) \u0003מ\u0004הדבר שאף הוא \u0003פסול מחשבה\u0004 (השוחט במחשבת חוץ לזמנו). \u0003ואין דנין\u0004 דינו של \u0003הדבר שהוא\u0004 \u0003פסול מחשבה\u0004 (השוחט במחשבת חוץ למקומו) \u0003מ\u0004הדבר שהוא \u0003פסול הגוף\u0004 (בעל מום).","\u0003התחיל ר' יהושע לדון\u0004 באופן אחר: \u0003דנין\u0004 (יש ללמוד מהשוואה) של הדבר שהוא \u0003פסול שאין בו\u0004 עונש \u0003כרת\u0004 על אכילתו (כגון הקרבן הנפסל במחשבת חוץ למקומו) \u0003מ\u0004הדבר שאף הוא \u0003פסול שאין בו כרת\u0004 (כבעל מום). \u0003ואל יוכיח\u0004 הנשחט במחשבת \u0003חוץ לזמנו\u0004 לקבוע דינו של הנשחט במחשבת חוץ למקומו, \u0003ש\u0004כן הריהו \u0003פסול שיש בו\u0004 עונש \u0003כרת\u0004 על אכילתו. \u0003ועוד\u0004 אמר ר' יהושע לר' אליעזר: \u0003נדוננו\u0004 (נלמד דינו של לחם התודה בשוחט במחשבת חוץ למקומו) \u0003מ\u0004דינו של לחם התודה בשוחט במחשבת \u0003שלא לשמו\u0004 של קרבן תודה אלא לשם קרבן אחר, \u0003ש\u0004כן אף הוא הריהו \u0003פסול מחשבה\u0004 (וכשיטתך, שיש להשוות בין הדברים שהם פסולי מחשבה), \u0003ו\u0004כמו כן \u0003אין בו\u0004 עונש \u0003כרת\u0004 על אכילתו (וכשיטתי, שיש להשוות בין הדברים שאין באכילתם עונש כרת). ומעתה נסיק, כי כשם שבשחיטה שלא לשמה — לא קדש הלחם, אף בשחיטה במחשבת חוץ למקומו — לא קדש הלחם.","\u0003ושתק ר' אליעזר,\u0004 ולא השיב על דבריו. ונמצא ששיטת משנתנו כי כשיטת רבי מאיר.","\u0003ו\u0004שואלים: לשיטת \u0003ר' מאיר\u0004 (שהיא שיטת משנתנו) הסבור כי אם נשחט קרבן התודה ונמצא שהוא \u0003טריפה\u0004 — לא קדש הלחם, ואולם אם נשחט קרבן התודה ונמצא שהוא בעל מום — קדש הלחם (לשיטת ר' אליעזר), \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003שחטה ונמצאת טריפה, דהוי\u0004 \u0005[שהריהו\u0006 נחשב\u0005]\u0006 ש\u0003פסולו קודם שחיטה,\u0004 ולכך אין הלחם קדוש, \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 \u0003שחטה ונמצאת בעלת מום\u0004 שאנו אומרים ש\u0003לא הוי\u0004 \u0005[אין הוא\u0006 נחשב\u0005]\u0006 ש\u0003פסולו קודם שחיטה,\u0004 ולכך הלחם קדוש.","ומשיבים: מדובר שם בדוקין, שלא היה מום גלוי ממש אלא \u0003בדוקין\u0004 (כעין קרומים) \u0003שבעין, ואליבא\u0004 \u0005[ועל פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' עקיבא,\u0004 ש\u0003אמר\u0004 כי בסוג מומים שכזה, שאינו ניכר, אף שפסולים הם להקרבה, מכל מקום \u0003אם\u0004 כבר \u0003עלו\u0004 על המזבח להקרבה — \u0003לא ירדו\u0004 ממנו, ויוקרבו כפי שהם. \u0003ור' יהושע\u0004 הסבור (לשיטת ר' מאיר) שנמצאת בעלת מום לאחר שחיטה — לא קדש הלחם, אמר: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' עקיבא\u0004 את דינו \u0003בקרבנות ש\u0004\u0003אם עלו\u0004 כבר על המזבח, שוב \u0003לא ירדו\u0004 ממנו, ויוקרבו כפי שהם — הרי זה דווקא \u0003בפסולא דגופיה\u0004 \u0005[בפסול של גופו],\u0006 שאין הקרבן עצמו שעלה כבר על המזבח נפסל להקרבה, \u0003אבל\u0004 \u0003ל\u0004ענין \u0003קדושי\u0004 \u0005[שיתקדש]\u0006 ה\u0003לחם\u0004 על ידי שחיטתו של קרבן שכזה — \u0003לא\u0004 אמר ר' עקיבא את דינו.","ודנים עוד במחלוקת ר' אליעזר ור' יהושע המובאת בברייתא למעלה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 בדברי אמוראים בדינה של \u0003חטאת ששחטה\u0004 במחשבת אכילה \u0003חוץ לזמנה\u0004 הראוי, ונתפגלה בכך ופסולה היא להקרבה, \u0003אם\u0004 ארע ש\u0003עלתה\u0004 על המזבח שלא כדין — הרי זו \u0003לא תרד,\u0004 ותוקרב. ואם שחטה במחשבת אכילה \u0003חוץ למקומה\u0004 הראוי, נחלקו בדינה חכמים, ש\u0003רבא אמר: תרד\u0004 ולא תוקרב, ואילו \u0003רבה אמר: לא תרד.\u0004","ומציעים בהסבר מחלוקתם: \u0003רבא\u0004 הריהו סבור \u0003כר' יהושע\u0004 הלמד (לענין קדושת לחמי תודה) את דינו של הקרבן שנשחט במחשבת חוץ למקומו מדינו \u0003של קרבן בעל מום. וכשם שחטאת בעלת מום הריהי יורדת מהמזבח אף אם כבר הועלתה עליו, כן הוא בחטאת שנשחטה במחשבת חוץ למקומו.\u0004 \u0003ו\u0004אילו \u0003רבה\u0004 סבור \u0003כר' אליעזר\u0004 הלומד את דינו של הקרבן הנשחט במחשבת חוץ למקומו מהנשחט במחשבת חוץ לזמנו. וכשם שחטאת שנשחטה במחשבת חוץ לזמנה הריהי אינה מורדת מהמזבח אם כבר הועלתה עליו, אף חטאת שנשחטה במחשבת חוץ למקומו אינה מורדת.","\u0003והדר ביה\u0004 \u0005[וחזר בו]\u0006 \u0003רבה לגביה\u0004 \u0005[לגביו,\u0006 אצל\u0005]\u0006 שיטתו של \u0003רבא\u0004 בדין הורדת החטאת שנשחטה במחשבת חוץ למקומו, שאף רבה סבור עתה שתרד, \u0003מ\u0004אחר \u0003דהדר ביה\u0004 \u0005[שחזר בו]\u0006 \u0003ר' אליעזר לגביה\u0004 \u0005[לגביו,\u0006 אצל\u0005]\u0006 שיטתו של \u0003ר' יהושע,\u0004 שכן למדנו בברייתא ששתק והודה ר' אליעזר לדברי ר' יהושע, ומעתה יש להשוות את דין שחיטה במחשבת חוץ למקומו לבעל מום.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003אף על גב דהדר ביה\u0004 \u0005[אף על פי שחזר בו]\u0006 \u0003ר' אליעזר לגביה\u0004 \u0005[לגביו]\u0006 של \u0003ר' יהושע,\u0004 בדין קדושת לחמי תודה בנשחט במחשבת חוץ למקומו, מכל מקום \u0003רבה לגביה\u0004 \u0005[לגביו]\u0006 של \u0003רבא\u0004 בענין הורדה מן המזבח של חטאת שנשחטה במחשבת חוץ למקומה, \u0003לא הדר ביה\u0004 \u0005[לא חזר בו].\u0006 שכן דווקא \u0003התם\u0004 \u0005[שם,\u0006 לענין קדושת לחמי תודה\u0005]\u0006, חזר בו ר' אליעזר טעם הדבר \u0003הוא\u0004 משום \u0003דקאמר ליה\u0004 \u0005[שהוא,\u0006 ר' יהושע, \u0005אמר לו]\u0006 טעם נוסף ואחר, כי \u0003נדוננו\u0004 לנשחט במחשבת חוץ למקומו \u0003מ\u0004דינו של התודה שנשחט \u0003שלא לשמו.\u0004 \u0003אבל הכא\u0004 \u0005[כאן,\u0006 לענין הורדה מן המזבח\u0005],\u0006 \u0003אי דיינת ליה\u0004 \u0005[אם אתה דן אותו,\u0006 את החטאת שנשחטה במחשבת חוץ למקומה\u0005]\u0006 \u0003מ\u0004דינה של החטאת שנשחטה \u0003שלא לשמו\u0004 — הרי דינה של חטאת זו הוא ש\u0003אם עלתה, לא תרד.\u0004","שנינו עוד במשנתנו שאם \u0003שחטה\u0004 לקרבן התודה (וכן איל המילואים ושני כבשי העצרת שנשחטו) \u0003שלא לשמה\u0004 — לא קדשו לחמיהם. ובענין זה \u0003אמר רב פפא\u0004 בתמיהה: \u0003שבק\u0004 \u0005[הניח,\u0006 לא ציין\u0005]\u0006 ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 את לחמי \u0003איל נזיר,\u0004 שאף בהם כך הוא הדין אם נשחט הקרבן שלא לשמו, \u0003דשכיח\u0004 \u0005[שמצוי]\u0006 הוא, \u0003ונקיט\u0004 \u0005[ותפס,\u0006 וציין\u0005]\u0006 את \u0003איל המילואים,\u0004 שנדיר הוא, שהרי לא היה אלא בהיות בני ישראל במדבר סיני! \u0003ו\u0004מסבירים: ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 שהעדיף להזכיר דווקא את איל המילואים, הרי זה משום שאת \u0003עיקר\u0004 (ראשית) \u0003מילתא נקט\u0004 \u0005[הדבר תפס],\u0006 שכן איל המילואים היה הראשון בקרבנות שבא עם הלחם.","\u0003הנסכים\u0004 הבאים עם הקרבנות, \u0003שקדשו\u0004 (התקדשו) בשעת שחיטת הזבח, שהיו \u0003בכלי\u0004 שרת, \u0003ו\u0004אולם אחר כך \u0003נמצא\u0004 שה\u0003זבח פסול\u0004 (שנפסל לאחר שחיטה, כגון בזריקת דמו), ואין הוא קרב. מה יעשו בנסכים הללו? \u0003אם יש\u0004 באותה שעה \u0003זבח אחר,\u0004 שנשחט הקרבן ונצרך הוא לנסכים — \u0003יקריבו עמו\u0004 את הנסכים הללו, \u0003ואם לאו\u0004 \u0005[לא]\u0006 נמצא בשעה שנפסל הקרבן, קרבן אחר הזבוח ונצרך לנסכים — \u0003יפסלו\u0004 (מניחים אותם עד שיפסלו) \u0003בלינה,\u0004 ויישרפו.","שנינו במשנתנו בדינם של הנסכים המתקדשים ונמצא הזבח פסול, ועוד בענין זה \u0003אמר זעירי:\u0004 הנסכים הריהם עדיין חולין, אף שניתנו בכלי שרת. שכן \u0003אין הנסכים מתקדשין אלא בשחיטת הזבח,\u0004 ומעתה חלה קדושה עליהם לענין שיפסלו בלינה וביציאה ממקומם. ומסביר: \u0003מאי טעמא\u0004 \u0005[מה טעם,\u0006 מקור הדבר\u0005]?\u0006 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"...להקריב אשה לה' עולה ומנחה \u0003זבח ונסכים\u0004 דבר יום ביומו\" (ויקרא כג, לז), והרי זה מלמד שאין הנסכים אלא כהשלמה לזבח, שאין הם מתקדשים אלא בזביחת (בשחיטת) הקרבן אתו הם באים.","ושואלים על דברי זעירי אלה ממה ש\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003הנסכים שקדשו בכלי ונמצא זבח פסול, אם יש זבח אחר\u0004 — \u0003יקרבו עמו, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003יפסלו בלינה.\u0004","ויש לדייק בדברים הללו: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר במשנתנו במקרה \u0003דאיפסיל\u0004 \u0005[שנפסל]\u0006 הזבח \u0003בשחיטה,\u0004 ונמצא איפוא שלא התקדשו הנסכים בשחיטה זו, ומדוע נצרכים אנו לפוסלם בלינה (אם אין זבח אחר)? הרי מכאן שהתקדשו הם בכלי, ולא בשחיטת הזבח, ושלא כדברי זעירי! ודוחים: \u0003לא,\u0004 אין להקשות ממשנתנו, שכן אין המדובר בה שנפסל הזבח בשחיטה אלא \u0003דאיפסיל\u0004 \u0005[שנפסל]\u0006 \u0003בזריקה.\u0004 ולכך פוסלים את הנסכים בלינה, שכן התקדשו בשחיטת הזבח.","ומבררים עוד: להסבר זה של משנתנו, שהתקדשו הנסכים בשחיטת הזבח אף שלאחר מכן נפסל הזבח בזריקה, \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 היא משנתנו? \u0003כ\u0004שיטת \u0003רבי,\u0004 ש\u0003אמר\u0004 כי אם יש לקרבן \u0003שני דברים\u0004 (שתי פעולות) \u0003המתירין\u0004 אותו לאכילה (וכגון שחיטת התודה וזריקת דמה) הריהם חולין אף שניתנו בכלי שרת — הריהם שני מעשים אלה \u0003מעלין\u0004 (פועלים, להחיל קדושת הגוף על הקרבן ונסכיו), כל אחד כשלעצמו, מעשה \u0003זה\u0004 אף \u0003בלא\u0004 מעשה \u0003זה.\u0004 ולכך התקדשו הנסכים בשחיטת הזבח, אף שנפסל הזבח בזריקת הדם!","ודוחים: אין הכרח לטעון שמשנתנו היא דווקא כשיטת רבי, שכן \u0003אפילו\u0004 אם \u0003תימא\u0004 \u0005[תאמר]\u0006 שהיא כשיטת \u0003ר' אלעזר בר' שמעון,\u0004 החולק על רבי וסבור הוא שעל מנת להחיל קדושה על הקרבן והנלוים עליו, יש צורך בעשייתם של שני דברים המתירים אותו, גם כן אפשר להסביר את משנתנו, שכן \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים],\u0006 \u0003כגון\u0004 שלאחר \u0003ש\u0004נשחטו הקרבנות כהלכתם, עמד הכהן \u0003ו\u0004\u0003קיבל\u0004 את \u0003דמן בכוס\u0004 על מנת לזרוק את הדם על המזבח, כדין, שכבר היה ראוי דם הקרבן להיזרק על המזבח, \u0003ו\u0004ארע הדבר ש\u0003נשפך\u0004 הדם מן הכוס, ולא בא לכלל זריקה. ומעתה אין איפוא המדובר בדם שנפסל לזריקה על המזבח, אלא בדם שהיה ראוי לזריקה."],["\u0003ור' אלעזר בר' שמעון סבר לה\u0004 \u0005[הריהו סבור]\u0006 בענין זה \u0003כוותיה דאבוה\u0004 \u0005[כשיטתו של אביו],\u0006 שכן \u0003אמר\u0004 ר' שמעון ככלל הלכתי מקיף: \u0003כל\u0004 דם קרבן \u0003העומד\u0004 (הראוי) \u0003לזרוק\u0004 על המזבח — \u0003כ\u0004\u0003זרוק\u0004 הוא \u0003דמי\u0004 \u0005[נחשב],\u0006 אף שבפועל הוא לא נזרק על המזבח (כגון במקרה זה שלפנינו, שנשפך הדם ולא נזרק בפועל על המזבח).","ומבררים עוד את הנאמר במשנתנו. \u0003אמר מר\u0004 \u0005[החכם]\u0006 במשנתנו בדינם של הנסכים שקדשו בכלי שרת ונמצא הזבח פסול, ש\u0003אם יש זבח אחר\u0004 — \u0003יקרבו עמו.\u0004 ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב חסדא: שמן שהפרישו לשום\u0004 (לשם) \u0003מנחה זה\u0004 — הריהו \u0003פסול\u0004 מנתינתו \u0003לשום\u0004 (לשם) \u0003מנחה אחרת.\u0004 ואף נסכים אלה שהופרשו לשם הקרבתם עם קרבן זה, יהיו פסולים מהקרבתם עם קרבן אחר! \u0003אמר ר' ינאי\u0004 בתשובה: לא אמר רב חסדא את דינו אלא בשמן למנחה, ואולם אין כן הדין בנסכים הבאים עם הקרבנות. שכן בנסכים \u0003לב בית דין מתנה עליהם,\u0004 כלומר, רצון בית הדין יוצר בהם תנאי שאמנם לא נאמר, אבל הוא כוונת הדברים, ש\u0003אם\u0004 אכן \u0003הוצרכו\u0004 הנסכים לקרבן זה — הרי \u0003הוצרכו\u0004 ויינתנו עמו. \u0003ואם לאו\u0004 \u0005[לא]\u0006 נצרכים לקרבן זה (וכגון שנפסל הקרבן, וכדין משנתנו) — \u0003יהו לזבח אחר.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא הסבר המשנה, שלב בית דין מתנה על כך, ב\u0003שמן\u0004 שהופרש למנחה מסויימת ונפסלה המנחה, \u0003נמי\u0004 \u0005[גם כן]\u0006 נאמר שלב בית דין מתנה על כך, וינתן השמן למנחה אחרת! ומשיבים: יש הבדל בין שמן לנסכים, כי ה\u0003שמן\u0004 — \u0003גופה\u0004 \u0005[עצם]\u0006 ה\u0003מנחה הוא,\u0004 שהרי הוא נבלל בתוכה. ולכן שמן שהופרש למנחה זו, ונפסלה — לא ינתן למנחה אחרת. מה שאין כן נסכים, הנלוים אל הזבח, אם נפסל הזבח — ינתנו לזבח אחר הנצרך אותה שעה לנסכים.","\u0003ו\u0004מקשים עוד: אם הסבר משנתנו הוא משום שלב בית דין מתנה על הנסכים, שאם נפסל הקרבן שיינתנו הנסכים לקרבן אחר, \u0003ליתנו\u0004 \u0005[שיתנו]\u0006 בית הדין \u0003עליהן\u0004 שבאופן שבו נפסלו הזבחים, \u0003דניפקו\u0004 \u0005[שיצאו]\u0006 הנסכים \u0003לחולין\u0004 לגמרי! ומשיבים: אין לב בית דין מתנה כן, משום ה\u0003גזירה שמא\u0004 מתוך כך יבואו אנשים הרואים דבר שהתקדש ויוצא עתה לחולין, ו\u0003יאמרו\u0004 (מתוך אי ידיעה שתנאי בית דין היה בדבר) כי \u0003מוציאין\u0004 (מותר להוציא) דברים \u0003מ\u0004תוך \u0003כלי שרת לחול.\u0004","ומקשים על תירוץ זה: אם יש מקום לחשש זה, ולכך גזרו חכמים שלא יצאו הנסכים לחולין כשנפסלו הקרבנות, \u0003השתא\u0004 \u0005[עכשיו],\u0006 שהתנו בית דין על הנסכים, שבאופן שנפסלו הקרבנות, שיינתנו לקרבנות אחרים, \u0003נמי\u0004 \u0005[גם כן]\u0006 יש מקום לקבוע \u0003גזירה\u0004 מפני החשש \u0003שמא יאמרו\u0004 האנשים הרואים שנסכים שהופרשו לקרבן זה ניתנים לקרבן אחר, כי \u0003נסכים שהפרישן לשום\u0004 (לשם) \u0003זבח זה\u0004 — הריהם \u0003כשרין\u0004 מלכתחילה לתיתם \u0003לשום\u0004 (לשם) \u0003זבח אחר!\u0004","ומשיבים: \u0003התני\u0004 \u0005[הרי\u0006 כבר \u0005שנה,\u0006 פירש \u0005במשנה\u0006\u0005]\u0006 \u0003מתתיה בן יהודה\u0004 את דברי משנתנו \"אם יש זבח אחר\" — \u0003כגון שהיה זבח זבוח באותה שעה.\u0004 ומעתה אין מקום לחשש זה שיאמרו הרואים שנסכים ניתנים לקרבן אחר, שכן יחשבו שהופרשו הנסכים לקרבן זה השני. ומקשים על תירוץ זה: אם כדברי מתתיה בן יהודה היא משנתנו, שמדובר בה שהיה זבח זבוח באותה שעה, יש לדייק מכאן: דווקא באופן זה ניתנים הנסכים לקרבן האחר.","\u0003אבל\u0004 אם \u0003אין זבח זבוח באותה שעה, מאי\u0004 \u0005[מה]\u0006 יהא דינם של הנסכים? שמביאים אותם לכלל שיהיה הנסך \u0003נפסל בלינה,\u0004 ולאחר מכן מוצאים הם לשריפה. ואולם על כך יש לשאול: \u0003אדתני סיפא\u0004 \u0005[עד ששנה\u0006 ב\u0005סוף\u0006 המשנה\u0005]\u0006 את המקרה הבא: \u0003אם לאו\u0004 \u0005[לא]\u0006 נמצא זבח אחר הנצרך לנסכים — \u0003יפסלו\u0004 הנסכים \u0003בלינה,\u0004 עדיף \u0003ליפלוג וליתני בדידה\u0004 \u0005[לחלק ולשנות בה עצמה,\u0006 בתוך אותה הלכה\u0005]\u0006 חלוקה זו: \u0003במה דברים אמורים\u0004 שנותנים את הנסכים לקרבן אחר הנזקק לנסכים? דווקא כ\u0003שהיתה זבח זבוח באותה שעה, אבל\u0004 אם \u0003אין זבח זבוח באותה שעה\u0004 — \u0003לא\u0004 נותנים את הנסכים לקרבן אחר!","ומשיבים: אכן \u0003הכי נמי קא אמר\u0004 \u0005[כך גם כן הוא\u0006 התנא במשנתנו \u0005אמר],\u0006 שזו כוונת דבריו: \u0003במה דברים אמורים\u0004 שניתנים הנסכים לקרבן אחר? דווקא \u0003כ\u0004\u0003שהיה זבח זבוח באותה שעה, אבל אין זבח זבוח באותה שעה\u0004 — הרי זה \u0003נעשה\u0004 (נחשב) \u0003כמי שנפסלו\u0004 הנסכים \u0003בלינה, ופסולין\u0004 מלהינתן לקרבן אחר. ושואלים עוד: הוסבר למעלה, כי משנתנו הריהי אף כשיטת ר' אליעזר בנו של ר' שמעון, הסבור כשיטת אביו ר' שמעון (בכלל שקבע כי כל העומד להיזרק נחשב כזרוק).","ועוד הוסברו דברי משנתנו (על ידי ר' ינאי, כמבואר למעלה) שהם משום שלב בית דין מתנה על הנסכים שינתנו לקרבן אחר אם הקרבן שלשמו הופרשו נפסל, \u0003ו\u0004מעתה יש לשאול: \u0003מי אית ליה\u0004 \u0005[האם יש לו,\u0006 מקבל\u0005]\u0006 \u0003לר' שמעון בן אלעזר\u0004 סברה זו של \u0003לב בית דין מתנה עליהן?\u0004","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב אידי בר אבין\u0004 במסורת העוברת מפי חכמים, שכך \u0003אמר רב עמרם\u0004 שכך \u0003אמר ר' יצחק\u0004 שכך \u0003אמר ר' יוחנן:\u0004 קרבנות שהופרשו ל\u0003תמידין, שלא הוצרכו לציבור,\u0004 שהפרישו אותם לשם כך, ואחר כך התברר שאינם נצרכים, והרי הם קדושים בקדושת הגוף, כיצד ייפדו מהקדש לחולין? \u0003לדברי ר' שמעון\u0004 — \u0003אין\u0004 הם \u0003נפדין\u0004 כשהם \u0003תמימים\u0004 (ללא מום). ואילו \u0003לדברי חכמים\u0004 — הריהם \u0003נפדין\u0004 אף שהם \u0003תמימים.\u0004 שכן סבורים חכמים שלב בית דין מתנה עליהם, שאם לא יצטרכו אותם הציבור — ייפדו אף שהם תמימים. ומכאן עולה, כי ר' שמעון החלוק על חכמים, סבור שאין אומרים כי לב בית דין מתנה עליהם!","ומשיבים: אמנם אף ר' שמעון סבור כי לב בית דין מתנה. ואולם טעמו בקרבנות תמידים שאין הם נפדים אלא כבעלי מומים ולא כתמימים, ואין אומרים שלב בית דין מתנה שייפדו אף כשהם תמימים, שכן \u0003שאני התם\u0004 \u0005[שונה שם,\u0006 בתמידים\u0005],\u0006 \u0003דאית להו תקנתא\u0004 \u0005[שיש להם תקנה]\u0006 שלא יבואו \u0005לכלל הפסד,\u0006 \u0003ברעייה\u0004 בשדה, שמשאיר אותם לעצמם עד שיפול בהם מום, ואז ימכרו. מה שאין כן בנסכים שנפסל קרבנם, שאין להם תקנה אחרת, מלבד נתינתם לקרבן אחר הנצרך לנסכים, שבמקרה שכזה לב בית דין מתנה.","\u0003ולד\u0004 הנולד לבהמה שהוקדשה לקרבן \u0003תודה,\u0004 וכן \u0003תמורתה\u0004 של בהמה המוקדשת לקרבן תודה (שהמיר, אף שאסור לעשות כן, את בהמת ההקדש של תודה בבהמת חולין, שאמר \"זו תמורת זו\". ודינה של התמורה, שזו וזו קדושות הן). או ש\u0003הפריש\u0004 בהמה לקרבן \u0003תודה ואבדה,\u0004 ועמד \u0003והפריש אחרת תחתיה,\u0004 והקריב אותה כתודתו, ולאחר מכן מצא את הראשונה — שלושת אלה הקרבנות (ולד תודה, תמורת תודה, תודה שאבדה) \u0003אינה טעונה\u0004 (חייבת בהבאת) \u0003לחם\u0004 עמה, כתודה רגילה. \u0003ש\u0004כן \u0003נאמר\u0004 בדין התודה: \"אם על תודה יקריבנו \u0003והקריב על זבח התודה\u0004 חלות מצות בלולות בשמן ורקיקי מצות משוחים בשמן וסולת מורבכת חלות בלולות בשמן\" (ויקרא ז, יב). והרי זה בא למעט: דווקא \u0003התודה\u0004 עצמה היא ש\u0003טעונה לחם, ולא ולדה\u0004 של התודה, \u0003ולא חילופה\u0004 של התודה \u0003ולא תמורתה\u0004 של התודה \u0003טעונין לחם.\u0004","שנינו במשנתנו כי מן הכתוב \"אם על תודה יקריבנו והקריב על זבח התודה\" למדנו שאין ולד התודה ותמורת התודה וחילופי תודה טעונים הבאת חלות אתם. ועוד בענין הנלמד מכתוב זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 שנאמר בכתוב: \u0003מהו אומר\u0004 (מה מלמדנו האמור) \u0003\"תודה יקריב\"\u0004 (הנכלל בכתוב \"תודה יקריבנו\")? \u0003\"אם על תודה יקריב\", מנין למפריש\u0004 בהמה לצורך קרבן \u0003תודתו, ואבדה,\u0004 ועמד \u0003והפריש\u0004 בהמה \u0003אחרת תחתיה, ו\u0004לאחר מכן \u0003חזרה ו\u0004\u0003נמצאת\u0004 הבהמה \u0003הראשונה, ו\u0004עתה \u0003הרי שתיהן עומדות\u0004 לפניו להקרבה — \u0003מנין\u0004 לנו שהלכה היא \u0003שאיזה מהן שירצה,\u0004 אותה הוא \u0003יקריב ולחמה\u0004 בא \u0003עמה?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) \u0003\"התודה יקריב\"\u0004 — איזו מהן שירצה.","ומעתה יש מקום להוסיף ולשאול: \u0003יכול\u0004 יהא הדין \u0003שתהא\u0004 גם התודה ה\u0003שניה,\u0004 אחר שהוקרבה הראשונה עם לחמיה, \u0003טעונה\u0004 (חייבת בהבאת) \u0003לחם\u0004 אתה? לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) \u0003\"יקריבנו\"\u0004 — קרבן תודה \u0003אחד\u0004 קרב עם לחמיו, \u0003ולא שנים.\u0004 ודנים עוד: \u0003אחר שריבה הכתוב\u0004 לענין ההקרבה (מן האמור \"יקריב\"), \u0003ו\u0004כן \u0003גם\u0004 \u0003מיעט\u0004 הכתוב לענין הבאת הלחמים עם הקרבן (מן האמור \"יקריבנו\"), \u0003מנין\u0004 לנו \u0003לרבות ולדות\u0004 התודה \u0003וחליפות\u0004 התודה \u0003ותמורות\u0004 התודה \u0003להקרבה?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) \u0003\"אם על תודה\".\u0004 ועדיין יש לשאול: \u0003יכול\u0004 יהא הדין ש\u0003יהו\u0004 גם אלה \u0003טעונות לחם?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) \u0003\"והקריב על זבח התודה\"\u0004 — לומר ש\u0003תודה\u0004 עצמה היא ה\u0003טעונה לחם, ולא ולדה ולא חילופה ולא תמורתה טעונין לחם.\u0004","ועוד בענין ולד התודה וחילופי התודה ותמורת התודה נמסר כי \u0003שלח רב חנינא\u0004 מארץ ישראל לתלמידי חכמים שבבבל, איגרת ובה דברים \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן: לא שנו\u0004 במשנתנו שאין שלושת הקרבנות הללו חייבים בהבאת לחמי תודה, \u0003אלא לאחר כפרה,\u0004 אחר שכבר הובאה התודה וחלותיה, \u0003אבל לפני כפרה\u0004 — גם שלושת קרבנות אלה \u0003טעונין לחם.\u0004","ועוד נמסר כי \u0003הוי\u0004 \u0005[היה עוסק]\u0006 \u0003בה\u0004 בהלכה זו ומתקשה בה, \u0003רב עמרם,\u0004 שכך שאל בה: \u0003אהייא\u0004 \u0005[על איזו\u0006 הלכה במשנתנו, מתוך שלוש אלה הנזכרות בה\u0005]\u0006 מדבר ר' יוחנן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שכוונתו \u0003אחליפי\u0004 \u0005[על\u0006 בהמת \u0005חילופי]\u0006 \u0003תודת חובה\u0004 שהיה מחויב להביא אותה, והביא ראשונה ואבדה, והביא אחרת תחתיה, ונמצאה הראשונה — אין חידוש בדברי איגרתו של רב חנינא בשם ר' יוחנן. שכן \u0003אי\u0004 \u0005[אם]\u0006 לענין שנמצאה הראשונה \u0003לפני כפרה\u0004 שהתכפר בשניה, וללמדנו שהריהי חייבת בלחמים — הלכה זו כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 בברייתא, העוסקת \u0005בתודת חובה, ולמדנו בה מן הכתוב שמאיזה מהן שירצה יביא את תודתו ואת לחמה! ו\u0006\u0003אי\u0004 \u0005[אם]\u0006 לענין שנמצאה \u0005הראשונה\u0006 \u0003לאחר כפרה\u0004 שהתכפר בשניה, וללמדנו שהריהי פטורה מן הלחמים — אף הלכה זו גם כן כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 אותה, שכן למדנו בברייתא שרק הראשונה באה בלחמיה, ואין השניה באה בלחמים!"],["\u0003אלא\u0004 נאמר כי דברי ר' יוחנן עוסקים לא בחליפי תודת חובה אלא ב\u0003חליפי תודה נדבה\u0004 — אף זה קשה, שאין מקום להבחין בין לפני כפרה ובין לאחר כפרה, שכן בבהמת תודה שהובאה במקום זו שאבדה, דינה הוא \u0003בין\u0004 שנמצאה הראשונה \u0003לפני כפרה\u0004 שהביא את השניה ונרצה לו בה, ו\u0003בין\u0004 שנמצאה \u0003הראשונה\u0004 \u0003לאחר כפרה טעונות\u0004 — בשני האופנים הללו באות שתי התודות עם \u0003לחם,\u0004 שכן הרי זה \u0003מרבה בתודות הוא,\u0004 שהרי מכיון שלא היה מחויב גם בראשונה, אם הביא עוד אחרת הרי היא כתודה נוספת שרוצה להביא, ולכן אם מוסיף עוד תודה צריך להוסיף לה לחם!","\u0003אלא\u0004 צריך לומר שדברי ר' יוחנן עוסקים \u0003ב\u0004\u0003ולד\u0004 הנולד לבהמה שהוקדשה ל\u0003תודה\u0004 הבאה ב\u0003נדבה\u0004 — אף זה קשה, שאין מקום להבחין בין קרב הולד לפני כפרה (שטרם הוקרבה אמו כקרבן התודה) ובין לאחר כפרה (שכבר הוקרבה אמו לקרבן התודה), שהרי בולד תודה דינו הוא ש\u0003בין לפני כפרה בין לאחר כפרה\u0004 — \u0003אין טעונין לחם,\u0004 כי נחשב הדבר ל\u0003מותר\u0004 (תוסף) של ה\u0003תודה היא,\u0004 ואין תוספת התודה באה בלחמים! \u0003אלא\u0004 צריך לומר שבענינו של \u0003ולד תודה חובה\u0004 אמר ר' יוחנן את דבריו, כי אם הוא קרב \u0003לפני כפרה\u0004 — הריהו \u0003טעון לחם,\u0004 ואם הוא קרב \u0003לאחר כפרה\u0004 — \u0003אין\u0004 הוא \u0003טעון לחם.\u0004","ומסבירים: \u0003מאי קא משמע לן\u0004 \u0005[מה הוא,\u0006 ר' חנניה באיגרתו, \u0005משמיע לנו]\u0006 בדבריו אלה? \u0003דקסבר\u0004 \u0005[שסבור הוא]\u0006 \u0003ר' יוחנן\u0004 כי \u0003אדם מתכפר בשבח\u0004 (תוספת ויתרון) שנוסף על ה\u0003הקדש\u0004 המקורי אותו הוא הקדיש. וכגון המקריב את ולד התודה לחובתו, אף שהוא הקדיש את אמו לקרבן, הריהו מתכפר בוולד הנולד לה (שהריהו מכלל שבח ההקדש), ואם הקריב את ולד התודה קודם שהתכפר באמו — הריהו אף מביא אתו את לחמי התודה. \u0003ומוסרים:\u0004 \u0003הוי\u0004 \u0005[עסק,\u0006 התקשה\u0005]\u0006 \u0003בה\u0004 בדברי איגרתו של ר' חנניה, בשיטת ר' יוחנן, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אביי כי האי גוונא\u0004 \u0005[כעין זה]\u0006 שהתקשה בה רב עמרם, ואף אביי הגיע בסופו של דבר למסקנה כעין זו שהגיע אליה רב עמרם, שדברי ר' יוחנן הינם בעניינו של ולד תודת חובה.","ומוסיפים עוד בענין זה, שכהבנה זו של רב עמרם ואביי בדברי ר' יוחנן, \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 ש\u0003אמר רב יצחק בר יוסף,\u0004 \u0003אמר ר' יוחנן:\u0004 ב\u0003חילופי תודה נדבה\u0004 — אין הבדל בדין \u0003בין לפני כפרה, בין לאחר כפרה,\u0004 שכן בשני אופנים הללו \u0003הריהי\u0004 \u0003טעונה לחם,\u0004 וטעם הדבר: שכן \u0003מרבה בתודות הוא.\u0004 וכמו כן, אף ב\u0003ולד תודה נדבה\u0004 — אין הבדל בדין \u0003בין לפני כפרה, בין לאחר כפרה,\u0004 שכן בשני האופנים הללו הרי התודה \u0003אין טעון לחם,\u0004 וטעם הדבר: שכן \u0003מותר\u0004 של \u0003תודה הוא,\u0004 ואין מותר התודה חייב בחלות. \u0003ו\u0004אולם ב\u0003ולד תודה חובה\u0004 — יש הבדל בדין אם קרב לפני כפרה או לאחר כפרה. שכן אם קרב \u0003לפני כפרה\u0004 — הריהם \u0003טעונין לחם,\u0004 ואם קרב \u0003לאחר כפרה\u0004 — \u0003אין\u0004 הם \u0003טעונין לחם.\u0004","ומביאים עוד בענין לחמי תודה בקרבן תודה שאבד והופרש אחר תחתיו, \u0003אמר שמואל\u0004 כלל בדין חיוב לחמי תודה: ב\u0003כל\u0004 אחד מהאופנים \u0003ש\u0004ארעו \u0003ב\u0004קרבן \u0003חטאת\u0004 ונקבע בהם שה\u0003ריהי\u0004 \u0003מתה\u0004 (יש להביא אותה לכלל מיתה), אם ארע כדבר הזה \u0003ב\u0004קרבן \u0003תודה\u0004 — \u0003אין\u0004 היא \u0003טעונה לחם.\u0004 וב\u0003כל\u0004 אחד מהאופנים \u0003ש\u0004ארעו \u0003ב\u0004קרבן \u0003חטאת\u0004 ונקבע בהם שהריהי \u0003רועה\u0004 (יוצאת למרעה עד שיפול בה מום, ותיפדה), אם ארע כדבר הזה \u0003ב\u0004קרבן \u0003תודה\u0004 — הריהי \u0003טעונה לחם.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב עמרם\u0004 על קביעה זו המשווה את דין הלחמים בתודה לדין מיתה או רעייה בחטאת, מן הברייתא שהובאה למעלה, בה שנינו: \u0003מהו אומר\u0004 (מה מלמדנו האמור) \u0003\"התודה יקריב\"? מנין למפריש\u0004 בהמה לקרבן \u0003תודתו, ואבדה\u0004 הבהמה, ועמד \u0003והפריש\u0004 בהמה \u0003אחרת תחתיה, ו\u0004לאחר מכן \u0003נמצאת\u0004 הבהמה \u0003הראשונה, והרי\u0004 עתה \u0003שתיהן עומדות\u0004 (מזומנות) לפניו להקרבה, \u0003מנין\u0004 לנו \u0003ש\u0004הלכה היא כי \u0003איזו מהן שירצה,\u0004 אותה \u0003יקריב ולחמה\u0004 בא \u0003עמה?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) \u0003\"התודה יקריב\". יכול\u0004 יהא הדין ש\u0003תהא\u0004 אף התודה הקרבה \u0003שניה טעונה לחם?\u0004 לכך \u0003תלמוד לומר: \"יקריבנו\"\u0004 — בקרבן תודה \u0003אחד\u0004 בא הלחם, \u0003ולא\u0004 ב\u0003שנים.\u0004","\u0003ואילו גבי\u0004 \u0005[אצל]\u0006 קרבן \u0003חטאת\u0004 במקרה \u0003כי האי גונא\u0004 \u0005[כגון זה]\u0006 אין דינה של החטאת למיתה, אלא שהיא \u0003רועה,\u0004 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הפריש\u0004 בהמה ל\u0003חטאתו\u0004 שהוא חייב בה, \u0003ואבדה\u0004 בהמה זו, ועמד \u0003והפריש אחרת תחתיה, ו\u0004לאחר מכן \u0003נמצאת\u0004 הבהמה \u0003הראשונה, ו\u0004עתה \u0003הרי שתיהן עומדות\u0004 לפניו להקרבה — הריהו \u0003מתכפר באחת מהן\u0004 שירצה, \u0003ו\u0004הבהמה \u0003ה\u0004\u0003שניה תמות\u0004 (תובא למיתה), אלו \u0003דברי רבי. ו\u0004אילו \u0003חכמים\u0004 חולקים ו\u0003אומרים\u0004 שבאופן זה אין דין מיתה בחטאת השניה, שכן כלל הוא כי \u0003אין\u0004 קובעים בדינה של ה\u0003חטאת\u0004 שהיא \u0003מתה אלא\u0004 רק בזמן \u0003שנמצאת\u0004 הראשונה שאבדה \u0003לאחר ש\u0004כבר קרבה השניה ו\u0003נתכפרו\u0004 בה ה\u0003בעלים. הא\u0004 \u0005[הרי]\u0006 מכאן נלמד כי אם \u0005נמצאה החטאת הראשונה\u0006 \u0003קודם שנתכפרו בעלים\u0004 בשניה, ועתה הרי שתיהן עומדות לפניו להקרבה — הריהו מקריב אחת מהן, והאחרת \u0003רועה!\u0004","ומשיבים: \u0003שמואל כ\u0004דעת \u0003רבי סבירא ליה\u0004 \u0005[סבור הוא],\u0006 שכך \u0003אמר\u0004 רבי: בהמת חטאת שהיתה \u0003אבודה בשעת הפרשה\u0004 של בהמה שניה, אף שנמצאה לפני שהוקרבה השניה והתכפרו בה הבעלים — הריהי \u0003מתה,\u0004 ולא מוצאת לרעייה. והרי זה ככלל של שמואל המשווה בין דין מיתה בחטאת לבין פטור לחמים בתודה.","ושואלים על כך: \u0003אלא\u0004 מעתה, שאף באופן זה סבור רבי שבהמת החטאת האחרת הריהי מוצאת למיתה, אם כן הלכה זו בחטאת ה\u0003רועה, ל\u0004דעת \u0003רבי היכי משכחת לה\u0004 \u0005[כיצד אתה מוצא אותה]\u0006 שתהיה רועה? אין זה אלא \u0003כ\u0004דברי \u0003ר' אושעיא,\u0004 שכן \u0003אמר ר' אושעיא: הפריש\u0004 אדם \u0003שתי חטאות,\u0004 וטעם הפרשת שתי חטאות: האחת — לחובתו, והשניה — \u0003לאחריות,\u0004 שאם האחת תאבד, יביא את השניה. מה דינן של אלה? הריהו \u0003מתכפר באיזה מהן שירצה, והשניה\u0004 — \u0003תרעה. ו\u0004אולם","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 מקרה בקרבן \u0003תודה כי האי גוונא\u0004 \u0005[כגון זה]\u0006 \u0003אין טעונה לחם,\u0004 ואילו לדעת שמואל כל שבחטאת רועה, בתודה הריהי חייבת בלחם. ואין איפוא מקום לומר ששמואל סבור כרבי! \u0003אלא\u0004 יש לומר כי \u0003שמואל כ\u0004שיטת \u0003ר' שמעון סבירא ליה\u0004 \u0005[סבור הוא],\u0006 שכך \u0003אמר\u0004 ר' שמעון: יש \u0003חמש חטאות\u0004 שנקבע בדינן שהן \u0003מתות,\u0004 ובכלל החמש הללו חטאת שאבדה ונמצאה לפני שהוקרבה השניה, שהאחת קריבה והשניה מתה, וכן המפריש שתי חטאות לאחריות.","ומקשים גם על תירוץ זה: \u0003והא\u0004 \u0005[והרי]\u0006 אי אפשר להעמיד את דברי שמואל כשיטת ר' שמעון, שכן דין חטאת ה\u0003רועה לר' שמעון לית ליה\u0004 \u0005[אין לו]\u0006 \u0003כלל,\u0004 ואילו שמואל אמר כי כל שבחטאת רועה — בתודה חייבת בלחם?","ומשיבים: \u0003שמואל נמי חדא קאמר\u0004 \u0005[גם כן\u0006 רק אימרה \u0005אחת אמר]\u0006 ולא שתים, שכך אמר: \u0003כל שבחטאת מתה\u0004 — \u0003בתודה אין טעונה לחם\u0004 ואת האימרה הבאה \"כל שבחטאת רועה — בתודה טעונה לחם\" לא אמר שמואל. ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה הוא,\u0006 שמואל, \u0005השמיע לנו]\u0006 בכך? ומסבירים: \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003מ\u0004דברי \u0003ר' יוחנן,\u0004 ש\u0003אמר\u0004 כי \u0003אדם מתכפר\u0004 אף \u0003בשבח הקדש,\u0004 ולכך לשיטת ר' יוחנן ולד תודת חובה הקרב לפני שקרבה אמו הריהו טעון לחם, \u0003קמשמע לן\u0004 \u0005[הוא\u0006, שמואל, \u0005משמיע לנו]\u0006 ש\u0003לא\u0004 כך הוא הדין, שאין אדם מתכפר בשבח הקדש, ולכך ולד תודה אינו טעון לחם, ובדומה לולד חטאת שדינו למיתה.","ועוד בדין לחמי התודה \u0003אמר ר' אבא:\u0004 מי שנדב להקדש ואמר \u0003\"זו\u0004 הבהמה הריהי לקרבן \u0003תודה וזו\u0004 הסולת הריהי ל\u0003לחמה\".\u0004 אם \u0003אבד הלחם\u0004 ולא אבדה התודה — הריהו מקריב את התודה הזו ו\u0003מביא\u0004 עימה \u0003לחם אחר.\u0004 ואם \u0003אבדה\u0004 ה\u0003תודה\u0004 ולא אבד הלחם — \u0003אינו מביא תודה אחרת\u0004 שיוקרב עם לחם זה, למרות שיש לו לחם. ומסביר: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005],\u0006 שנשתנה דין הלחם שאבד מדין התודה שאבדה? \u0003לחם\u0004 התודה הריהו בא \u0003לגלל\u0004 (בגלל) ה\u0003תודה,\u0004 ולכך אם אין \u0003קרבן תודה\u0004 — אין מקום להבאת הלחם. \u0003ואין תודה\u0004 באה \u0003לגלל\u0004 (בגלל) \u0003לחם,\u0004 ולכך אם אבד הלחם — הריהו מקריב את התודה, ומביא לחם אחר עימה.","\u0003ו\u0004עוד הלכה דומה, המבדילה בין דין התודה לדין לחמיה, \u0003אמר רבא:\u0004 מי שנדר להביא קרבן תודה, ו\u0003הפריש מעות לתודתו,\u0004"],["וקנה את קרבן תודתו רק בחלק מהמעות שהפריש, \u0003ונתותרו\u0004 בידו מעות. מה יעשה בהן? — הריהו \u0003מביא בהן לחם\u0004 הבא עם קרבן התודה. ואולם אם הפריש מעות \u0003ללחמי תודה,\u0004 ואכן קנה בחלק מהן לצורך לחמי תודה, \u0003ונתותרו\u0004 בידו מעות — \u0003אין מביא בהן תודה.\u0004","ומבררים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005],\u0006 ומדוע המפריש מעות לתודה יכול לקנות בשארית המעות לחמי \u0005תודה, אך המפריש מעות ללחמי תודה אינו יכול לקנות בשארית המעות תודה?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום\u0004 דרשה זו שאמר \u0003רב כהנא,\u0004 שכך \u0003אמר רב כהנא: מנין ללחמי תודה שנקראו\u0004 אף \u0003הם\u0004 \u0003\"תודה\"?\u0004 שכן \u0003נאמר\u0004 בפרשת התודה: \u0003\"והקריב על זבח התודה חלות מצות\"\u0004 (ויקרא ז, יב), שאף החלות נקראות \"תודה\", ולכך המפריש מעות לתודתו קונה בהן אף לחמי התודה. ואולם \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא ההסבר, שנלמד מכתוב זה הכולל את החלות בזבח התודה, הרי יש לומר כי \u0003איפכא\u0004 \u0005[ההיפך],\u0006 שתיקרא גם התודה בשם \"לחם\", \u0003נמי\u0004 \u0005[גם כן],\u0006 יש ללמוד מן הכתוב, ולמה לא יותר לקנות תודה במעות הנותרות מאלה שהופרשו ללחמי תודה! ומשיבים: מן הכתוב אנו למדים כי \u0003לחם\u0004 תודה \u0003איקרי\u0004 \u0005[נקרא]\u0006 אף הוא \u0003\"תודה\",\u0004 ואולם ה\u0003תודה לא איקרי\u0004 \u0005[לא נקראה]\u0006 \u0003לחם.\u0004","\u0003ו\u0004עוד הלכה בדיני התודה \u0003אמר רבא:\u0004 מי ש\u0003הפריש\u0004 בהמה לקרבן \u0003תודתו, ואבדה, וחזר והפריש\u0004 בהמה \u0003אחרת תחתיה, ו\u0004גם היא \u0003אבדה, וחזר והפריש אחרת תחתיה, ו\u0004לאחר מכן \u0003נמצאו\u0004 שתי \u0003הראשונות, והרי\u0004 עתה \u0003שלשתן עומדות\u0004 (מזומנות) להקרבה. מה יעשה? אם עמד והקריב ו\u0003נתכפר\u0004 איפוא \u0003בראשונה\u0004 — ה\u0003שניה אינה טעונה לחם,\u0004 שהרי היא חילופיה של הראשונה, והראשונה קרבה עם לחמה. ואולם ה\u0003שלישית טעונה לחם,\u0004 שהרי היא רק חליפין של השניה, והשניה אינה טעונה לחם.","ואם עמד והקריב ו\u0003נתכפר\u0004 איפוא \u0003בשלישית\u0004 — ה\u0003שניה אינה טעונה לחם,\u0004 שהרי חלופתה (התודה השלישית) כבר קרבה עם לחמה, ואולם ה\u0003ראשונה\u0004 הריהי \u0003טעונה לחם,\u0004 שהרי כאשר תוקרב חלופתה (התודה השניה), היא תוקרב בלא לחם. ואם עמד והקריב והתכפר \u0003באמצעית\u0004 — \u0003שתיהן\u0004 (הן התודה הראשונה והן התודה השלישית) \u0003אין טעונות לחם.\u0004 התודה הראשונה אינה טעונה לחם — שהרי הובא לחם בחלופתה (התודה השניה), וכן התודה השלישית אינה טעונה לחם — שהרי היא חלופתה של זו שהוקרבה עם לחמה. ואילו \u0003אביי אמר: אפילו נתכפר ב\u0004כל \u0003אחת מהן,\u0004 ולאו דווקא בתודה השניה — \u0003שתיהן\u0004 (שתי התודות האחרות) שוב \u0003אין טעונות לחם,\u0004 וטעם הדבר: כי כל השלוש \u0003כולהו\u0004 \u0005[כולן]\u0006 \u0003חליפין דהדדי נינהו\u0004 \u0005[של זו בזו הן].\u0006","ובעקבות דברי רבא בענין שלוש תודות, \u0003אמר ר' זירא: וכן\u0004 הוא הדין \u0003לענין\u0004 המפריש שלוש \u0003חטאות.\u0004 ומפרט את דבריו: שאם עמד ו\u0003הפריש\u0004 בהמה לקרבן \u0003חטאתו, ואבדה,\u0004 ועמד \u0003והפריש\u0004 בהמה \u0003אחרת תחתיה\u0004 לחטאת, \u0003ו\u0004אף זו החטאת השניה \u0003אבדה,\u0004 ועמד \u0003והפריש\u0004 בהמה \u0003אחרת תחתיה\u0004 לחטאת. \u0003ו\u0004לאחר מכן \u0003נמצאו\u0004 שתי \u0003הראשונות\u0004 שאבדו, \u0003והרי\u0004 עתה \u0003שלשתן עומדות\u0004 (מזומנות) לפניו להקרבה כחטאת. אם עמד והקריב ו\u0003נתכפר ב\u0004חטאת ה\u0003ראשונה\u0004 — ה\u0003שניה תמות\u0004 (תובא לכלל מיתה), כדין חטאת שהתכפרו בעליה בזו שבאה להחליפתה. ואילו החטאת ה\u0003שלישית\u0004 לא תמות (שהרי לא קרבה זו שהיא באה להחליפה, היא החטאת השניה), אלא \u0003תרעה\u0004 באחו עד שיפול בה מום ותיפדה.","ואם עמד והקריב ו\u0003נתכפר ב\u0004חטאת ה\u0003שלישית\u0004 — החטאת ה\u0003שניה תמות\u0004 (שהרי זו שהיא חלופתה כבר הוקרבה), \u0003ו\u0004אילו החטאת ה\u0003ראשונה\u0004 לא תמות (שהרי החטאת שבאה להחליפה, היא החטאת השניה, לא הוקרבה), אלא \u0003תרעה\u0004 באחו עד שיפול בה מום ותיפדה. ואולם אם עמד והקריב ו\u0003נתכפר\u0004 בחטאת ה\u0003אמצעית\u0004 — \u0003שתיהן\u0004 (הן החטאת הראשונה והן החטאת השלישית) \u0003ימותו.\u0004 החטאת הראשונה תומת — שהרי כבר הוקרבה חלופתה (החטאת השניה), וכן החטאת השלישית תומת — שהרי היא חלופתה של זו החטאת שהוקרבה. ואף בענין זה חלק \u0003אביי\u0004 ו\u0003אמר:\u0004 לא רק אם התכפר באמצעית, אלא \u0003אפילו נתכפר ב\u0004כל \u0003אחת מהן\u0004 האחרות, בראשונה או בשלישית — \u0003שתיהן ימותו.\u0004 וטעם הדבר: כי כל השלוש \u0003כולהו\u0004 \u0005[כולן]\u0006 \u0003חליפין דהדדי נינהו\u0004 \u0005[של זו בזו הן].\u0006","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 טיבה\u0005]\u0006 של המלה \u0003\"וכן\"\u0004 שאמר ר' זירא בדין שלוש חטאות בעקבות דין שלוש תודות, והרי לכאורה זהו אותו דין עצמו, ומה חידש לנו בדבריו? ומסבירים: חידש ר' זירא שלא רק בשלוש תודות כך הוא הדין, אלא אף בשלוש חטאות. ונצרך להשמיענו כן, שכן יש מקום להבחין בין דין התודות לדין החטאות, ו\u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 דווקא \u0003התם\u0004 \u0005[שם,\u0006 בתודות\u0005]\u0006 \u0003הוא דאיכא למימר\u0004 \u0005[שיש לומר]\u0006 שאם הוקרבה התודה הראשונה, התודה השלישית טעונה לחם, שכן בכך \u0003מרבה בתודות הוא\u0004 (שהרי התודה באה אף בנדבה, ומרבה בנדבותיו הוא בכך). \u0003אבל הכא\u0004 \u0005[כאן,\u0006 בחטאות\u0005],\u0006 \u0003דליכא למימר\u0004 \u0005[שאין לומר]\u0006 \u0003מרבה בחטאות הוא,\u0004 שהרי אין החטאת באה בנדבה אלא בחובה בלבד. \u0003אימא\u0004 \u0005[אמור]\u0006 שאם קרבה הראשונה, \u0003לא\u0004 יהא דינה של השלישית לרעייה, אלא למיתה. לכן \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 ר' זירא, \u0005משמיע לנו],\u0006 שאף בשלוש חטאות, אין השלישית נחשבת כחילופי הראשונה, ותומת, אלא כחילופי השניה, ותרעה.","שנינו במשנתנו כי תמורתה של תודה אינה טעונה לחם. ועוד בענין זה \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא:\u0004 בהמת הקדושה לקרבן \u0003תודה,\u0004 והריהי איפוא חייבת בהבאת לחמי תודה בהקרבתה, \u0003שנתערבה בתמורתה\u0004 (ודינה של תמורת תודה, שאינה חייבת בהבאת לחם בהקרבתה), ואין יודעים עתה מיהי בהמת התודה ומיהי בהמת התמורה. \u0003ומתה אחת מהן,\u0004 ומעתה אין אנו יודעים מה טיבה של \u0003חבירתה\u0004 זו שלפנינו. מה דינה של בהמה זו? — \u0003אין לה תקנה\u0004 (עצה כיצד תוקרב). שכן \u0003היכי נעביד\u0004 \u0005[כיצד נעשה]?\u0006 אם \u0003נקריב לחם בהדה\u0004 \u0005[עימה]\u0006 — \u0003דלמא\u0004 \u0005[שמא]\u0006 בהמת \u0003תמורה היא\u0004 זו, שאינה חייבת בהבאת לחם. ואם \u0003לא נקריב לחם בהדה\u0004 \u0005[עימה]\u0006 — \u0003דלמא\u0004 \u0005[שמא]\u0006 בהמת \u0003תודה היא,\u0004 החייבת בהבאת לחם עימה.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר ש\u0003אמר\u0004 המקדיש את התודה (שהתערבה בתמורתה) בלשון \"הרי \u0003עלי\u0004 קרבן תודה\" (ומעתה, הריהו חייב באחריותה, שאם אבדה בהמה זו, הריהי מביא אחרת תחתיה) — מדוע אין לה תקנה? האם \u0003לא סגיא\u0004 \u0005[אין\u0006 הבעיה נפתרת \u0005דיה]\u0006 ש\u0003לא\u0004 באופן זה: \u0003מייתי ליה\u0004 \u0005[הריהו מביא]\u0006 \u0003בהמה אחרינא\u0004 \u0005[אחרת],\u0006 שהרי קיבל אחריות עליו לקרבן זה, \u0003ולחם\u0004 עימה, \u0003ולימא\u0004 \u0005[ויאמר]\u0006 בדרך תנאי: \u0003אי הך דקיימא\u0004 \u0005[אם\u0006 בהמה \u0005זו שעומדת]\u0006 לפני, לאחר שתערובתה מתה, בהמת ה\u0003תמורה היא,\u0004 ולא בהמת התודה — תקרב \u0003הא\u0004 \u0005[זו]\u0006 הבהמה המובאת עתה לקרבן ה\u0003תודה והא\u0004 \u0005[וזה]\u0006 הוא \u0003לחמה,\u0004 ו\u0003אי הך דקיימא\u0004 \u0005[אם\u0006 בהמה \u0005זו שעומדת]\u0006 לפני בהמת ה\u0003תודה היא\u0004 ולא בהמת התמורה — תקרב \u0003הא\u0004 \u0005[זו]\u0006 הבהמה העומדת לפניו לתודה, והרי זה \u0003לחמה, ו\u0004אילו בהמה \u0003הא\u0004 \u0005[זו]\u0006 שאני מביא עתה \u0003תיהוי\u0004 \u0005[תהיה,\u0006 תשמש\u0005]\u0006 כבאה \u0005ב\u0006\u0003אחריות\u0004 לבהמת התודה, שאם תאבד בהמת התודה — תוקרב זו!","ומשיבים: אכן כשאמר המקדיש \"הרי עלי תודה\", יש תקנה, ו\u0003לא צריכא\u0004 \u0005[\u0006ו\u0005לא נצרכה]\u0006 להיאמר הלכה זו שבברייתא אלא בזמן ש\u0003אמר\u0004 המקדיש \u0003\"הרי זו\u0004 תודה\", שהקדיש רק אותה בהמה מסויימת לקרבן, וללא קבלת אחריות להביא אחרת אם תאבד זו.","על דברי ברייתא זו, שבמקרה שהתערבו התודה ותמורתה ומתה אחת מהן, אין כל תקנה, הקשו חכמים שונים בדרכים שונות. ומביאים \u0003(סימן\u0004 לזכרון שמותיהם של החכמים ששאלותיהם תופענה במהלך הסוגיה הבאה: \u0003למודים\u0004 (=לוי, הוא החכם המכונה \"למדין לפני רבי\"), \u0003מידת\u0004 (=ר' יצחק \u0003בר שמואל בר מרתא).\u0004 \u0003עלה\u0004 (=עולא בר אבא). \u0003שיש\u0004 (=רב שישא בריה דרב אידי). \u0003שכן\u0004 (=רב אש י ורב כהנ א). \u0003דדמה\u0004 (=רב דימי בריה דרב הונא מדמהוריא). \u0003דאי\u0004 (=רבינא דאי קלע). וכן ניתן סימן לזכרון הענינים מהם הקשו: \u0003חלש\u0004 (ח ולין, של מים). \u0003מותר. תמורה. בחוץ. חזקיה. הפריש חטאת. לאחר\u0004 = אחריות).","\u0003אמרו למדין לפני רבי\u0004 (החכם לוי): מדוע אין תקנה במקרה זה, \u0003ו\u0004הרי ניתן לעשות כך: \u0003ליתי\u0004 \u0005[שיביא]\u0006 המקדיש \u0003לחם\u0004 לתודה, \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 בדרך התנאי: \u0003אי הך דקיימא\u0004 \u0005[אם\u0006 בהמה \u0005זו שעומדת]\u0006 לפני, מבין השתים שהתערבו, בהמת ה\u0003תודה היא,\u0004 ובהמת התמורה היא שמתה — \u0003הא\u0004 \u0005[זה]\u0006 יהא \u0003לחמה\u0004 הבא עימה, וייאכל הלחם כלחם תודה. ו\u0003אי\u0004 \u0005[אם]\u0006 בהמה זו היא \u0003לא\u0004 בהמת התודה, אלא בהמת התמורה (שאין לחם בא עימה) — \u0003ליפוק\u0004 \u0005[שיצא]\u0006 לחם זה \u0003לחולין,\u0004 וייאכל כחולין! \u0003אמר להו\u0004 \u0005[להם]\u0006 רבי לשואלים כן בתשובה: והרי \u0005את לחם התודה יש להכניס לעזרה להנפתו,\u0006 \u0003וכי מכניסין\u0004 לכתחילה דבר שעשוי הוא להיות \u0003חולין לעזרה?\u0004","והציעו עוד תקנה לבעיה זו: \u0003וליתי\u0004 \u0005[ושיביא]\u0006 הבעלים \u0003בהמה\u0004 אחרת \u0003ולחם, ולימא\u0004 \u0005[ושיאמר]\u0006 בדרך תנאי זה: \u0003אי הך דקיימא\u0004 \u0005[אם זו שעומדת]\u0006 לפני, מבין השתים שהתערבו, בהמת ה\u0003תמורה היא\u0004 — תהא בהמה \u0003הא\u0004 \u0005[זו]\u0006 המובאת עתה לקרבן \u0003תודה, והא\u0004 \u0005[וזה]\u0006 הוא \u0003לחמה.\u0004 ו\u0003אי הך דקיימא\u0004 \u0005[אם זו שעומדת]\u0006 לפני עתה בהמת ה\u0003תודה היא,\u0004 ולא בהמת התמורה — יהא \u0003הא\u0004 \u0005[זה]\u0006 \u0003לחמה, ו\u0004אילו \u0003הא\u0004 \u0005[זו]\u0006 המובאת עתה, \u0003תיהוי\u0004 \u0005[תהיה]\u0006 לקרבן \u0003שלמים\u0004 (ואין השלמים באים עם לחם)! \u0003אמר להו\u0004 \u0005[להם]\u0006 רבי לשואלים כן: אי אפשר לעשות כך, \u0003משום דקא\u0004 \u0005[ש\u0006בכך \u0005הוא]\u0006 \u0003ממעט ב\u0004זמן ה\u0003אכילה\u0004 של ה\u0003ש\u0004\u0003למים,\u0004 שהרי זמן אכילתם של קרבנות השלמים הריהו שני ימים ולילה אחד, בעוד שזמן אכילתה של התודה אינו אלא יום ולילה. ולאחר מכן, אסורה היא באכילה. ולהצעה זו שהצעתם לא יהיה ניתן לאכול מבשר הבהמה המובאת (שאפשר והיא שלמים) אלא לילה ויום בלבד (מן הספק אולי היא תודה).","ועוד הצעה לפתרון בעיה זו \u0003אמר לוי לרבי: וליתי\u0004 \u0005[ושיביא]\u0006 הבעלים \u0003בהמה\u0004 אחרת \u0003ולחם, ולימא\u0004 \u0005[ושיאמר]\u0006 בדרך תנאי זה: \u0003אי הך דקיימא\u0004 \u0005[אם\u0006 בהמה \u0005זו שעומדת]\u0006 לפני, מבין השתים שהתערבו, בהמת ה\u0003תמורה היא\u0004 — תהא בהמה \u0003הא\u0004 \u0005[זו]\u0006 המובאת עתה לקרבן \u0003תודה, והא\u0004 \u0005[וזה]\u0006 הוא \u0003לחמה. ואי האי דקיימא\u0004 \u0005[ואם זו שעומדת]\u0006 לפני עתה בהמת ה\u0003תודה היא,\u0004 ולא בהמת התמורה — יהא \u0003הא\u0004 \u0005[זה]\u0006 \u0003לחמה, ו\u0004אילו \u0003הא\u0004 \u0005[זו]\u0006 המובאת עתה, \u0003תיהוי\u0004 \u0005[תהיה]\u0006 \u0003מותר\u0004 של \u0003תודה\u0004 (תודה שנותרה, וכגון שאבדה בהמת התודה ועמד והתכפר באחרת, ולאחר מכן נמצאה התודה), שדינה הוא שאינה באה עם לחם! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי ללוי על שאלתו זו: \u0003כמדומה אני שאין לו מוח בקדקדו,\u0004"],["שאין להעלות על הדעת הצעה כזו, \u0003וכי מפרישין\u0004 (מקדישים) לכ \u0003תחלה\u0004 דבר רק \u0003למותרות?!\u0004 ועוד בהצעות שהעלו חכמים למציאת תקנה כשהתערבו בהמת תודה ובהמת תמורת תודה, ומתה אחת מהן.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' יצחק בר שמואל בר מרתא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן, ויתיב וקאמר\u0004 \u0005[וישב ואמר]:\u0006 \u0003ולייתי\u0004 \u0005[ושיביא]\u0006 הבעלים \u0003בהמה\u0004 אחרת \u0003ולחם, ולימא\u0004 \u0005[ושיאמר]:\u0006 \u0003אי הך דקיימא\u0004 \u0005[אם זו שעומדת]\u0006 לפני, מבין השתים שהתערבו, בהמת ה\u0003תמורה היא\u0004 — תהא בהמה \u0003הא\u0004 \u0005[זו]\u0006 המובאת עתה לקרבן \u0003תודה, והא\u0004 \u0005[וזה]\u0006 הוא \u0003לחמה.\u0004 ו\u0003אי הך דקיימא\u0004 \u0005[אם זו שעומדת]\u0006 לפני בהמת ה\u0003תודה היא,\u0004 ולא התמורה — יהא \u0003הא\u0004 \u0005[זה]\u0006 \u0003לחמה, ו\u0004אילו \u0003הא\u0004 \u0005[זו]\u0006 המובאת עתה, \u0003תהוי\u0004 \u0005[תהיה]\u0006 \u0003תמורה\u0004 של קרבן תודה. שהרי תמורת תודה אינה באה עם לחם, וזמן אכילתה הוא לילה ויום (ולכך אין כאן מיעוט זמן אכילתה)!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לר' יצחק בר שמואל בר מרתא בדחייה: \u0003עני מרי\u0004 \u0005[ענה אדוני],\u0006 והרי כל העושה תמורה, הריהו לוקה \u0003ארבעין בכתפיה\u0004 \u0005[ארבעים\u0006 מלקות \u0005בכתיפו],\u0006 ככל העוברים על איסור לאו שבתורה, \u0003וכשר\u0004 (ראוי) לעשותו?!","ועוד מסופר כי \u0003רב עילא חלש\u0004 \u0005[חלה],\u0006 \u0003על לגביה\u0004 \u0005[נכנס אצלו]\u0006 לבקרו \u0003אביי ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003ויתבי וקא אמרי\u0004 \u0005[וישבו ואמרו]\u0006 הצעה לפתרונה של \u0005בעיה זו, כי\u0006 \u0003אם איתא\u0004 \u0005[יש,\u0006 מקובלת\u0005]\u0006 \u0003ל\u0004דעתו של \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 שאם היה לחם התודה בעיר ירושלים (שהיא מקום אכילתו), אף שהיה מ\u0003חוץ לחומת העזרה\u0004 בשעה שנשחטה התודה, הריהו \u0003קדוש\u0004 בכך, מעתה אם כן יש פתרון לבעיה זו שבברייתא: \u0003לייתי\u0004 \u0005[שיביא]\u0006 \u0003לחם ולותבה\u0004 \u0005[ושיניח אותו]\u0006 מ\u0003חוץ לחומת העזרה\u0004 (ונמצא שאין בכך הכנסת חולין לעזרה), \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 לפיכך: \u0003אי הך דקיימא\u0004 \u0005[אם\u0006 בהמה \u0005זו שעומדת]\u0006 עתה לפני, מבין השתים שהתערבו, בהמת ה\u0003תודה היא\u0004 — הרי \u0003הא\u0004 \u0005[זה]\u0006 הוא \u0003לחמה. ואי\u0004 \u0005[ואם]\u0006 בהמה זו העומדת עתה לפני \u0003לא\u0004 בהמת התודה היא אלא התמורה — \u0003ליפוק\u0004 \u0005[שיצא]\u0006 הלחם \u0003לחולין.\u0004","ומשיבים: אין בהצעה זו פתרון לבעיה, \u0003משום דאיכא\u0004 \u0005[שישנם]\u0006 \u0003ארבע\u0004 לחמי תודה מארבעים הלחמים שאותם מצוה \u0003להניף,\u0004 וכשהלחמים נמצאים מחוץ לעזרה, \u0003היכי ליעביד\u0004 \u0005[כיצד יעשה]\u0006 הנפה זו? אם \u0003לנפינהו אבראי\u0004 \u0005[יניף אותם מחוץ\u0006 לעזרה\u0005]\u0006 — והרי בהנפת שלמים (וכן הוא בתודה, שאף בכלל שלמים) \"להניף אותו תנופה \u0003לפני ה' \"\u0004(ויקרא ז, ל) \u0003כתיב\u0004 \u0005[נאמר],\u0006 ואין הנפה הנעשית מחוץ לחומת העזרה נחשבת בכלל \"לפני ה' \". ואם יכניס את ארבעת הלחמים הללו \u0003גוואי\u0004 \u0005[בפנים]\u0006 העזרה, ויניפם שם — הרי \u0003קא מעייל\u0004 \u0005[הוא מכניס]\u0006 \u0003חולין לעזרה! הלכך\u0004 (משום כך) \u0003לא אפשר\u0004 לעשות כהצעה זו.","ועוד בענין קביעתה של הברייתא כי כשהתערבו תודה ותמורת תודה ומתה אחת מהן אין להן תקנה, \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי,\u0004 \u0003אם איתא\u0004 \u0005[יש,\u0006 מקובלת\u0005]\u0006 \u0003ל\u0004דעתו של \u0003חזקיה\u0004 ש\u0003אמר\u0004 בדינה של התודה שנשחטה על שמונים לחמים (ולא על ארבעים, כדין) כי \u0003קדשו ארבעים\u0004 לחמים \u0003מתוך\u0004 ה\u0003שמונים\u0004 שהביא, הרי יש לדבר \u0003פתרון, ש\u0004\u0003לייתי\u0004 \u0005[שיביא]\u0006 הבעלים \u0003בהמה\u0004 אחרת \u0003ולייתי\u0004 \u0005[ושיביא]\u0006 \u0003שמונים\u0004 חלות \u0003בהדה\u0004 \u0005[עימה],\u0006 \u0003ולימא\u0004 \u0005[ושיאמר]:\u0006 \u0003אי הך דקיימא\u0004 \u0005[אם\u0006 בהמה \u0005זו שעומדת]\u0006 עתה לפני, בהמת ה\u0003תודה היא\u0004 — הרי \u0003הא נמי תיהוי\u0004 \u0005[זו\u0006 הבהמה המובאת עתה \u0005גם כן תהיה]\u0006 \u0003תודה, והא\u0004 \u0005[ואלה]\u0006 ה\u0003שמונים\u0004 לחמים המובאים הריהם \u0003דתרוייהו\u0004 \u0005[של שתיהן],\u0006 של שתי התודות. ו\u0003אי הך דקיימא\u0004 \u0005[אם זו שעומדת]\u0006 עתה לפני בהמת ה\u0003תמורה היא\u0004 — \u0003הא\u0004 \u0005[זו]\u0006 המובאת עתה \u0005הריהי ל\u0006\u0003תודה, והא\u0004 \u0005[וזה]\u0006 \u0003לחמה, וליקדשו להו\u0004 \u0005[ושיתקדשו להם],\u0006 כשיטת חזקיה, \u0003ארבעים\u0004 לחמים \u0003מתוך\u0004 ה\u0003שמונים!\u0004","ודוחים: אין זה פתרון, שאין לעשות כן \u0003משום דקא\u0004 \u0005[ש\u0006בכך \u0005הוא]\u0006 \u0003ממעט ב\u0004אפשרות ה\u0003אכילה\u0004 של לחמי התודה. שכן \u0005מתוך\u0006 \u0003ארבעים\u0004 הלחמים ניתנים ארבעה לחמים כתרומה לכהנים. ומעתה, שהריהו מביא, כהצעה זו, שמונה לחמים (ארבעה לחמים כודאי, וארבעה מן הספק), וכיון שאין כולן נאכלות, נמצא שמתמעט מספר החלות הנאכלות.","ועוד הצעה הקודמת לפתרון הבעיה המובאת בברייתא, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא:\u0004 \u0003אם איתא\u0004 \u0005[יש,\u0006 מקובלת\u0005]\u0006 \u0003ל\u0004דעתו של \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 בדין החטאת, שאם \u0003הפריש\u0004 בהמה לקרבן \u0003חטאת\u0004 והיתה בהמה זו \u0003מעוברת, וילדה.\u0004 אם \u0003רצה\u0004 — מביא את האם לקרבן, ו\u0003בה\u0004 הוא \u0003מתכפר,\u0004 ואם \u0003רצה\u0004 — הריהו מביא את \u0005הוולד, ואותו הוא מקריב, ו\u0006\u0003בוולדה\u0004 הוא \u0003מתכפר,\u0004 הרי שלדעת ר' יוחנן הולד הוא ברשותו של המקדיש, ויכול הוא לקובעו לקרבן כרצונו. ומעתה אף במקרה זה שלפנינו, \u0003לייתי\u0004 \u0005[שיביא]\u0006 לקרבן תודתו \u0003בהמה מעוברת, ו\u0004לא יקריבנה מיד אלא \u0003ימתין לה עד שתלד, ולייתי\u0004 \u0005[ושיביא]\u0006 \u0003שמונים\u0004 חלות \u0003בהדה\u0004 \u0005[עימה],\u0006 \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 בדרך \u0005תנאי:\u0006 \u0003אי הך דקיימא\u0004 \u0005[אם\u0006 בהמה \u0005זו שעומדת]\u0006 עתה לפני \u0005בהמת ה\u0006\u0003תמורה היא\u0004 ולא בהמת התודה — \u0003הא\u0004 \u0005[זו]\u0006 הבהמה \u0003ו\u0004כן \u0003וולדה תודה היא, והא\u0004 \u0005[ו\u0006הרי \u0005אלה]\u0006 ה\u0003שמונים\u0004 הינם \u0003דתרווייהו\u0004 \u0005[של שתיהן].\u0006 \u0003ואי הך דקיימא\u0004 \u0005[ואם\u0006 בהמה \u0005זו שעומדת]\u0006 לפני, בהמת \u0005ה\u0006\u0003תודה היא\u0004 ולא בהמת התמורה — \u0003הא נמי\u0004 \u0005[\u0006בהמת האם \u0005הזו גם כן]\u0006 \u0003תודה היא, והא\u0004 \u0005[ואלה]\u0006 ה\u0003שמונים דתרווייהו\u0004 \u0005[של שתיהן]\u0006 \u0003הוא, ו\u0004אילו \u0003האי\u0004 \u0005[זה,\u0006 הולד\u0005]\u0006 \u0003ליהוי\u0004 \u0005[יהיה]\u0006 \u0003מותר\u0004 של ה\u0003תודה,\u0004 שאינו בא עם לחם!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא לרב אשי בדחיית דבריו: \u0003מאן לימא לן\u0004 \u0005[מי יאמר לנו,\u0006 מנין לנו\u0005]\u0006 שאכן \u0003אמר ר' יוחנן\u0004 כי הולד הוא ברשותו של המקדיש את האם המעוברת, ולכך \u0003אם\u0004 הוא \u0003שיירו\u0004 (קובעו להקדש מסויים) הריהו \u0003משוייר\u0004 (נקבע לאותו הקדש)? \u0003דלמא\u0004 \u0005[שמא]\u0006 סבור ר' יוחנן כי אין הולד ברשותו של המקדיש \u0005לקובעו שירצה, ו\u0006\u0003אם שיירו\u0004 — \u0003אינו משוייר, ו\u0004אולם \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' יוחנן\u0004 שאמר שאפשר לו להתכפר אף בולד הנולד לחטאת המעוברת, משום ש\u0003אמר\u0004 ר' יוחנן כי \u0003אדם מתכפר\u0004 אף \u0003בשבח הקדש,\u0004 כגון הולד הנולד לבהמת הקדש מעוברת.","ועוד בענין בעיה זו שבברייתא ובדרכים למצוא לה פתרון, מסופר כי \u0003רבינא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004מקום הנקרא \u0003דמהוריא, אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב דימי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא מדמהוריא לרבינא:\u0004 יש פתרון לבעיה זו, \u0003ו\u0004באופן זה: \u0003לייתי\u0004 \u0005[שיביא]\u0006 הבעלים \u0003בהמה\u0004 נוספת, \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 בלשון נדר שיש בו אחריות: \u0003\"הרי עלי\u0004 להביא תודה\", ויפריש בהמה זו לנדרו. \u0003ו\u0004לאחר מכן \u0003לייתי\u0004 \u0005[שיביא]\u0006 \u0003בהמה אחריתי\u0004 \u0005[אחרת],\u0006 שלישית, \u0003ולייתי\u0004 \u0005[ושיביא]\u0006 \u0003שמונים\u0004 חלות \u0003בהדה\u0004 \u0005[עימה],\u0006 \u0003ולימא\u0004 \u0005[ושיאמר]:\u0006 \u0003אי הך דקיימא\u0004 \u0005[אם\u0006 בהמה \u0005זו שעומדת]\u0006 לפני, בהמת \u0005ה\u0006\u0003תמורה היא,\u0004 ולא בהמת התודה — \u0003הני תרתי\u0004 \u0005[אלה שתיהן]\u0006 הריהן \u0003תודות\u0004 (אחת — הבאה בנדרו, והאחרת — כנדבה), \u0003והא\u0004 \u0005[ואלה]\u0006 ה\u0003שמונים\u0004 חלות הריהן \u0003דתרוייהו\u0004 \u0005[של שתיהן],\u0006 \u0003ואי הך דקיימא\u0004 \u0005[ואם\u0006 בהמה \u0005זו שעומדת]\u0006 לפני, בהמת ה\u0003תודה היא,\u0004 ולא בהמת התמורה. \u0003ו\u0004כן \u0003הא\u0004 \u0005[זו]\u0006 הבהמה \u0003דאמרי\u0004 \u0005[שאמרתי]\u0006 עליה \"הרי \u0003עלי\u0004 תודה\" והפרשתיה לצורך זה, \u0003נמי ליהוי\u0004 \u0005[גם שתהיה]\u0006 \u0003תודה, והא\u0004 \u0005[ואלה]\u0006 ה\u0003שמונים\u0004 חלות הן \u0003דתרוייהו\u0004 \u0005[של שתיהן],\u0006 \u0003ואידך תהוי\u0004 \u0005[ו\u0006הבהמה \u0005האחרת,\u0006 השלישית, \u0005תהיה,\u0006 תשמש\u0005]\u0006 \u0003לאחריות\u0004 שאם תאבד תודתי, היא תקרב. ודינה שהיא קרבה בלא לחם!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא לרב דימי בנו של רב \u0005הונא מדמהוריא בדחיית דבריו: אין זו הצעה ראויה, שכן\u0006 \u0003התורה אמרה: \"טוב אשר לא תדר משתדור ולא תשלם\"\u0004 (קהלת ה, ד), שאין ראוי לנדור מפני החשש שמא ייכשל ולא ישלם נדרו, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 כהצעה לפתרון הבעיה \u0005הזו\u0006 \u0003ליקום ולינדור\u0004 \u0005[שיקום וינדור]\u0006 \u0003בתחילה\u0004 (לכתחילה)?! ונשארו דברי הברייתא, כי אכן במקרה זה של בהמת תודה ובהמת תמורה שהתערבו ומתה אחת מהן, אין תקנה לבהמה שנותרה.","\u0003האומר \"הרי עלי תודה\"\u0004 — \u0003יביא היא\u0004 (התודה עצמה) \u0003ו\u0004את \u0003לחמה מן\u0004 מעות \u0003החולין\u0004 שבידו, ולא ממעות מעשר שני שבידו. שכן כיון שאמר \"הרי עלי\" — נתחייב בדבר, וכל דבר שאדם נתחייב בו, אין יוצא ידי חובתו זו במעות מעשר שני, אלא במעות חולין."],["אם אמר \"הרי \u0003תו\u0004 \u0003דה עלי\u0004 להביאה \u0003מן\u0004 מעות \u0003החולין ו\u0004את \u0003לחמה\u0004 אני מביא \u0003מן\u0004 מעות \u0003המעשר\u0004 (השני)\" — \u0003יביא היא\u0004 (התודה) ממעות החולין, \u0003ו\u0004אף את \u0003לחמה\u0004 הריהו מביא \u0003מן\u0004 מעות \u0003החולין,\u0004 ולא ממעות מעשר שני, שכן חיוב הלחם תלוי בחיוב התודה ונגרר אחריו. וכיון שנדר להביא תודה מן החולין, נתחייב בהבאת לחם. ומה שהוסיף ואמר שיביא לחם זה ממעות מעשר — אין בכך כלום. ואולם אם אמר \"הרי עלי להביא \u0003תודה מן המעשר\u0004 השני, \u0003ו\u0004את \u0003לחמה\u0004 אביא \u0003מן\u0004 מעות \u0003החולין\"\u0004 — אם רצה יכול הוא ש\u0003יביא\u0004 את תודתו ממעות מעשר שני ואת הלחם ממעות החולין, וכפי שנדר. וכן אם אמר \"הרי עלי להביא \u0003היא\u0004 התודה) \u0003ו\u0004את \u0003לחמה מן\u0004 מעות \u0003המעשר\u0004 השני\" — אם רצה, יכול ש\u0003יביא\u0004 את שניהם ממעות מעשר שני. \u0003ו\u0004מסבירים: זה שאמרנו שהריהו מביא את לחם התודה ממעשר שני כוונת הדברים היא \u0003לא\u0004 ש\u0003יביא\u0004 את הלחם \u0003מחיטי מעשר שני, אלא\u0004 שיקנה סולת \u0003ממעות מעשר שני\u0004 שבידו, וממנה ייעשה הלחם.","שנינו במשנתנו אופנים שונים של הנודר לתודה וללחמה, ועוד הוסיף בענין זה ו\u0003אמר רב הונא:\u0004 אדם \u0003ה\u0004נודר ו\u0003אומר \"הרי עלי לחמי תודה\",\u0004 אף שלא הזכיר שהריהו מתחייב להביא תודה עצמה — \u0003מביא\u0004 בנדרו \u0003זה\u0004 \u0003תודה ולחמה.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005],\u0006 והרי לא הזכיר בנדרו אלא לחמי תודה? \u0003מידע ידע האי גברא\u0004 \u0005[יודע אדם זה\u0006 הנודר כך\u0005]\u0006 כי \u0003לחם\u0004 תודה \u0003בלא\u0004 קרבן \u0003תודה לא איקריב\u0004 \u0005[קרב],\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 שאמר בנדרו \u0005\"לחמי תודה\"\u0006 — קרבן \u0003תודה ולחמה קאמר\u0004 \u0005[הוא\u0006 בעצם \u0005אמר],\u0006 שלכך התכוון, \u0003והאי דקאמר\u0004 \u0005[וזה שהוא אמר]\u0006 בלשון נדרו \"הרי עלי \u0003לחמי תודה\"\u0004 ולא הזכיר את התודה עצמה — את \u0003סוף מילתא נקט\u0004 \u0005[הדבר תפס],\u0006 שהשלמת הבאת התודה היא בלחמיה, אבל באמת התכוון ללחמי התודה ולתודה עצמה.","ומקשים על דברי רב הונא ממה ש\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 בדינו של הנודר ואומר \"הרי \u0005עלי להביא\u0006 \u0003תודה מן\u0004 מעות \u0003המעשר ולחמה מן\u0004 מעות \u0003החולין\"\u0004 — אם ירצה, \u0003יביא כמה שנדר.\u0004 \u0003ו\u0004לשיטת רב הונא שכל האומר \"לחמי תודה\" כוונתו אף לתודה עצמה, יש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 באופן זה הריהו יכול להביא את התודה ממעות מעשר שני, והרי \u0003כיון\u0004 ש\u0003אמר \"לחמה מן החולין\",\u0004 התכוון אף לתודה עצמה, ולכך צריך הוא ש\u0003יביא היא ולחמה מן החולין!\u0004","ומשיבים: אין זו קושיה על רב הונא, שכן \u0003שאני התם\u0004 \u0005[שונה\u0006 הדין \u0005שם\u0006 במקרה שבמשנתנו\u0005],\u0006 ש\u0003כיון\u0004 ש\u0003אמר\u0004 הנודר בתחילה \"הרי עלי \u0003תודה מן המעשר\"\u0004 והוסיף ואמר כי \"לחמה מן החולין\" הריהו \u0003נעשה כ\u0004מי ש\u0003אומר \"הרי עלי לחם לפטור\u0004 בו את \u0003תודתו של פלוני\u0004 החייבת \u0003בלחם\".\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא הסבר משנתנו, \u0003רישא דקתני\u0004 \u0005[תחילת\u0006 המשנה, \u0005ששנה\u0006 בה התנא\u0005]:\u0006 אם אמר \"הרי עלי \u0003תודה מן החולין ולחמה מן המעשר\"\u0004 — \u0003יביא היא\u0004 (התודה עצמה) \u0003ו\u0004אף את \u0003לחמה מן החולין\u0004 (שכיון שהתחייב באמירתו \"הרי עלי תודה\" הביאה מן החולין, אף נתחייב בהבאת לחמיה מן החולין, ואין משמעות לדבריו \"ולחמה מן המעשר\"), \u0003הכא נמי\u0004 \u0005[כאן,\u0006 במקרה זה, \u0005גם כן]\u0006 מדוע לא נאמר \u0005כי כשאמר \"הרי עלי תודה\" הריהו\u0006 \u0003נעשה כ\u0004מי \u0003ש\u0004\u0003אומר \"הרי עלי תודה לפטור לחמו של פלוני\",\u0004 ואת תודתו זו יביא מן המעשר!","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]\u0006 בין שני המקרים הללו, שכן \u0003בשלמא\u0004 \u0005[נניח]\u0006 האומר \"תודה מן המעשר ולחמה מן החולין\" ניתן לומר שהריהי כאומר שהלחם יבוא להשלמת נדרו של החייב בתודה, שכן ה\u0003לחם למיפטר\u0004 \u0005[לפטור]\u0006 את ה\u0003תודה אתי\u0004 \u0005[בא].\u0006 אבל באומר \"תודה מן החולין ולחמה מן המעשר\" אין לומר שנעשה כאומר שתהא התודה באה לפטור חובתו של החייב בתודה, שכן \u0003תודה למיפטר\u0004 \u0005[לפטור]\u0006 את ה\u0003לחם מי אתיא\u0004 \u0005[האם היא באה]?\u0006 ודנים עוד בשיטת רב הונא שכל האומר \"הרי עלי לחמי תודה\" הרי זה מביא תודה ולחמה.","\u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה מן הברייתא, שלא כשיטת רב הונא, שכן שנינו בה: \u0003האומר\u0004 בנדרו \u0003\"הרי עלי\u0004 להביא \u0003תודה בלא לחם\" ו\u0004כן זה האומר \"הרי עלי להביא \u0003זבח בלא נסכים\"\u0004 — \u0003כופין אותו, ומביא תודה ולחמה, זבח ונסכים.\u0004","ויש לדקדק בדברי הברייתא: כל עיקר \u0003טעמא\u0004 \u0005[הטעם]\u0006 שהריהו מביא (בעל כורחו) את התודה ואת לחמיה הריהי משום ש\u0003אמר\u0004 \u0003שהריהו מתחייב בתודה,\u0004 \u0003אבל\u0004 אם \u0003לא אמר\u0004 שהוא מתחייב ב\u0003תודה\u0004 אלא בלחמי תודה — \u0003לא\u0004 היה חייב בהבאת תודה עם הלחמים. ושלא כשיטת רב הונא!","ודוחים את הראיה: אין לדקדק כן מדברי הברייתא, משום שכך \u0003הוא הדין\u0004 (שהריהו מביא תודה ולחמיה) \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא אמר\u0004 בנדרו \u0003\"הרי עלי\u0004 \u0003תו\u0004 \u0003דה\",\u0004 אלא \"הרי עלי לחמי תודה\", וכשיטת רב הונא. \u0003ו\u0004טעם הדבר שהזכיר התנא בברייתא דווקא אופן זה של \"הרי עלי תודה בלא לחם\", \u0003איידי דקא בעי למיתנא\u0004 \u0005[מתוך שהוא רוצה לשנות]\u0006 לאחר מכן בברייתא את המקרה באדם האומר \"הרי עלי \u0003זבח בלא נסכים\",\u0004 ובדינם של הזבח והנסכים \u0003לא\u0004 יכול התנא \u0003מתני ליה\u0004 \u0005[לשנות לו]\u0006 באופן של האומר \"הרי עלי \u0003נסכים בלא זבח\"\u0004 (שכן הנסכים — שלא כלחמי תודה — באים אף לעצמם, ויכול אדם לנדור נסכים לעצמם), לכך \u0003תנא נמי\u0004 \u0005[שנה גם כן]\u0006 בתחילת הברייתא באומר \"הרי עלי \u0003תודה\".\u0004","ושואלים על מה ששנינו בברייתא שאף שנדר ואמר \"הרי עלי תודה בלא לחמים\" או \"הרי עלי זבח בלא נסכים\" כופים אותו להביא תודה ולחמיה, זבח ונסכיו: ו\u0003אמאי\u0004 \u0005[מדוע]\u0006 כך נוהגים בו, והרי זה \u0003נדר ופתחו\u0004 (התרתו) \u0003עמו הוא.\u0004 שיכול הוא לומר שכך היה סבור כשנדר, ועתה שנתברר לו שאין התודה קרבה בלא לחם — שוב אין רצונו בכך, והותר בכך הנדר!","\u0003אמר חזקיה\u0004 בתשובה לשאלה זו: \u0003הא\u0004 \u0005[זו]\u0006 הברייתא כשיטת \u0003מני\u0004 \u0005[מי היא]?\u0006 כשיטת \u0003בית שמאי היא, דאמרי\u0004 \u0005[ש\u0006כן \u0005אומרים]\u0006 בית שמאי באדם האומר שתי לשונות הסותרות זו את זו (כגון במקרה שאמר \"הרי עלי תודה\" — והתחייב בתודה ובלחמיה, וחזר ואמר \"בלא לחמה\") יש ל\u0003תפוס\u0004 (לקבוע דין) על פי ה\u0003לשון הראשון\u0004 שאמר האדם. ולכך בענייננו, כיון שאמר \"הרי עלי תודה\" כבר התחייב אף בהבאת לחמיה. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 האומר \u0003\"הריני נזיר מן הגרוגרות\u0004 (תאנים מיובשות) \u0003ומן הדבלה\u0004 (גוש של תאנים מיובשות)\", והרי משמע הלשון \"הריני נזיר\" שאסור באיסורי הנזיר, ובכללם כל היוצא מן הגפן. אבל אין הנזיר אסור באכילת תאנים. ואילו המשך דבריו (\"לשון אחרון\") לא הזכיר אלא פרישות מאכילת תאנים, שאין בכך דין נזירות. ונחלקו בכך חכמים, ש\u0003בית שמאי אומרים:\u0004 הריהו \u0003נזיר\u0004 גמור, שכן אוחזים אנו את ראשית דבריו שאמר \"הריני נזיר\", ומה שהוסיף ואמר \"מן הגרוגרות\" — אין בדבריו כלום. \u0003ו\u0004אילו \u0003בית הלל אומרים\u0004 כי \u0003אינו נזיר\u0004 כלל, שהרי לא קיבל עליו נזירות.","\u0003ר' יוחנן אמר\u0004 כי אפשר להסביר מדוע אין נחשב \"הרי עלי תודה בלא לחם\" כנדר שפתחו עמו, \u0003אפילו\u0004 אם \u0003תימא\u0004 \u0005[תאמר]\u0006 שהברייתא היא כשיטת \u0003בית הלל,\u0004 שכן מדובר \u0003ב\u0004ברייתא שהנודר \u0003אומר \"אילו הייתי יודע שאין נודרין כך\u0004 (\"הרי עלי תודה בלא לחם\" או \"הרי עלי זבח בלא נסכים\"), \u0003לא הייתי נודר כך, אלא\u0004 הייתי נודר \u0003כך\u0004 (בנוסח הנדר הראוי \"הרי עלי תודה ולחמיה\" או \"הרי עלי זבח ונסכיו\"). \u0003ומאי\u0004 \u0005[ומה\u0006 טעם\u0005]\u0006 נאמר בברייתא שבית דין \u0003\"כופין\u0004 אותו ומביא תודה ולחמה, זבח ונסכיו\"? שהרי הסביר את דבריו ואמר שאילו היה יודע שאין נודרים כך, היה נודר בדרך הראויה! שכן מדובר \u0003דקא בעי הדר ביה\u0004 \u0005[ש\u0006עתה \u0005הוא רוצה לחזור בו]\u0006 מנדרו, ולא להביא תודה ולחמיה.","ולאחר שהובאו הסבריהם של חזקיה ור' יוחנן בברייתא הקודמת, מציעים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ברייתא נוספת, ממנה ראיה לשיטת \u0005חזקיה:\u0006 \u0003ה\u0004נודר ו\u0003אומר \"הרי עלי תודה בלא לחם\", ו\u0004כן הנודר \"הרי \u0003עלי\u0004 \u0003זבח בלא נסכים\", ואמרו לו\u0004 חכמים לנודר התודה בלא לחם \u0003\"הבא תודה ולחמה\", ו\u0004כן אמרו חכמים לנודר הזבח בלא נסכים \"הבא \u0003זבח ונסכים\".\u0004 \u0003ואומר \"אילו הייתי יודע שכן\u0004 הוא הדין — \u0003לא הייתי נודר\u0004 כלל\". \u0003כופין אותו\u0004 בית דין, \u0003ואומר לו\u0004 בלשון מקרא \u0003\"שמר ושמעת\"\u0004 (\"...רק קדשיך אשר יהיו לך ונדריך תשא... שמור ושמעת את כל הדברים האלה אשר אנכי מצוך למען ייטב לך ולבניך אחריך עד עולם כי תעשה הטוב והישר בעיני ה' אלקיך\". דברים יב, כו— כח).","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004הסברו של \u0003חזקיה\u0004 כי הברייתא הקודמת היא כשיטת בית שמאי האומרים שיש לתפוס לשון ראשון, \u0003ניחא ליה\u0004 \u0005[נוח לו]\u0006 ברייתא זו, שאף היא כשיטת בית שמאי, ולכך כופים אותו להביא תודה ולחמיה וזבח ונסכיו. \u0003אלא ל\u0004הסברו של \u0003ר' יוחנן\u0004 שמדובר שאמר הנודר שאילו היה יודע שאין נודרים באופן שנדר, כי אז היה נודר באופן המתוקן, \u0003קשיא\u0004 \u0005[קשה]\u0006 היא ברייתא זו, שהרי כאן אומר בה \u0005הנודר שאילו היה יודע שכך הוא הדין, לא היה נודר כלל\u0006\u0005!\u0006 ומשיבים: \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך ר' יוחנן:\u0004 אכן \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 היא \u0005ב\u0006\u0003ודאי\u0004 כשיטת \u0003בית שמאי היא,\u0004 ואולם הברייתא הקודמת יכולה להיות מוסברת אף לשיטת בית הלל.","ובפירושה של ברייתא זו, מבררים : \u0003מאי\u0004 \u0005[מה\u0006 עניין אמירת הכתוב\u0005]\u0006 \u0003\"שמר ושמעת\"\u0004 לזה שנדר להביא תודה בלא לחם? \u0003אמר אביי,\u0004 שכך צריך להבין: \u0003\"שמר\"\u0004 — \u0003הבא תודה, \"ושמעת\"\u0004 — \u0003הבא לחמה.\u0004 ואילו \u0003רבא אמר: \"שמר\"\u0004 — \u0003הבא תודה ולחמה, \"ושמעת\"\u0004 — \u0003שלא תהא רגיל לעשות כן.\u0004","שנינו במשנתנו כי הנודר ואומר \"הרי עלי \u0003היא ולחמה מן המעשר\"\u0004 — הרי זה \u0003יביא\u0004 מן המעשר. ושואלים: לשון זו, \u0003\"יביא\u0004 מן המעשר\" יש בה להורות שחייב להביא דווקא ממעות מעשר שני, ואולם האם \u0003לא סגי\u0004 \u0005[לא די]\u0006 לקיום נדרו באופן ש\u0003לא מייתי\u0004 \u0005[מביא]\u0006 מן המעשר אלא מן החולין? והרי עדיף שיביא מן החולין, ולא מן המעשר! \u0003רב נחמן ורב חסדא אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: אין כוונת המשנה שחייב הוא להביא דווקא מן המעשר, אלא שיכול הוא להביא אף מן המעשר, ותלוי הדבר ברצונו, שאם \u0003רצה\u0004 — הריהו \u0003מביא\u0004 מן המעשר, ואם \u0003לא רצה\u0004 להביא מן המעשר — \u0003לא יביא.\u0004","\u0003ו\u0004עוד שנינו במשנתנו דברי הסבר, שכוונת הדברים היא \u0003לא\u0004 ש\u0003יביא\u0004 את הלחם \u0003מחיטי מעשר שני, אלא\u0004 שיקנה סולת \u0003ממעות מעשר שני\u0004 שבידו, וממנה ייעשה הלחם. ובענין זה מביאים מה ש\u0003רב נחמן ורב חסדא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 מה שנאמר במשנתנו שאין להביא את לחם התודה מחיטי מעשר שני, \u0003לא שנו אלא מחיטי מעשר שני\u0004 (שהחיטים עצמן מעשר שני), \u0003אבל מחיטין הלקוחות\u0004 שנקנו \u0003ממעות\u0004 פדיון \u0003מעשר שני\u0004 — יכול הוא ש\u0003יביא.\u0004","ונמסר כי \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' ירמיה קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' זירא, ויתיב וקאמר\u0004 \u0005[וישב ואמר],\u0006 כדברי רב נחמן ורב חסדא אלה, כי \u0003לא שנו\u0004 במשנתנו שאין להביא לחם תודה \u0003אלא מחיטי מעשר שני, אבל מחיטין הלקוחות במעות מעשר שני\u0004 — יכול הוא ש\u0003יביא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי, אתה אומר כן.\u0004 אך \u0003אני אומר\u0004 כי \u0003אפילו מחיטין הלקוחות במעות מעשר שני\u0004 גם כן \u0003לא יביא\u0004 את לחם התודה. \u0003ו\u0004הוסיף ואמר: \u0003אימא טעמא דידי\u0004 \u0005[אומר\u0006 מה \u0005הטעם שלי]\u0006 מדוע אין להביא את לחם התודה מחיטים שנקנו במעות מעשר שני, \u0003ואימא טעמא דידך\u0004 \u0005[אומר\u0006 לך מה \u0005הטעם שלי]\u0006 שיכול \u0005להביא את לחם התודה ממעות מעשר שני. ומפרט: בתחילה\u0006\u0005.\u0006 \u0003ואימא טעמא דידך\u0004 \u0005[אומר\u0006 את \u0005הטעם שלך]:\u0006 הרי כל עיקרה של \u0005ה\u0006\u0003תודה\u0004 שהיא באה אף ממעות מעשר, \u0003מהיכא קא ילפת לה\u0004 \u0005[מהיכן אתה לומד אותה]?\u0006 \u0003מ\u0004תוך ההקש של התודה ל\u0003שלמים\u0004 (כנאמר בתחילת פרשת התודה \"וזאת תורת השלמים אשר יקריב לה'. אם על תודה יקריבנו...\" ויקרא ז, יא— יב)."],["\u0003ו\u0004אילו דין ה\u0003שלמים\u0004 שהם באים אף ממעות מעשר, אתה למד מגזירה שווה של המלים \u0003\"שם\"\u0004 הנאמרת בשלמים (\"וזבחת שלמים ואכלת שם\", דברים כז, ז), \u0003ו\u0004\u0003\"שם\"\u0004 הנאמר ב\u0003מעשר\u0004 (\"ואכלת... במקום אשר יבחר לשכן שמו שם מעשר דגנך...\" שם יד, כג). \u0003ומינה\u0004 \u0005[וממנה,\u0006 מגזירה שווה זו\u0005]\u0006 נסיק: \u0003מה\u0004 קרבנות ה\u0003שלמים\u0004 — \u0003אין גופן\u0004 (הם עצמם) באים מן ה\u0003מעשר\u0004 עצמו (שהרי המעשר הוא מן הצומח), \u0003אף\u0004 לחמי ה\u0003תודה נמי\u0004 \u0005[גם כן]\u0006 — \u0003אין גופה\u0004 באה מן \u0003ה\u0004\u0003מעשר\u0004 עצמו, \u0003והני\u0004 \u0005חיטי\u0006 \u0005[ואותן חיטים]\u0006 \u0003הלקוחות במעות מעשר שני, נמי\u0004 \u0005[גם כן]\u0006 כיון ש\u0003אין גופן מעשר,\u0004 יכול להביא בהן לחמי תודה.","ועתה, \u0003אימא טעמא דידי\u0004 \u0005[אומר\u0006 מה \u0005הטעם שלי],\u0006 שאין מביאים לחמי תודה אף מחיטים הלקוחות ממעות מעשר שני: דין ה\u0003תודה\u0004 עצמה, \u0003מהיכא קא ילפינא לה\u0004 \u0005[מהיכן אנו לומדים אותה]?\u0006 \u0003משלמים,\u0004 ואת דין ה\u0003שלמים\u0004 שהם באים אף ממעות מעשר, אתה למד מגזירה שווה \u0003\"שם\" \"שם\"\u0004 \u0003ממעשר.\u0004 ומכאן נסיק: \u0003מה\u0004 קרבנות ה\u0003שלמים\u0004 — \u0003אין\u0004 הם מ\u0003מין מעשר, אף תודה\u0004 — \u0003אין מין מעשר,\u0004 ולכך נלמד מכאן \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 את לחמי התודה שאינם באים מ\u0003חיטין הלקוחות במעות מעשר שני,\u0004 שכן \u0003מין מעשר נינהו\u0004 \u0005[הם].\u0006","ועוד בדין הבאת שלמים ממעות מעשר שני, \u0003אמר ר' אמי: המתפיס\u0004 (המקדיש) \u0003מעות\u0004 שחילל עליהן \u0003מעשר שני\u0004 (והריהן עתה קדושות בקדושת מעשר שני) \u0003ל\u0004דמי קרבן ה\u0003שלמים\u0004 — \u0003לא קנו\u0004 (כלומר, לא חלה עליהן קדושת) \u0003שלמים.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 שכן \u0003לא אלימא\u0004 \u0005[אין תקיפה,\u0006 חזקה\u0005]\u0006 \u0003קדושת השלמים למיחל\u0004 \u0005[שתחול]\u0006 על \u0003קדושת מעשר שני\u0004 שבמעות אלה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו במסכת מעשר שני כי עיקר מצות דמי פדיון מעשר שני (המועלים לירושלים לקנות בהם דברי אכילה), הוא להביא בהם זבחי שלמים והקונה בהם בהמה לשלמים — רק בשרה נתפס בקדושת מעשר שני, ולא עורה, והריהו יוצא לחולין. ואף שמעיקר הדין יכול לקנות בהם שאר דברי מאכל ואף בהמה לאכילת חולין, גזרו חכמים שאין לקנות בהם אלא בהמה לזבחי שלמים ולא לאכילה סתם (\"בשר תאוה\"). ומעתה, \u0003הלוקח\u0004 (הקונה) בכסף מעשר שני שלא כהוגן, וכגון שקנה \u0003חיה\u0004 (שאינה עולה לקרבן) \u0003לזבחי שלמים, ו\u0004כן \u0003בהמה לבשר תאוה\u0004 — קנסוהו חכמים, ו\u0003לא יצא העור לחולין.\u0004 ויש לדון בדברים הללו: \u0003לאו למימרא דקני\u0004 \u0005[האם אין\u0006 כוונת הדבר אלא \u0005לומר שקונים,\u0006 שחלה קדושת\u0005]\u0006 דמי \u0003שלמים\u0004 על העור, והרי זה שלא כדברי ר' אמי האומר שאין קדושת שלמים חלה על קדושת מעשר שני!","ודוחים: אין זו כוונת הדברים, שכן \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה,\u0006 בפירוש משנה זו\u0005],\u0006 ש\u0003אמר רב:\u0004 הכוונה היא ש\u0003לא קני\u0004 \u0005[לא קנו,\u0006 לא חלה קדושת\u0005]\u0006 \u0003שלמים\u0004 על העור. \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 הנאמר באותה משנה \u0003\"לא יצא העור לחולין\"? הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 זו הכוונה\u0005]:\u0006 החיה \u0003אינו בתורת\u0004 שלמים כלל \u0003לצאת\u0004 (לענין הוצאת) \u0003העור\u0004 מקדושת מעשר שני \u0003לחולין,\u0004 שבכלל לא חלה קדושת מעשר שני על החיה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר רבה:\u0004 כיון שלקחה שלא כדין, הריהו \u0003נעשה\u0004 (נחשב) \u0003כ\u0004מי ש\u0003לוקח\u0004 בדמי מעשר שני \u0003שור ל\u0004צורך \u0003חרישה,\u0004 שאין חלה עליו כלל קדושת מעשר שני.","ועוד בענין זה, \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדין \u0003המתפיס מעות מעשר שני לשלמים,\u0004 ש\u0003ר' יוחנן אמר: קני\u0004 \u0005[קונה,\u0006 חלה עליהם קדושה\u0005],\u0006 של שלמים. ואילו \u0003ר' אלעזר אומר: לא קני\u0004 \u0005[לא קונה,\u0006 לא חלה\u0005]\u0006 קדושת שלמים.","\u0003ו\u0004מסבירים את מחלוקתם: \u0003אליבא\u0004 \u0005[על פי\u0006 שיטת\u0005]\u0006 \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 כי \u0003מעשר\u0004 שני כ\u0003ממון\u0004 של \u0003הדיוט\u0004 (הבעלים) \u0003הוא\u0004 נחשב — \u0003דכולי עלמא\u0004 \u0005[שהכל,\u0006 ואף ר' אלעזר\u0005]\u0006 \u0003לא פליגי דקני\u0004 \u0005[אינם חלוקים שקונה,\u0006 שחלה \u0005קדושה\u0006\u0005],\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 ר' יוחנן ור' אלעזר הרי \u0005זה\u0006 \u0003אליבא\u0004 \u0005[על פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' מאיר\u0004 ש\u0003אמר\u0004 כי \u0003מעשר\u0004 שני כ\u0003ממון גבוה הוא\u0004 נחשב. ובזאת נחלקו: \u0003מאן דאמר\u0004 \u0005[מי שאומר,\u0006 ר' אלעזר\u0005]\u0006 כי \u0003לא קני\u0004 \u0005[לא קונה],\u0006 הריהו סבור בפשטות \u0003כר' מאיר,\u0004 שהמעשר הריהו ברשות ההקדש. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר,\u0006 \u0005ר' יוחנן\u0006\u0005]\u0006 כי \u0003קני\u0004 \u0005[קונה]\u0006 הריהו סבור כי \u0003כיון\u0004 ש\u0003מעשר קרי ליה\u0004 \u0005[הריהו קרוי]\u0006 \u0003שלמים,\u0004 שכן בהמה הנקנית בסתם מדמי מעשר שני קריבה למזבח כשלמים, לכך \u0003כי מיתפסת ליה\u0004 \u0005[כאשר מתפיסים אותם,\u0006 את דמי מעשר שני בשלמים\u0005]\u0006 — \u0003נמי תפיס\u0004 \u0005[גם כן תופסת\u0006 בהם קדושת שלמים\u0005].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי ר' אלעזר הסבור שאין נתפסת קדושת שלמים על דמי מעשר שני, מברייתא ששנינו בה כי \u0003המתפיס מעות מעשר שני לשלמים\u0004 — חלה קדושת שלמים עליהן, ויש בהן קדושת מעשר שני וקדושת שלמים. ולכך \u0003כשהוא פודן\u0004 את המעות הללו (ודין הפודה שהוא מוסיף חומש בפדיונו) — הריהו \u0003מוסיף עליהם שני חומשין:\u0004 חומש \u0003אחד\u0004 — \u0003לקדש\u0004 (קדושת שלמים) שבו, \u0003ו\u0004חומש \u0003אחד\u0004 — \u0003למעשר\u0004 (קדושת מעשר שני) שבו. הרי איפוא שחלה קדושת שלמים על מעות מעשר שני!","ומשיבים: מכאן אין קושיה, שכן \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 שברייתא זו כ\u0003דברי הכל היא?\u0004 — אין כך הדבר, \u0003אלא\u0004 \u0003הא\u0004 \u0005[זו]\u0006 הברייתא כשיטת \u0003מני\u0004 \u0005[מי היא]?\u0006 כשיטת \u0003ר' יהודה היא,\u0004 הסבור שמעשר שני הריהו ממון הדיוט, ולכך חלה עליו קדושת שלמים. ואילו ר' אלעזר אמר את דבריו לשיטת ר' מאיר, הסבור שמעשר שני הריהו ממון גבוה.","שנינו במשנה הקודמת (פא,ב) כי הנודר \"הרי עלי תודה\" מביא את התודה ואת לחמיה מן החולין, ואסור לו להביאם ממעשר שני. ומרחיבים עוד בענין זה: \u0003מנין לאומר \"הרי עלי תודה\", שלא יביא\u0004 את התודה ואת לחמה \u0003אלא מן החולין?\u0004 — \u0003תלמוד לומר\u0004 בקרבן הפסח \u0003\"וזבחת פסח לה' אלהיך צאן ובקר\"\u0004 (דברים טז, ב), ויש לדון בכתוב זה: \u0003והלא\u0004 קרבן \u0003פסח אין בא אלא מן הכבשים ומן העזים\u0004 (כנאמר בו \"שה תמים זכר בן שנה יהיה לכם מן הכבשים ומן העזים תקחו\", שמות יב, ה), \u0003אם כן מה תלמוד לומר \"צאן ובקר\"? להקיש כל\u0004 קרבן חובה \u0003הבא מן הצאן ומן הבקר ל\u0004קרבן ה\u0003פסח,\u0004 וללמדנו: \u0003מה\u0004 קרבן ה\u0003פסח\u0004 הריהו \u0003דבר שבחובה, ואין\u0004 הוא \u0003בא אלא מן החולין,\u0004 שדין פסח הנוהג לדורות כפסח הראשון שקרב בהיות בני ישראל במצרים, שבא מן החולין ולא מן המעשר (שהרי לא חלו דיני מעשר שני אלא לאחר שנכנסו ישראל לארץ), \u0003אף כל דבר\u0004 קרבן אחר \u0003שבחובה אין בא אלא מן החולין.\u0004","\u0003לפיכך, האומר \"הרי עלי תודה\",\u0004 או \u0003\"הרי עלי שלמים\", הואיל ו\u0004קרבנות אלה \u0003באין חובה\u0004 (בחיוב נדרו) — \u0003לא יביאו אלא מן החולין. ו\u0004אילו ה\u0003נסכים\u0004 הבאים עם התודה והשלמים — \u0003בכל מקום\u0004 (בכל אופן) את נסכיהם \u0003לא יביאו אלא מן החולין\u0004 ולא ממעות מעשר שני. שאין מביאים ממעשר שני אלא דברים הנאכלים לאדם, מה שאין כן הנסכים הקרבים על המזבח.","שנינו במשנתנו שלמדים שאין מביאים דבר שבחובה ממעות מעשר שני נלמד מקרבן פסח, ושואלים: \u0003ו\u0004קרבן \u0003פסח גופיה\u0004 \u0005[עצמו]\u0006 \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 שאינו בא אלא מן החולין? ומסבירים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: נאמר\u0004 בתורה (שמות יב) דין קרבן \u0003פסח\u0004 שהוקרב \u0003במצרים\u0004 (\"פסח מצרים\") בלבד, \u0003ונאמר\u0004 בתורה דין \u0003קרבן\u0004 \u0003פסח\u0004 הקרב \u0003לדורות.\u0004 ומן ההשוואה ביניהם יש ללמוד: \u0003מה פסח האמור במצרים לא בא אלא מן החולין, אף פסח האמור לדורות לא בא אלא מן החולין.\u0004","\u0003אמר לו ר' עקיבא\u0004 לר' אליעזר בשאלה: \u0003וכי דנין\u0004 (למדים דין) דבר ש\u0003אפשר\u0004 (שניתן במציאות להיעשות, וכגון להביא קרבן פסח דורות ממעשר שני) \u0003מ\u0004דבר \u0003שאי אפשר\u0004 (שלא ניתן במציאות להיעשות, וכגון בפסח מצרים, שלא היו להם באותה עת מעשר שני)?! \u0003אמר לו\u0004 ר' אליעזר לר' עקיבא: \u0003אף על פי ש\u0004אכן פסח מצרים מוגדר כ\u0003\"אי אפשר\",\u0004 ואולם בכל זאת \u0003ראייה גדולה היא, ונלמד הימנה.\u0004","\u0003חזר ר' עקיבא ודנו דין\u0004 (והקשה קושיה) \u0003אחר\u0004 על דברי ר' אליעזר: אין ללמוד דין פסח דורות מהשוואתו לפסח מצרים, שהרי יש לומר כי \u0003מה לפסח מצרים\u0004 דווקא הוא אינו בא אלא מן החולין \u0003שכן אין\u0004 הוא \u0003טעון מתן\u0004 (נתינת) \u0003דמים\u0004 על המזבח, \u0003ו\u0004הקרבת ה\u0003אימורין\u0004 (חלקי הקרבן הקרבים) \u0003לגבי\u0004 \u0005[אצל]\u0006 \u0003מזבח,\u0004"],["\u0003תאמר\u0004 כן אף \u0003ב\u0004קרבן \u0003פסח\u0004 הקרב ל\u0003דורות שטעון מתן דמים\u0004 על המזבח, \u0003ו\u0004הקרבת \u0003אימורין לגבי\u0004 \u0005[אצל]\u0006 ה\u0003מזבח?!\u0004 ויש מקום אם כן לומר שקרבן פסח הבא לדורות יבוא אף מן המעשר!","\u0003אמר לו\u0004 ר' אליעזר לר' עקיבא בדחייה: יש להשוות את קרבן פסח דורות לקרבן פסח מצרים, ש\u0003הרי הוא,\u0004 הכתוב הנאמר לבני ישראל במצרים, \u0003אומר:\u0004 \"והיה כי יביאך ה' אל ארץ הכנעני והחתי והאמורי והחוי והיבוסי אשר נשבע לאבותיך לתת לך ארץ זבת חלב ודבש \u0003ועבדת את העבדה הזאת בחדש הזה\"\u0004 (שמות יג, ה), ומכאן \u0003שיהיו כל\u0004 דיני ה\u0003עבודות של חודש הזה\u0004 (פסח דורות) \u0003כ\u0004דיני פסח \u0003זה,\u0004 פסח מצרים.","\u0003ו\u0004דנים בדברי \u0003ר' עקיבא:\u0004 בתחילה הקשה ר' עקיבא על דברי ר' אליעזר המשווה את דין פסח דורות לדין פסח מצרים קושיה עקרונית (שאין ללמוד דבר שאפשר מדבר שאי אפשר), ולאחר מכן חזר ר' עקיבא והקשה על השוואה זו קושיה פרטנית (המצביעה על השוני שבין שני הקרבנות הללו). ו\u0003אי\u0004 \u0005[אם]\u0006 ר' עקיבא \u0003סבר לה\u0004 \u0005[הריהו סבור]\u0006 שכלל הוא ש\u0003אין דנין\u0004 (למדים) דבר ש\u0003אפשר מ\u0004דבר \u0003שאי אפשר\u0004 — \u0003ליקו במילתיה\u0004 \u0005[שיעמוד בדברו]\u0006 זה לדחות את דברי ר' אליעזר!","ו\u0003אי הדר ביה\u0004 \u0005[אם חזר בו]\u0006 ר' עקיבא ומודה שאפשר ללמוד משאי אפשר, \u0003והאי\u0004 \u0005[וזה]\u0006 שהוא \u0003לא גמר\u0004 \u0005[לא למד]\u0006 את דין פסח דורות \u0003מפסח מצרים משום האי פירכא\u0004 \u0005[פירכה זו]\u0006 \u0003הוא\u0004 — על כך יש להקשות: קרבן \u0003פסח\u0004 שהקריבו ישראל בהיותם ב\u0003מדבר\u0004 בשנה השנית לצאתם ממצרים \u0003יוכיח\u0004 שלא כדברי ר' עקיבא אלה, שלמרות שאינו בא אלא מן החולין (שהרי באותה עת לא נהג עדיין מעשר שני), חייב בנתינת דמים על המזבח ובהקרבת אימורים עליו, ויהא כך הדין אף בפסח דורות!","ומשיבים: עיקר טעמו הוא משום שאין ללמוד דבר שאפשר מדבר שאי אפשר. ומה שחזר ר' עקיבא והקשה על ר' אליעזר על השוני שבין הקרבנות, שכן \u0003לדבריו\u0004 (לשיטתו) של \u0003ר' אליעזר קאמר\u0004 \u0005[הוא אמר].\u0006 שכך אמר ר' עקיבא לר' אליעזר: \u0003לדידי\u0004 \u0005[לי עצמי,\u0006 לשיטתי\u0005]\u0006 \u0003אין דנין\u0004 דין דבר ש\u0003אפשר מ\u0004דבר \u0003שאי אפשר,\u0004 ודי לי בטענה זו כשלעצמה, להסיק שאין ללמוד דינו של פסח דורות מדינו של פסח מצרים. ואולם אף \u0003לדידך\u0004 \u0005[לך עצמך,\u0006 לשיטתך\u0005]\u0006 ש\u0003אמרת\u0004 כי \u0003דנין אפשר משאי אפשר,\u0004 מכל מקום אפשר לפרוך את ההשוואה הזו, שהרי \u0003מה לפסח מצרים שכן אינו טעון מתן דמים ואימורין לגבי מזבח, תאמר בפסח דורות שטעון מתן דמים ואימורין לגבי מזבח? ו\u0004בתשובה על כך","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אליעזר\u0004 כי למרות שוני זה יש ללמוד את דינו של פסח דורות מפסח מצרים, משום הכתוב \u0003\"ועבדת\u0004 את העבודה הזאת בחודש הזה\".","ושואלים: \u0003ו\u0004מדוע נזקק \u0003ר' אליעזר\u0004 להביא פסוק זה, \u0003לימא ליה\u0004 \u0005[שיאמר לו,\u0006 לר' עקיבא\u0005]\u0006 כי \u0003פסח מדבר יוכיח\u0004 שהרי אף פסח מדבר שהיתה בו נתינת דם והקרבת אימורים על המזבח, לא בא אלא מן החולין!","ומשיבים: \u0003לדבריו\u0004 של \u0003ר' עקיבא קאמר ליה\u0004 \u0005[הוא אומר לו],\u0006 שכך אמר ר' אליעזר לר' עקיבא: \u0003לדידי\u0004 \u0005[לי עצמי,\u0006 לשיטתי\u0005]\u0006 \u0003דנין אפשר משאי אפשר, ומשום האי פירכא\u0004 \u0005[פירכה זו]\u0006 ששאלת ביחס לשוני שבין פסח מצרים לפסח דורות — \u0003פסח מדבר יוכיח\u0004 שאין זו הסיבה שבגללה אין הפסח בא אלא מן החולין. ואולם אף \u0003לדידך\u0004 \u0005[לך עצמך,\u0006 לשיטתך\u0005]\u0006 ש\u0003אמרת\u0004 כי \u0003אין דנין אפשר משאי אפשר\u0004 — יש להביא ראיה מן הפסוק \u0003\"ועבדת\u0004 את העבודה הזאת בחדש הזה\" המקיש את פסח דורות לפסח מצרים.","ושואלים: \u0003ו\u0004אף \u0003השתא\u0004 \u0005[עכשיו],\u0006 שהביא ר' אליעזר היקש זה, \u0003נמי ליפרוך\u0004 \u0005[גם כן יש לפרוך]\u0006 את ההיקש הזה בטענה שאין ללמוד דבר שאפשר (כפסח דורות) מדבר שאי אפשר (כפסח מצרים)! \u0003אמר רב ששת, זאת אומרת\u0004 (מכלל נלמד) כי \u0003אין משיבין\u0004 (מקשים) \u0003על ההיקש,\u0004 שאין בטענה זו של לימוד דבר שאפשר מדבר שאי אפשר כדי לפרוך היקש.","\u0003ו\u0004מוסיפים \u0003כי\u0004 \u0003בתרביצא\u0004 \u0005[בבית המדרש]\u0006 דנו חכמים בדברי משנתנו שכל הקרבנות הבאים חובה אין באים אלא מן החולין, ונלמד דינם זה מהיקש לקרבן פסח, ובענין זה \u0003אמור\u0004 \u0005[אמרו]\u0006 חכמים בשאלה: \u0003וכי דבר הלמד בהיקש\u0004 (פסח דורות, שנלמד בהיקש מפסח מצרים) \u0003חוזר ומלמד\u0004 על דינם של קרבנות אחרים \u0003בהיקש?\u0004 ומשיבים: אין זה נחשב כלימוד היקש מדבר הנלמד בהיקש, אלא \u0003בכללא איתמר\u0004 \u0005[ב\u0006דרך \u0005כוללת נאמר\u0006 הדבר\u0005],\u0006 שהוקשו כל הקרבנות לקרבן הפסח, שכן ה\u0003פסח כוליה\u0004 \u0005[כולו,\u0006 בכל ענייניו\u0005]\u0006 (פסח מצרים, ופסח דורות) \u0003חדא מילתא היא\u0004 \u0005[דבר אחד הוא].\u0006","ומבררים: \u0003ו\u0004לשיטת \u0003ר' עקיבא,\u0004 שדחה את ראיותיו של ר' אליעזר, הלכה זו שה\u0003פסח אינו בא אלא מן החולין מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו]\u0006 דין זה \u0003מהא\u0004 \u0005[מ\u0006שמועה \u0005זו]\u0006 ש\u0003אמר שמואל משום\u0004 \u0005[בשם]\u0006 \u0003ר' אליעזר:\u0004 מה שנאמר בסוף פרשת הקרבנות \u0003\"זאת התורה לעלה ולמנחה ולחטאת ולאשם ולמלואים ולזבח השלמים\"\u0004 (ויקרא ז, לז), בא ללמדנו שהושוו קרבנות אלה זה לזה, ובאופן זה:","\u0003\"עולה\"\u0004 — \u0003מה עולה\u0004 \u0003טעונה\u0004 (חייבת) \u0003כלי\u0004 שרת כדי להתקדש, \u0003אף\u0004 שאר \u0003כל\u0004 קרבן \u0003טעון כלי\u0004 שרת. ומבררים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 כוונת הדברים שהעולה חייבת בכלי שרת? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שנצרך דם העולה להינתן על המזבח ב\u0003מזרק\u0004 (כלי לקבלת הדם), וללמדנו שהוא הדין בכל הקרבנות — ואולם לשם זה אין צורך ללמוד מעולה, שכן \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003זבחי שלמי ציבור נמי כתיב\u0004 \u0005[גם כן נאמר]\u0006 \"...ויעלו עולות ויזבחו זבחים שלמים לה' פרים. ויקח משה חצי הדם \u0003וישם\u0004 \u0003באגנת\u0004 וחצי הדם זרק על המזבח\" (שמות כד, ה—ו), הרי שבקרבנות עולה ושלמים נאמר כבר שנזרק דמם על המזבח מן הכלי!","\u0003אלא\u0004 הכוונה היא שצריכה העולה \u0003סכין\u0004 לשחיטתה, וממנה נלמדים שאר כל הקרבנות. ומבררים: \u0003ועולה גופה מנלן\u0004 \u0005[עצמה מנין לנו]\u0006 שצריכה סכין לשחיטתה? \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בעקידת יצחק: \u0003\"וישלח אברהם את ידו ויקח את המאכלת לשחט את בנו\"\u0004 (בראשית כב, י), \u0003והתם\u0004 \u0005[ושם]\u0006 יצחק הלא קרבן \u0003עולה הוא\u0004 נחשב, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 לאחר מכן \"...והנה איל אחר נאחז בסבך בקרניו וילך אברהם ויקח את האיל \u0003ויעלהו לעלה תחת בנו\"\u0004 (שם יג).","וממשיכים עוד בדרשת הכתוב: מה שנאמר בו \"ל \u0003מנחה\"\u0004 בא להקביל את דין כל הקרבנות לדין המנחה, \u0003מה\u0004 ה\u0003מנחה אינה נאכלת אלא לזכרי כהונה\u0004 כהנים זכרים, \u0003אף\u0004 בשרם של \u0003כל\u0004 הקרבנות \u0003אין נאכלין אלא לזכרי כהונה.\u0004 ומבררים: \u0003מאי\u0004 \u0005[מה]\u0006 כוונת הדברים שבשר כל הקרבנות נאכל על ידי זכרי כהונה? \u0003אי\u0004 \u0005[אם]\u0006 הכוונה היא לבשר קרבנות \u0003ה\u0004\u0003חטאת ו\u0004ה\u0003אשם,\u0004"],["ויש לשאול: הרי אין צורך בכתוב מיוחד לשם כך, שהרי \u0003בהדיא כתיב\u0004 \u0005[במפורש נאמר]\u0006 בתורה בקרבנות החטאת והאשם שבשרם נאכל על ידי כהנים זכרים!","ו\u0003אי\u0004 \u0005[אם]\u0006 בא הכתוב \"זאת התורה... למנחה\" (ויקרא ז, לז), ללמד ש\u0003זבחי שלמי ציבור\u0004 נאכלים לכהנים זכרים — אף לכך לא נצרך הכתוב, שכן \u0003מרבויא דקראי אתי\u0004 \u0005[מריבוי המקראות\u0006 הם \u0005באים,\u0006 נלמדים\u0005],\u0006 שכן נאמר \"זה יהיה לך מקדש הקדשים מן האש כל קרבנם לכל מנחתם ולכל חטאתם ולכל אשמם אשר ישיבו לי קודש קדשים לך הוא ולבניך. \u0003בקדש הקדשים תאכלנו כל זכר בכהנים יאכל אותו\u0004 קדש יהיה לך\" (במדבר יח, ט— י) — \u0003לימד\u0004 מקרא \u0003זה\u0004 \u0003על זבחי שלמי ציבור שאין נאכלים אלא לזכרי כהונה!\u0004 ומשיבים: הכתוב \"זאת התורה...","למנחה\" בא ללמדנו שזבחי שלמי ציבור נאכלים על ידי זכרי כהונה, ומה ששאלו שאין צורך בכתוב זה — מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא\u0004 מהיכן נלמדת הלכה זו, \u0003איכא דמייתי לה\u0004 \u0005[יש שמביאים,\u0006 למדים, \u0005אותה]\u0006 \u0003מהכא\u0004 \u0005[מכאן,\u0006 מהכתוב \"זאת התורה... \u0005למנחה\"\u0006\u0005],\u0006 \u0003ואיכא דמייתי לה\u0004 \u0005[ויש שמביאים,\u0006 למדים, \u0005אותה]\u0006 \u0003מהכא\u0004 \u0005[מכאן,\u0006 מהכתוב \"בקודש הקדשים תאכלנו כל זכר יאכל אותו\"\u0005].\u0006 וממשיכים עוד בדרשת הכתוב: נאמר בפסוק \"זאת התורה...","ול\u0003חטאת\"\u0004 — להקיש כל הקרבנות לדין החטאת וללמד: \u0003מה חטאת, מקדשה\u0004 \u0005[מקדשת,\u0006 מחילה את קדושתה\u0005]\u0006 על קרבן אחר \u0003בבלוע\u0004 (בבליעה), שאם בלע בשר קרבן שלמים שזמן אכילתו שני ימים ולילה מבשר החטאת שזמן אכילתו יום ולילה בלבד — אף בשר קרבן השלמים נאכל ליום ולילה בלבד, כבשר החטאת. וכך הוא הדין \u0003אף\u0004 ב\u0003כל\u0004 הקרבנות, שהריהם \u0003מקדשה\u0004 \u0005[מקדשת]\u0006 \u0003בבלוע.\u0004 ועוד בדרשת הכתוב: מה שנאמר בפסוק \"זאת התורה...","ול\u0003אשם\"\u0004 בא להקיש את כל הקרבנות לאשם, וללמד: \u0003מה\u0004 קרבן \u0003אשם, אין שפיר\u0004 (עובר) \u0003ושליא\u0004 (כעין כיס שבתוכו נוצר הולד) \u0003קדוש בו,\u0004 שכן קרבן האשם הריהו ממין זכר ולא יתכנו בו שפיר ושליה, \u0003אף\u0004 ב\u0003כל\u0004 קרבן אחר, \u0003אין שפיר ושליא קדוש בו.\u0004 ומסבירים: טעם שיטת ר' אליעזר שאין השפיר והשליה מתקדשים בקדושת הקרבן, שכן \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 כי ה\u0003ולדות\u0004 של בהמות ה\u0003קדשים\u0004 רק \u0003בהוייתן\u0004 (בלידתם) \u0003הן קדושים,\u0004 ולא בעודם במעי אימם. \u0003ו\u0004כן סבור ר' אליעזר בדרכי הלימוד כי \u0003דנין\u0004 (ניתן ללמוד) את דינו של דבר שהוא \u0003אפשר\u0004 במציאות (כגון שפיר ושליה בשאר קרבנות שממין נקבה) \u0003מ\u0004תוך השוואה לדינו של דבר \u0003ש\u0004הוא \u0003אי אפשר\u0004 במציאות (כגון קרבן אשם שהרי הוא ממין זכר). וממשיכים עוד בדרשת הכתוב: מה שנאמר בו \"זאת התורה...","\u0003ול\u0004\u0003מלואים\"\u0004 בא להקיש את כל הקרבנות לדין קרבנות המילואים, ולומר: \u0003מה\u0004 קרבנות ה\u0003מלואים, מותריהן\u0004 (הנותר מבשרם), דינו \u0003בשריפה\u0004 (\"ואם יותר מבשר המלואים ומן הלחם עד הבוקר ושרפת את הנותר באש לא יאכל כי קודש הוא\". שמות כט, לד), \u0003ו\u0004אולם \u0003אין בעלי חיים\u0004 (בעודם חיים) ש\u0003מותריהן\u0004 \u0003בשריפה,\u0004 שכן אין מקדישים במילואים קרבן אחר לאחריות. \u0003אף\u0004 ב\u0003כל\u0004 שאר הקרבנות דין \u0003מותריהן בשריפה, ואין\u0004 דין \u0003בעלי חיים מותריהן בשריפה.\u0004 ומן הכתוב \"זאת התורה...","ולזבח ה\u0003שלמים\"\u0004 אנו למדים להקיש את כל הקרבנות לשלמים, ולענין זה: \u0003מה\u0004 ה\u0003שלמים מפגלין\u0004 (כשחשב הכהן בשעת עבודתו לאוכלם מחוץ לזמנם הראוי), אף את הנסכים הבאים אתם, \u0003ו\u0004כמו כן הם עצמם \u0003מתפגלין\u0004 על ידי נסכיהם שהתפגלו במחשבת הכהן להקריבם מחוץ לזמנם, הוא הדין \u0003אף\u0004 בשאר \u0003כל\u0004 הקרבנות שהריהם \u0003מפגלין ומתפגלין.\u0004","\u0003במתניתא תנא משמיה\u0004 \u0005[בברייתא שנה\u0006 החכם \u0005משמו]\u0006 של \u0003ר' עקיבא\u0004 אופן שונה בדרשת כתוב זה: \u0003\"זאת התורה...\u0004 ל\u0003מנחה\"\u0004 — \u0003מה מנחה מקדשת\u0004 (מחילה דין קדושתה) \u0003בבלוע\u0004 (דבר שבלע ממנה), שכן נאמר בה \"כל אשר יגע בהם יקדש\". ויקרא ו, יא), \u0003אף\u0004 \u0003כל\u0004 שאר הקרבנות הריהם \u0003מקדשת בבלוע.\u0004","ומעירים: \u0003ואיצטריך למכתב\u0004 \u0005[והוצרך לכתוב]\u0006 \u0003בחטאת\u0004 (\"ולחטאת\") ללמד דין בליעה בשאר קרבנות, \u0003ו\u0004כן \u0003איצטריך למכתב\u0004 \u0005[הוצרך לכתוב]\u0006 כן גם \u0003במנחה\u0004 (\"למנחה\"). משום \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק \u0003במנחה,\u0004 ולא בחטאת — היינו אומרים שכך הדין רק במנחה, וטעם הדבר: \u0003משום דרכיכא\u0004 \u0005[ש\u0006היא \u0005רכה],\u0006 ולכך היא בכלל \u0003בלעה\u0004 \u0005[בליעה],\u0006 שמבליעה באחרים. \u0003אבל חטאת,\u0004 שהיא בשר וקשה, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 מבליעה, ולא יהיה הנוגע בה קדוש בקדושתה — לכך נדרש לכתוב כן גם בחטאת. \u0003ו\u0004מצד שני, \u0003אי כתב רחמנא\u0004 \u0005[אם היתה כותבת התורה]\u0006 רק \u0003בחטאת\u0004 ולא במנחה — היינו אומרים שהדין רק בחטאת, וטעם הדבר: \u0003משום\u0004 שה\u0003בשר אגב\u0004 \u0005[מתוך]\u0006 שהוא \u0003שמן\u0004 הריהו \u0003קדיר\u0004 \u0005[מפעפע]\u0006 בדבר הבא עמו במגע ומבליע בו, ולכך הריהו מחיל עליו קדושתו. \u0003אבל מנחה, אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהיה הדבר הנוגע בה קדוש בקדושתה — לכך \u0003צריכא\u0004 \u0005[צריך]\u0006 לכתוב כן גם במנחה. וממשיך ר' עקיבא עוד בדרשת כתוב זה: \"זאת התורה...","ול\u0003חטאת\"\u0004 בא ללמד כי \u0003מה\u0004 ה\u0003חטאת אינה באה אלא מן החולין,\u0004 וקרבה דווקא \u0003ביום, ו\u0004עבודתה נעשית דווקא \u0003בידו הימנית\u0004 של הכהן. \u0003אף\u0004 שאר \u0003כל\u0004 קרבן \u0003אינו בא אלא מן החולין, ו\u0004קרב רק \u0003ביום, ו\u0004העבודה בו נעשית רק \u0003בידו הימנית\u0004 של הכהן.","ומבררים: \u0003וחטאת גופה מנלן\u0004 \u0005[עצמה מנין לנו]\u0006 שבאה רק מן החולין, ולא מן המעשר? \u0003אמר רב חסדא,\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין קרבן החטאת: \u0003\"והקריב אהרן את פר החטאת אשר לו\"\u0004 (ויקרא טז, יא), ללמד: \"אשר \u0003לו\"\u0004 — שיהא הקרבן \u0003משלו\u0004 (מן החולין) \u0003ולא משל\u0004 ה\u0003מעשר.\u0004 ושואלים: שנינו בדברי ר' עקיבא כי דינם של שאר הקרבנות שהם קרבים רק \u0003ביום\u0004 נלמד מן הכתוב \"זאת התורה...","ולחטאת\", ואולם הלכה זו \u0003מ\u0004הכתוב לאחר מכן \"אשר צוה ה' את משה \u0003בהר סיני\u0004 \u0003ביום צותו\u0004 את בני ישראל להקריב את קרבניהם לה' במדבר סיני\" (שם ז, לח) \u0003נפקא\u0004 \u0005[יוצאת,\u0006 נלמדת\u0005]!\u0006 ואומרים: דבר זה \u0003כדי נסבה\u0004 \u0005[לחינם הביאה],\u0006 כלומר, באמת אין דין עבודת הקרבנות ביום נלמד מ\"זאת התורה.. ולחטאת\" אלא מ\"ביום צוותו\", ובדרך אגב הביא גם לימוד זה.","ושואלים עוד: מה שאמר ר' עקיבא כי דין זה שעבודת הקרבנות צריכה להיעשות דווקא \u0003בידו הימנית\u0004 של הכהן נלמד מן הכתוב \"זאת התורה... ולחטאת\", ואולם דבר זה הרי \u0003מ\u0004דברי \u0003רבה בר בר חנה נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005],\u0006 שכן \u0003אמר רבה בר בר חנה, אמר ריש לקיש: כל מקום שנאמר\u0004 בתורה \u0003\"אצבע\" ו\u0004כן \u0003כהונה\u0004 בעבודת המקדש — \u0003אינו אלא ימין!\u0004 ואומרים: אף הלכה זו \u0003כדי נסבה\u0004 \u0005[לחינם הביאה],\u0006 והוזכרה בדברי ר' עקיבא אגב עיקר דבריו. עוד דרש ר' עקיבא את הנאמר \"זאת התורה...","ול\u0003אשם\",\u0004 ללמד: \u0003מה אשם עצמותיו\u0004 שאינן ראויות לאכילה \u0003מותרין\u0004 לעשות מהם כלים. \u0003אף כל\u0004 קרבן \u0003עצמותיו מותרין.\u0004","ודנים עוד בדברי ר' עקיבא שבברייתא זו: במשנתנו שנינו כי מן הכתוב \"וזבחת פסח לה' אלקיך צאן ובקר\" (דברים טז, ב) למדים אנו בדרך היקש שכל קרבן חובה דינו הוא כקרבן הפסח, ואינו בא אלא מן החולין, ומעתה יש לברר: \u0003ור' עקיבא\u0004 הלומד הלכה זו מן הכתוב \"זאת התורה... ולחטאת\", \u0003האי\u0004 \u0005[זה\u0006 הכתוב\u0003]\u0004 \u0003\"וזבחת פסח\"\u0004,"],["\u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו],\u0006 מה הוא לומד ממנו? ומשיבים: \u0003מבעי ליה\u0004 \u0005[צריך\u0006 ר' עקיבא \u0005אותו]\u0006 כתוב \u0003ל\u0004למוד על הדין שאמר \u0003רב נחמן,\u0004 ש\u0003אמר רב נחמן, אמר רבה בר אבוה: מנין למותר\u0004 קרבן \u0003הפסח\u0004 (וכגון שהפריש מעות לצורך הפסח, וקנה בחלק מהן את הקרבן, ונותרו בידו מן המעות הללו) \u0003שקרב\u0004 כקרבן \u0003שלמים? שנאמר: \"וזבחת פסח לה' אלהיך צאן ובקר\"\u0004 (דברים טז, ב). שכן יש לשאול: \u0003והלא אין\u0004 קרבן ה\u0003פסח בא אלא מן הכבשים ומן העזים,\u0004 ולמה נאמר \"צאן ובקר\"? \u0003אלא\u0004 ללמדנו לענין \u0003מותר הפסח\u0004 ש\u0003יהא\u0004 קרב \u0003לדבר\u0004 (קרבן) \u0003הבא מן הצאן ומן הבקר,\u0004 והוא קרבן השלמים.","ושואלים: \u0003ו\u0004האם דין \u0003הא\u0004 \u0005[זה]\u0006 שמותר הפסח קרב שלמים \u0003מהכא נפקא\u0004 \u0005[מכאן,\u0006 מפסוק זה הוא \u0005יוצא,\u0006 נלמד\u0005]?\u0006 והלא \u0003מדאבוה\u0004 \u0005[מ\u0006דברים \u0005של אביו]\u0006 של \u0003שמואל נפקא\u0004 \u0005[יוצא,\u0006 נלמד הדבר\u0005],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בפרשת השלמים \"ו \u0003אם מן הצאן קרבנו לזבח שלמים\"\u0004 (ויקרא ג, ו), ומקרא יתר הוא, \u0003ואמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל\u0004 כי בא הכתוב ללמדנו: ש\u0003דבר\u0004 (קרבן) \u0003הבא מן הצאן\u0004 בלבד, קרבן הפסח, מותרו \u0003יהא לזבח שלמים!\u0004","וממשיכים: \u0003ואכתי\u0004 \u0005[ועדיין,\u0006 ועוד\u0005]\u0006 יש להוסיף ולשאול: האם דין זה \u0003מהכא נפקא\u0004 \u0005[מכאן,\u0006 הוא \u0005יוצא,\u0006 נלמד\u0005]?\u0006 והלא \u0003מהתם נפקא\u0004 \u0005[משם,\u0006 מן הכתוב שיובא להלן בברייתא, הוא \u0005יוצא,\u0006 נלמד\u0005]!\u0006 \u0003והתניא\u0004 \u0005[ו\u0006כך היא \u0005שנויה\u0006 בברייתא\u0005],\u0006 אף שנאמר שהשלמים באים מן הצאן (\"ואם מן הצאן קרבנו לזבח שלמים לה' זכר או נקבה תמים יקריבנו\"), מוסיף הכתוב ומפרט \"אם כשב הוא מקריב את קרבנו... ואם עז קרבנו\" (שם ג, ו— יב). ובא המקרא הנוסף \u0003\"כבש\" לרבות את\u0004 קרבן \u0003הפסח ל\u0004חובת הקרבת ה\u0003אליה\u0004 שלו על המזבח, וכדרך שמקריבים בכבש השלמים.","ו\u0003כשהוא\u0004 (כתוב \u0003זה)\u0004 \u0003אומר: \"אם כבש\",\u0004 המלה \"אם\" הריהי מקרא יתר, ובאה ללמד — \u0003להביא\u0004 (לרבות) את קרבן ה\u0003פסח שעברה שנתו\u0004 ונפסל בכך מלהיקרב לפסח (שכן דינו הוא דווקא בן שנתו), ועמד והביא שה אחר לקרבנו, ואילו קרבן זה הריהו בכלל \"מותר פסח\". \u0003ו\u0004כן יש לרבות את קרבנות ה\u0003שלמים הבאים מחמת\u0004 (מכח) קרבן ה\u0003פסח\u0004 (שנוספו אלה, כדי שיתוסף על ידם בשר, וייאכל קרבן הפסח על השובע), שדינם \u0003ל\u0004ענין \u0003כל\u0004 ה\u0003מצות\u0004 כקרבן \u0003שלמים:\u0004 \u0003שיטענו סמיכה\u0004 עליהם, \u0003ונסכים ותנופת חזה ושוק.\u0004 ומוסיפים ודורשים עוד על הנאמר בפרשת השלמים: \u0003כשהוא\u0004 (הכתוב\u0003)\u0004 \u0003אומר\u0004 לאחר מכן \u0003\"ואם עז\"\u0004 — הרי זה כפותח ענין חדש, ו\u0003הפסיק הענין\u0004 הקודם, ומכאן \u0003לימד\u0004 הכתוב \u0003על העז\u0004 הבאה בקרבן שלמים, \u0003שאינה טעונה\u0004 הקרבת ה\u0003אליה.\u0004 ויש לשאול: מדוע נצרכים מקראות אלה ללמדנו לענין מותר הפסח שהוא קרב כשלמים, והרי לדעת ר' עקיבא נדרש הדבר מן האמור \"וזבחת פסח לה' אלקיך צאן ובקר\"!","","ומשיבים: \u0003תלתא קראי כתיב\u0004 \u0005[שלושה מקראות כתובים\u0006 בפרשת השלמים\u0005]\u0006 ונצרכים כולם כדי להשמיענו שלוש הלכות: כתוב \u0003חד\u0004 \u0005[אחד]\u0006 בא ללמדנו \u0003ל\u0004עניינו של מותר הפסח ש\u0003עברה זמנו\u0004 (זמן הקרבת הפסח), \u0003ו\u0004אף \u0003עברה שנתו\u0004 שעתה הוא בן יותר משנה, ופסול מלשמש לקרבן פסח. \u0003ו\u0004כתוב \u0003חד\u0004 \u0005[אחד],\u0006 שני, בא ללמדנו \u0003ל\u0004עניינו של קרבן הפסח ש\u0003עברה זמנו ו\u0004אולם \u0003לא עברה שנתו. ו\u0004כתוב \u0003חד\u0004 \u0005[אחד]\u0006 נוסף, \u0005שלישי, בא ללמדנו\u0006 \u0003ל\u0004זה ש\u0003לא עברה זמנו ולא עברה שנתו,\u0004 וכגון שאבד הפסח קודם חצות היום, והפריש אחר תחתיו, והריהו \"מותר הפסח\", וכל אלה קרבים כשלמים.","ומסבירים: \u0003וצריכי\u0004 \u0005[וצריכים]\u0006 כל שלושת הכתובים הללו להיאמר, משום \u0003דאי אשמעינן\u0004 \u0005[שאם היה\u0006 הכתוב \u0005משמיע לנו]\u0006 רק דינו של זה שגם \u0003עברה זמנו ו\u0004גם \u0003עברה שנתו,\u0004 שהריהו קרב כשלמים, היינו אומרים כי כך הדין בזה דווקא — \u0003משום דאידחי ליה\u0004 \u0005[שנדחה לו]\u0006 \u0003לגמרי, אבל\u0004 קרבן פסח ש\u0003עברה זמנו ולא עברה שנתו, דחזי\u0004 \u0005[ש\u0006עדיין \u0005ראוי]\u0006 הוא \u0003ל\u0004הקרבה ב\u0003פסח שני,\u0004 בחודש אייר, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יביאו אותו לשלמים — לכך נצרך כתוב נוסף.","\u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 שכך הדין רק ב\u0003עברה זמנו ולא עברה שנתו\u0004 בלבד, היינו אומרים כי דווקא הוא קרב כשלמים — משום \u0003דאידחי ליה\u0004 \u0005[שנדחה הוא]\u0006 \u0003מ\u0004הקרבה ב\u0003פסח ראשון, אבל\u0004 \u0003לא עברה זמנו ולא עברה שנתו,\u0004 ש\u0003אפילו לפסח ראשון נמי חזי\u0004 \u0005[גם כן ראוי]\u0006 להקרבה, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהיה לשלמים — על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמר כתוב שלישי, להשמיענו שגם זה קרב כשלמים.","","\u0003כל\u0004 המנחות הקרבות במקדש, הן אלה הבאות כ\u0003קרבנות הציבור ו\u0004הן אלה הבאות כקרבנות \u0003היחיד,\u0004 הריהן \u0003באין\u0004 (מובאים, נלקחים) מכל יבולי התבואה: \u0003מן ה\u0004תבואה שגדלה ב\u0003ארץ\u0004 ישראל, \u0003ומ\u0004התבואה שגדלה ב\u0003חוצה לארץ,\u0004 הן \u0003מן החדש\u0004 (תבואת שנה זו, שנקצרה לפני הנפת העומר בפסח) \u0003ו\u0004הן \u0003מן\u0004 \u0003הישן\u0004 (שנקצר בשנים קודמות). \u0003חוץ מן העומר ושתי הלחם\u0004 \u0003ש\u0004שני אלה \u0003אינן באין\u0004 \u0003אלא מן החדש ו\u0004רק \u0003מן ה\u0004תבואה הגדלה ב\u0003ארץ. ו\u0004אולם בדבר זה שוות כל המנחות \u0003כולן\u0004 — שהן \u0003אינן באין אלא מן ה\u0004יבול היותר \u0003מובחר\u0004 (משובח). \u0003ואיזהו\u0004 ה\u0003מובחר שלהם\u0004 ממנו תובא הסולת למנחה? התבואה הגדלה במקום הנקרא \u0003מכניס ו\u0004כן זו הגדלה במקום הנקרא \u0003זטחא\u0004 — הריהי \u0003אלפא\u0004 (הראשונה במעלה) הקודמת \u0003לסלת\u0004 הבאה משאר כל המקומות. \u0003שנייה להן\u0004 — היא הסולת הבאה מהתבואה שגדלה במקום הנקרא \u0003עפוריים\u0004 ש\u0003בבקעה.\u0004","","ומסבירים: אכן מעיקר הדין תבואות \u0003כל הארצות\u0004 (האיזורים) \u0003היו כשרות\u0004 להבאת סולת המנחה, \u0003אלא\u0004 ש\u0003מכאן\u0004 (מהמקומות הללו המנויים למעלה) \u0003היו מביאין,\u0004 שהם היו המובחרים.","שנינו במשנתנו כי העומר ושתי הלחם באים דווקא מהיבול החדש, ומכאן יש להסיק כי אם הביא מנחות אלה מהיבול הישן — הרי אלה פסולות. ומעירים: דעת \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 זו הריהי ש\u0003לא כי\u0004 \u0005[כמו]\u0006 דעתו של \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא,\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 ה\u0003עומר הבא מן\u0004 היבול \u0003הישן,\u0004 ולא מהתבואה החדשה, כמצוותו הראויה — הריהו \u0003כשר.\u0004 וכן \u0003שתי הלחם הבאות מן\u0004 היבול \u0003הישן,\u0004 ולא מן החדש, כמצוותם הראויה — הריהם \u0003כשרות, אלא שחיסר מצוה.\u0004 ומסבירים את מקור הדברים: ה\u0003עומר\u0004 — שכן אף \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במנחת העומר \"ואם תקריב מנחת בכורים לה' אביב קלוי באש גרש כרמל\", נאמר עוד \u0003\"תקריב את מנחת בכוריך\"\u0004 (ויקרא ב, יד), ובאה הלשון הנוספת \"תקריב את מנחת בכוריך\" להשמיענו כי בדיעבד יכולה זו להיות ישנה, \u0003ואפילו מן ה\u0004תבואה של השנה שעברה, הנמצאת זה מכבר ב\u0003עלייה.\u0004 וכן \u0003שתי הלחם\u0004 הבאים מהתבואה הישנה \u0003כשרים\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בשתי הלחם \"...והקרבתם מנחה חדשה לה'. \u0003ממושבתיכם תביאו\u0004 לחם תנופה שתים...\" (שם כג, טז—יז). והלשון \"ממושבותיכם\" באה למעט: דווקא מתבואת ארץ ישראל — \u0003ולא מן\u0004 תבואת \u0003חוצה לארץ. \"ממושבתיכם\"\u0004 בא לרבות — מכל תבואת הארץ אתה מביא, \u0003ואפילו מן\u0004 התבואה הנמצאת ב\u0003עלייה.\u0004 ותוהים: כיצד יכול אתה ללמוד ממלה זו \u0003לרבות,\u0004 \u0003הא אפיקתיה\u0004 \u0005[הרי\u0006 כבר \u0005הוצאת,\u0006 דרשת \u0005אותו\u0006 פסוק\u0005]\u0006 למעט את תבואת חוצה לארץ! ומסבירים: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \"ממושבותיכם \u0003תביאו\", ו\u0004מן הכתוב \"תביאו\" אנו למדים — \u0003אפילו מן העלייה.\u0004","","","","וחוזרים ושואלים: \u0003והאי מיבעי ליה\u0004 \u0005[ו\u0006הרי אף כתוב זה נצרך לו] ללימוד אחר, \u0003שכל\u0004 מקרה \u0003שאתה מביא\u0004 חמץ \u0003ממקום אחר,\u0004 כלומר, בשאר מנחות (כלחמי תודה) — דינו ש\u0003הרי הוא כזה!\u0004 ומשיבים: \u0003אם כן\u0004 שבא הכתוב ללמד רק לענין זה, \u0003ליכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 \u0003\"תביא\"\u0004 בלבד, ולא \"תביאו\", ו\u0003מאי\u0004 \u0005[מה]\u0006 תוספת ה—ו' \u0003\"תביאו\"? שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003תרתי\u0004 \u0005[שני]\u0006 לימודים נלמדים מכאן, לענין דין החמץ שבלחמי התודה, ולענין דין התבואה הישנה בשתי הלחם.","ושואלים על עצם הדין: מדוע העומר ושתי הלחם הבאים מתבואה ישנה כשרים, \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בשני אלה הלשון \u0003\"ראשית\"\u0004 (בעומר: \"...וקצרתם את קצירה והבאתם את עומר ראשית קצירכם אל הכהן\". שם כג, י. ובשתי הלחם: \"קרבן ראשית תקריבו אותם לה'...\". שם ב, יב), ללמד שאין להביא אלא מן התבואה החדשה! ומשיבים: אין זה אלא \u0003למצוה,\u0004 לעשות לכתחילה, ואולם אם הביאו מן התבואה הישנה, הרי זה כשר.","ושואלים עוד: \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 בשתי הלחם במפורש \"והקרבתם מנחה \u0003חדשה\",\u0004 ומדוע שתי הלחם הבאים מהתבואה הישנה כשרים? ומתרצים: \u0003האי מיבעי ליה\u0004 \u0005[\u0006כתוב \u0005זה נצרך לו]\u0006 \u0003ל\u0004למד הלכה אחרת, \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003ר' נתן ור' עקיבא אמרו: שתי הלחם הבאות מן הישן\u0004 — הריהם \u0003כשרות, ומה\u0004 (וכיצד) \u0003אני מקיים\u0004 (מסביר) את האמור בשתי הלחם \"מנחה \u0003חדשה\"?\u0004 — \u0003שתהא חדשה לכל המנחות,\u0004 שיש להביא תחילה את שתי הלחם לפני שיביאו כל מנחה אחרת מן החדש, שאין שאר מנחות באות מן היבול החדש אלא אם כן כבר הוקרבו שתי הלחם, ואולם שתי הלחם עצמם יכולים לבוא אף מן התבואה הישנה.","למעלה נאמר כי חלוקים התנא של משנתנו והתנא של הברייתא בדין העומר ושתי הלחם שהביאום מן הישן, אם הם כשרים בדיעבד. ועתה דנים בדינם של העומר והחדש מחוצה לארץ אם כשרים הם בדיעבד. ומעירים: \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 התנאים הללו \u0003אלא ב\u0004דינם של המנחות שהביאם שלא מן ה\u0003חדש,\u0004"],["\u0003אבל ב\u0004כך שיהיו דווקא מתבואת ה\u0003ארץ, לא פליגי\u0004 \u0005[אינם חלוקים],\u0006 ולדעת הכל ה\u0003עומר ושתי הלחם, מ\u0004תבואת \u0003ה\u0004\u0003ארץ\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מביאים, ואילו \u0003מ\u0004תבואות \u0003חוצה לארץ\u0004 — \u0003לא\u0004 מביאים.","ומבררים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 היא? הרי זו ש\u0003לא כי\u0004 \u0005[כמו]\u0006 שיטתו של \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי בר ר' יהודה אומר:\u0004 ה\u0003עומר\u0004 \u0003בא\u0004 לכתחילה אף \u0003מ\u0004תבואת \u0003חוצה לארץ, ומה\u0004 (וכיצד) \u0003אני מקיים\u0004 (מסביר) את האמור בעומר \u0003\"כי תבאו אל הארץ\u0004 אשר אני נותן לכם וקצרתם את קצירה והבאתם את עומר ראשית קצירכם אל הכהן\" (ויקרא כג, י)? אין כוונת הכתוב לומר שמביאים את העומר רק מתבואת הארץ, אלא להשמיענו \u0003שלא נתחייבו\u0004 ישראל \u0003ב\u0004מצות הנפת \u0003ה\u0004\u0003עומר קודם שנכנסו לארץ\u0004 ישראל, ואולם לאחר שנתחייבו יכולים להביאם מכל מקום ואף מחוץ לארץ.","\u0003וקסבר\u0004 \u0005[וסבור]\u0006 ר' יוסי בר ר' יהודה כי איסור אכילת היבול \u0005ה\u0006\u0003חדש\u0004 קודם הנפת העומר נוהג אף \u0003בחוצה לארץ,\u0004 ואיסור \u0003דאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003היא.\u0004 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ממושבתיכם\"\u0004 (\"ולחם וקלי וכרמל לא תאכלו עד עצם היום הזה עד הביאתם את קרבן אלהיכם חוקת עולם לדורותיכם בכל מושבותיכם\". שם יד), שכן \"מושבותיכם\" — \u0003כל מקום שאתם יושבין משמע,\u0004 אף בחוצה לארץ. \u0003ו\u0004אף שנאמר \u0003\"כי תבאו\u0004 אל הארץ אשר אני נותן לכם\", כוונת הדברים להשמיענו מאיזה זמן הריהו נוהג, ש\u0003זמן\u0004 ה\u0003ביאה\u0004 של בני ישראל לארץ \u0003היא\u0004 העת בה החל נוהג איסור זה. \u0003וכיון\u0004 שאיסור חדש אף בחוץ לארץ \u0003דאורייתא היא\u0004 \u0005[מן התורה הוא]\u0006 — אף \u0003אקרובי\u0004 \u0005[להקריב]\u0006 מן היבול החדש שבחוצה לארץ לעומר \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מקריבין.\u0004","ומביאים עוד בדיני התבואה המובאת לעומר. \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 האנשים שמונו על ידי בית הדין לשמש כ\u0003שומרי\u0004 מקצת מן ה\u0003ספיחין\u0004 (פירות התבואה שגדלו בשנת השמיטה מעצמם, שלא על ידי עבודת אדם בהם), שהם הפקר לכול \u0003ב\u0004שנה ה\u0003שביעית\u0004 (שנת השמיטה). ותפקיד השומרים להודיע לעניים לבל ילקטו מתבואות אלה, ולהרחיק בעלי חיים מלאוכלן, שהן מיועדות להביא מהן את העומר בחג הפסח ואת שתי הלחם בחג השבועות, שומרים אלה \u0003נוטלין\u0004 את \u0003שכרן\u0004 על מלאכה זו \u0003מתרומת הלשכה.\u0004","ונמסר כי \u0003רמי ליה\u0004 \u0005[השליך לו,\u0006 הראה \u0005סתירה\u0006\u0005]\u0006 \u0003רמי בר חמא לרב חסדא,\u0004 שכן \u0003תנן\u0004 \u0005[שנינו]\u0006 מצד אחד כי \u0003שומרי ספיחין בשביעית נוטלין שכרן מתרומת הלשכה,\u0004 ללמד כי העומר בא מתבואת השביעית, אף שקדושה היא. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו על הנאמר בהיתר להשתמש בפירות שביעית \"והיתה שבת הארץ לכם לאכלה לך ולעבדך ולאמתך ולחיה אשר בארצך תהיה כל תבואתה לאכול\" (שם כה, ו), שההדגשה \u0003\"לאכלה\"\u0004 באה למעט — דווקא לאכילה הותרו פירות השביעית, \u0003ולא לשריפה,\u0004 והרי מעלים לשריפה על המזבח את קומץ העומר!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לרמי בר חמא בתשובה: והרי \u0003רחמנא אמר\u0004 \u0005[התורה אמרה]\u0006 \u0003לך\u0004 (כנגד טענתך זו) במצות העומר \u0003\"ולחם וקלי וכרמל לא תאכלו עד עצם היום הזה עד הביאכם את קרבן אלהיכם חוקת עולם לדורותיכם בכל מושבותיכם\" (ויקרא כג, יד), ובא הכתוב\u0004 \u0003\"לדרתיכם\"\u0004 להורות כי נוהגת מצות העומר בכל הזמנים, ואף בשנת השמיטה, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 כי \u0003תיבטל\u0004 ההקרבה, משום שאין לשרוף פירות שביעית!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רמי בר חמא לרב חסדא בתשובה: \u0003ומי קאמינא אנא\u0004 \u0005[והאם אומר אני]\u0006 בשאלתי זו ש\u0003תיבטל\u0004 הבאת העומר?! והרי יש דרך אחרת לקיומה של מצוה זו, ובלא שיישרפו פירות שביעית — \u0003לייתי\u0004 \u0005[שיביא]\u0006 לעומר \u0003מ\u0004תבואות \u0003דאשתקד\u0004 \u0005[של השנה שעברה],\u0006 שאין בהם קדושת שביעית! דחה רב חסדא את דבריו: אין זו דרך ראויה להבאת העומר, שהרי \u0003בעינא\u0004 \u0005[צריך]\u0006 שיתקיים בעומר הנאמר בו \u0003\"כרמל\",\u0004 שתהיה התבואה רכה ומלאה, \u0003ו\u0004אילו בתבואות שנה שעברה \u0003ליכא\u0004 \u0005[אין כאן]\u0006 דבר זה.","חזר רמי בר חמא והקשה: \u0003ו\u0004עדיין \u0003לייתי\u0004 \u0005[שיביא]\u0006 \u0003מ\u0004תבואה שהיתה \u0003כרמל\u0004 בשעת הקצירה \u0003דאשתקד\u0004 \u0005[של השנה שעברה]!\u0006 דחה דבריו רב חסדא: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 במצות העומר \"ואם תקריב מנחת בכורים לה' אביב קלוי באש גרש כרמל תקריב את מנחת בכוריך\" (שם ב, יד), והרי הלשון \u0003\"כרמל תקריב\"\u0004 מורה כי \u0003בעינא\u0004 \u0005[צריך]\u0006 שיהיה העומר \u0003כרמל בשעת הקרבה,\u0004 \u0003ו\u0004אילו בתבואות שנה שעברה \u0003ליכא\u0004 \u0005[אין כאן]\u0006 כרמל בשעת הקרבה.","למדנו למעלה כי בשנה השביעית אין להביא את העומר מפירות השנה שעברה. ובענין זה \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים במקור הדברים. \u0003ר' יוחנן אומר\u0004 כי דין זה נלמד מן האמור בעומר \u0003\"כרמל תקריב\",\u0004 ופירות השנה שעברה אינם בכלל זה. ואילו \u0003ר' אלעזר אומר\u0004 כי נלמד הדין מן האמור בעומר שהוא \u0003ראשית קצירך\u0004 (\"ראשית קצירכם\"), והרי זה בא לומר כי יש להביא את העומר דווקא מן התבואה שהיא \u0003ראשית קצירך\u0004 (של שנה זו), \u0003ולא\u0004 מן התבואה שהיא \u0003סוף קצירך\u0004 (של השנה שעברה).","\u0003מותיב\u0004 \u0005[מקשה]\u0006 \u0003רבה\u0004 על הסברו של ר' יוחנן ממה ששנינו בברייתא: מה שנאמר \u0003\"ואם תקריב מנחת בכורים\u0004 לה' אביב קלוי באש גרש כרמל תקריב את מנחת בכוריך\" (שם) — \u0003במנחת העומר\u0004 הבאה בפסח \u0003הכתוב מדבר.\u0004 ו\u0003מהיכן,\u0004 מאיזה מין ממיני הדגן \u0003היא באה\u0004 מנחה זו? \u0003מן השעורים.\u0004 ודנים בדבר: \u0003אתה אומר\u0004 שמנחת העומר באה \u0003מן השעורים, או אינו אלא\u0004 היא באה \u0003מן החיטין?\u0004","\u0003ר' אליעזר אומר:\u0004 אין לומר כך, שכן מגזירה שווה אנו נלמדים שהיא באה מן השעורים דווקא. שהרי \u0003נאמר\u0004 הלשון \u0003\"אביב\" ב\u0004מכות \u0003מצרים,\u0004 במכת ברד (\"...והשעורה נוכתה כי השעורה אביב\". שמות ט, לא). \u0003ו\u0004כן \u0003נאמר\u0004 הלשון \u0003\"אביב\"\u0004 בציווי הנאמר \u0003לדורות\u0004 (בהבאת מנחת ביכורים, \"אביב קלוי באש\"). ומעתה נקיש ונאמר: \u0003מה \"אביב\" האמור במצרים\u0004 — הריהו \u0003שעורים\u0004 דווקא ולא חיטים (שכן נאמר במכת ברד, בפסוק שלאחר מכן, \"והחטה והכוסמת לא נוכו כי אפילות הנה\". שם לב). \u0003אף \"אביב\" האמור לדורות\u0004 — \u0003אינו בא אלא מן השעורים.\u0004","\u0003ר' עקיבא אומר\u0004 ראיה אחרת, שכן \u0003מצינו\u0004 (מוצאים אנו) בדינו של \u0003יחיד\u0004 מישראל \u0003ש\u0004הוא \u0003מביא חובתו\u0004 למנחה (כשחטא העני ומביא \"מנחת חוטא\") \u0003מן החיטין\u0004 (ככתוב בו \"עשירית האיפה סולת\". שם ה, יא) \u0003ו\u0004הריהו \u0003מביא\u0004 גם מנחה \u0003ל\u0004\u0003חובתו מן השעורין\u0004 (במנחת הסוטה, ככתוב בה \"עשירית האיפה קמח שעורים\". במדבר ה, טו). \u0003ו\u0004כן מוצאים אנו \u0003אף\u0004 ב\u0003ציבור שמביא\u0004 מנחת \u0003חובתו מן החיטין\u0004 (בשתי הלחם הקרב בעצרת. ומעתה נקיש: מה יחיד מביא מנחת חובתו מן השעורים וכן מן החיטים — \u0003ו\u0004אף ציבור הריהו \u0003מביא חובתו מן השעורין\u0004 ומן החיטים. \u0003אם אתה אומר\u0004 שמנחת ביכורים (שהיא מנחת חובה של ציבור) באה דווקא \u0003מן החיטין\u0004 — אם כן \u0003לא מצינו ציבור שמביא\u0004 מנחת \u0003חובתו מן השעורין!\u0004 ומכאן ראיה שמנחת העומר הריהי באה מהשעורים.","ועוד \u0003אמר ר' עקיבא\u0004 \u0003דבר אחר\u0004 (אופן נוסף) להוכיח כי מנחת העומר באה מהשעורים: שכן \u0003אם אתה אומר\u0004 שה\u0003עומר בא מן החיטין\u0004 — אם כן מעתה \u0003אין שתי הלחם\u0004 הבאים בחג השבועות מן החיטים נקראים \u0003\"ביכורים\",\u0004 שהרי קדמם העומר, והרי אמרה תורה בחג השבועות \"וביום הביכורים בהקריבכם מנחה חדשה לה' בשבועותיכם\" (במדבר כח, כו). \u0003אלמא\u0004 \u0005[מכאן]\u0006 ששתי הלחם \u0003משום ביכורים הוא,\u0004 וכן העומר, שאף בו נאמר \"בכורים\". והרי זה כהסברו של ר' אליעזר, ושלא כהסברו של ר' יוחנן! ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא.","ומביאים עוד בדין הבאת שתי הלחם. \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003אין מביאין ביכורים\u0004 מכל הפירות \u0003חוץ משבעת המינין\u0004 שהשתבחה בהם ארץ ישראל (\"ארץ חטה ושעורה וגפן ותאנה ורמון \u0003ארץ זית שמן ודבש\". דברים ח, ח),\u0004 \u0003ולא\u0004"],["\u0003מ\u0004פירות עצי ה\u0003תמרים ש\u0004גדלים \u0003בהרים, ולא מ\u0004שאר ה\u0003פירות\u0004 של שבעת המינים \u0003ש\u0004גדלים \u0003בעמקים,\u0004 לפי שפירות אלה הריהם גרועים, ואילו בביכורים יש להביא מן המובחר שבפירות. ו\u0003אמר עולא\u0004 בהסברה של הלכה זו, שאין היא רק לכתחילה, שכך ראוי לנהוג, אלא הריהי נוהגת אף בדיעבד, ולכך \u0003אם\u0004 עבר ו\u0003הביא\u0004 מתמרים שבהרים או מפירות שבעמקים — \u0003לא קידש\u0004 (לא חלה עליהם קדושת ביכורים, והריהם כחולין).","ונמסר כי \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רבה וקא אמר לה להא שמעתא\u0004 \u0005[ואמר אותה, את ההלכה הזו]\u0006 שאמר עולא, שהמביא מתמרים שבהרים — לא קידש. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' אחא בר אבא לרבה\u0004 על הלכה זו, ממה ששנינו בברייתא על הנאמר \"...כי כל שאור וכל דבש לא תקריבו ממנו אשה לה'. קרבן ראשית \u0003תקריבו אותם לה' ואל המזבח לא יעלו לריח ניחוח\" (ויקרא ב, יא—יב). והרי שתי הכלל בכלל כתוב זה, שכן נאמר בו\u0004 \u0003\"קרבן ראשית\"\u0004 — והרי זה בא ללמד על מנחת שתי הלחם הבאה בחג השבועות, \u0003שתהא ראשית\u0004 (ראשונה) \u0003לכל המנחות\u0004 הבאות מן התבואה החדשה של שנה זו. \u0003ו\u0004ראיה לדבר, שכך הוא דינם של שתי הלחם, ש\u0003כן הוא\u0004 הכתוב \u0003אומר\u0004 בהם: \"וביום הביכורים \u0003בהקריבכם מנחה חדשה לה' בשבעתיכם...\"\u0004(במדבר כח, כו) — שהריהי המנחה הראשונה (\"מנחה חדשה\") המובאת מהתבואה החדשה, הקודמת לכל שאר המנחות.","וממשיכים לדון בדינם של שתי הלחם: ואולם עדיין \u0003אין לי\u0004 שכך היא דינה של מנחה זו, \u0003אלא\u0004 שהיא \u0003חדשה\u0004 לכל המנחות הבאות מתבואה \u0003של חטים,\u0004 שהרי אף שתי הלחם באים מן החיטים. ואילו באשר לכך שהריהי אף המנחה ה\u0003חדשה\u0004 (הראשונה להקרבה בשנה זו) למנחות הבאות מתבואה \u0003של שעורים\u0004 (כמנחתה של הסוטה, \"מנחת קנאות\") \u0003מנין\u0004 לי? לכך \u0003תלמוד לומר\u0004 (מלמד האמור) בתורה שתי פעמים, \u0003\"חדשה\"\u0004 בענינם של שתי הלחם. שכך נאמר בכתוב זה שבספר במדבר, וכן נאמרה לשון זו \u0003\"חדשה\"\u0004 בעניינם של שתי הלחם במקרא אחר \u0003(\"עד ממחרת השבת השביעית תספרו חמישים יום והקרבתם מנחה חדשה לה' \". ויקרא כג, טז). ומעתה יש לומר בכתוב נוסף זה:\u0004 \u0003אם אינו ענין ל\u0004למדנו שמנחת שתי הלחם הריהי המנחה ה\u0003חדשה\u0004 הקודמת לכל המנחות הבאות מתבואה \u0003של חיטין,\u0004 שהרי כבר למדנו זאת — \u0003תנהו ענין ל\u0004למדנו שמנחת שתי הלחם הריהי המנחה ה\u0003חדשה\u0004 הקודמת אף לכל המנחות הבאות מתבואה \u0003של שעורים.\u0004","וממשיכים ודנים: \u0003ומנין\u0004 לי \u0003שתהא\u0004 הבאת מנחת העומר \u0003קודמת\u0004 אף \u0003ל\u0004הבאת ה\u0003ביכורים?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) \u0003\"וחג שבעת תעשה לך בכורי קציר חטים\"\u0004 (שמות לד, כב) — ללמדנו כי בתחילה מביאים את המנחה המצווה להיות מובאת בחג השבועות, היא מנחת שתי הלחם (\"וחג שבועות תעשה לך\"), ולאחר מכן אף מביאים מן הביכורים. וממשיכים ודנים: \u0003ו\u0004עדיין \u0003אין לי\u0004 שכך הוא דינם של שתי הלחם \u0003אלא\u0004 שהם קודמים בהבאה להבאתם של \u0003בכורי קציר חטים,\u0004 ואולם שקודמים הם בהבאה אף להבאתם של ביכורי \u0003קציר שעורים מנין\u0004 לי? לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) עוד בחג השבועות \u0003\"וחג הקציר בכורי מעשיך אשר תזרע בשדה\"\u0004 (שם כג, טז) — ללמדנו כי המצוה הנוהגת בחג השבועות מקציר החיטים, היא מנחת שתי העומר, הריהי מובאת בתחילה, ולאחר מכן מביאים להבאת שאר הביכורים (\"אשר תזרע בשדה\").","וממשיכים ודנים: \u0003ו\u0004עדיין \u0003אין לי\u0004 מתוך לימוד זה \u0003אלא\u0004 שקודמת מנחת שתי הלחם בהבאתה דווקא לביכורים הבאים מן הפירות \u0003שתזרע\u0004 אתה (כנאמר בכתוב \"אשר תזרע\"), ואולם שקודמת היא בהבאתה אף לביכורים הבאים מן הפירות ש\u0003עלו מאליהן מנין\u0004 לנו? לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) בכתוב זה \u0003\"בשדה\"\u0004 — ללמדנו כי קודמים שתי הלחם בהבאתם אף לביכורים הבאים מן השדה, שעלו מאליהם.","וממשיכים ודנים: \u0003ו\u0004עדיין \u0003אין לי אלא\u0004 שקודמים שתי הלחם בהבאתם לביכורים הבאים מפירות שגדלו מאליהם \u0003בשדה, מנין\u0004 לי שיש \u0003לרבות\u0004 לענין זה אף את הביכורים הבאים \u0003מפירות\u0004 \u0003ש\u0004גדלו \u0003בגג\u0004 הבית \u0003ו\u0004כן את אלה \u0003ש\u0004גדלו \u0003בחורבה, ו\u0004כן את אלה \u0003ש\u0004גדלו \u0003בעציץ, וש\u0004גדלו \u0003בספינה?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) בפרשת המתנות הניתנות לכהנים (ובכללן הביכורים) \u0003\"בכורי כל אשר בארצם\u0004 אשר יביאו לה' לך יהיה...\" (במדבר יח, יג). וכן נאמר בשתי הלחם \"וחג הקציר בכורי קציר חטים\" — ללמדנו כשם ש\"בכורי\" האמורים כאן הריהם כוללים הכל (כנאמר בהם \"בכורי כל אשר בארצם\"), אף \"בכורי\" האמור בשתי הלחם הריהו מתייחס לכול, ולהורות שקודמת מנחת שתי הלחם לכל סוגי הביכורים המובאים, שאין הם באים מן התבואה החדשה אלא לאחר שהובאה קודם מנחת שתי הלחם.","וממשיכים ודנים: \u0003מנין\u0004 לי \u0003שתהא\u0004 מנחת שתי הלחם \u0003קודמת\u0004 בהבאה מן התבואה החדשה אף \u0003לנסכים\u0004 של יין ושל שמן, \u0003ו\u0004לביכורים הבאים מ\u0003פירות האילן?\u0004 ומשיבים: \u0003נאמר כאן\u0004 (בשתי הלחם) \"וחג הקציר \u0003בכורי מעשיך\u0004 אשר תזרע בשדה\", \u0003ונאמר להלן\u0004 (אחרי כן) בהמשכו של אותו כתוב \u0003\"באספך את מעשיך מן השדה\"\u0004 — ללמדנו: \u0003מה להלן\u0004 הכתוב כולל במשמעו אף \u0003נסכים ופירות אילן\u0004 (שכן נאמר בו \"מעשיך\" — כל המעשים הנעשים על ידך), \u0003אף\u0004 הכתוב \"מעשיך\" האמור \u0003כאן\u0004 בדין חג השבועות, בהבאת שתי הלחם מן התבואה החדשה הקודמת להבאת שאר דברים מן התבואה החדשה, ואף ל\u0003נסכים ו\u0004ל\u0003פירות אילן.\u0004","ולאחר שהביא ר' אחא בר אבא את דברי הברייתא במילואה, נפנה להקשות על הלכה זו של עולא שבפי רבה: \u0003קתני מיהא\u0004 \u0005[שנה\u0006 התנא בברייתא זו \u0005על כל פנים]:\u0006 שקודמים שתי הלחם בהבאה מן התבואה החדשה להבאתם של הביכורים, ואף אלה הבאים מן הפירות \u0003שבגג שבחורבה שבעציץ ושבספינה,\u0004 הרי משמע שמביאים ביכורים מכל סוגי הפירות, ואף מן התמרים שבהרים ומן הפירות שבעמקים, והרי זה שלא כדברי עולא! השיב לו רבה: מה ששנינו ב\u0003סיפא\u0004 \u0005[סוף\u0006 הברייתא\u0005]\u0006 ששתי הלחם קודמים בהבאה לפירות הגדלים בגג \u0003ובחורבה ובעציץ ובספינה, אין הברייתא עוסקת עוד בפירות הבאים לביכורים, אלא בדברים אלה\u0004 \u0003אתאן\u0004 \u0005[באנו,\u0006 נפנים לדון\u0005]\u0006 בפירות אלה המובאים \u0003ל\u0004שאר \u0003מנחות,\u0004 ובאה הברייתא ללמדנו כי הבאת שתי הלחם מהתבואה החדשה קודמת להבאת שאר מנחות הבאות אף מפירות שכאלה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך,\u0006 על תירוץ זה של רבה\u0005]\u0006 \u0003רב אדא בר אהבה: אי הכי\u0004 \u0005[אם כך]\u0006 הוא פירוש הברייתא, ומה ששנינו בה שמהפסוק \"בכורי כל אשר בארצם אשר יביאו לה' לך יהיה\" אנו למדים דין הקדמת \u0005שתי הלחם בהבאה לפני הבאתם של שאר מנחות, מהפירות הללו שגדלו בגג ובחורבה בעציץ ובספינה, הרי מוקשה מעתה\u0006 \u0003היינו דכתיב\u0004 \u0005[זה שנאמר]\u0006 בהמשכו של אותו פסוק \u0003\"כל טהור בביתך (יאכל אותו) [יאכלנו]\",\u0004 ומובן הלשון \"כל טהור בביתך\" הריהו: כל בני ביתו של הכהן, ואף הנשים שבביתו ואף עבדים, \u0003ו\u0004אולם \u0003אי\u0004 \u0005[אם]\u0006 אתה אומר שמדובר בפסוק זה ב\u0003מנחות,\u0004 הלוא המנחות רק \u0003לזכרי כהונה הוא דמיתאכלן\u0004 \u0005[שנאכלות]\u0006 ולא לאחרים!","\u0003אמר רב משרשיא\u0004 בתירוץ שאלתו של רב אדא בר אהבה: פסוק זה הריהו נחלק לשנים, והרי זה כעין \u0003תרי קראי כתיבי\u0004 \u0005[שני מקראות כתובים].\u0006 וראיה לדבר, שהרי יש בפסוק זה כעין סתירה, שכן בכתוב אחד נאמר \"בכורי כל אשר בארצם אשר יביאו לה' \u0003לך יהיה\"\u0004 — בזכרי כהונה עוסק הפסוק, שרק הכהן (ובניו הכהנים) אוכלים במתנת כהונה זו, \u0003ו\u0004אילו בהמשך הפסוק \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"כל טהור בביתך יאכל אתו\"\u0004 — במתנות כהונה שאוכלים בהן כל בני ביתו של הכהן, ואף נשים ועבדים, עוסק הפסוק. \u0003הא\u0004 \u0005[הרי]\u0006 מעתה \u0003כיצד\u0004 ניישב סתירה זו? שני מקראות חלוקים יש לפנינו בפסוק זה, \u0003כאן,\u0004 בכתוב האומר \"כל טהור בביתך יאכל אותו\" — עוסק הכתוב \u0003בביכורים\u0004 הנאכלים לכל. ואילו \u0003כאן,\u0004 בכתוב האומר \"לך יהיה\" — עוסק הכתוב \u0003במנחות.\u0004 ואין איפוא מקום לשאלתו של רב אדא בר אהבה.","\u0003רב אשי אמר\u0004 הסבר אחר המשיב על קושיותיהם של ר' אחא בר אבא ושל רב אדא בר אהבה, ושלא כהסברו של רב משרשיא: אין הפסוק נחלק לשני מקראות, והריהו \u0003כוליה\u0004 \u0005[כולו]\u0006 עוסק בענין אחד, \u0003במנחות, ו\u0004אולם באשר לשאלה הנוגעת ל\u0003סיפא דקרא\u0004 \u0005[סוף הפסוק]\u0006 שבו נאמר \"כל טהור בביתך יאכל אותו\", והרי אין המנחות נאכלות לכל בני ביתו של הכהן? יש לומר כי בחלק זה של הפסוק \u0003אתאן\u0004 \u0005[באנו,\u0006 עוסקים אנו\u0005]\u0006 \u0003ל\u0004סוג מסויים של מנחות, \u0003לחמי תודה,\u0004 שאלה נאכלים על ידי כל בני ביתו של הכהן.","לאחר שנידונה שיטת עולא, הסבור שלא חלה קדושת ביכורים על הביכורים הבאים מתמרים שבהרים ומפירות שבעמקים, ומחלוקתו של רב אחא בר אבא על שיטת עולא. מביאים עוד בענין זה, ומציינים כי הריהם חלוקים \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 אמוראים ראשונים. שכן \u0003ר' יוחנן אמר: אם הביא\u0004 לביכורים מן התמרים שבהרים ומן הפירות שבעמקים — \u0003לא קדש\u0004 הפרי בקדושת ביכורים. ואילו \u0003ריש לקיש אמר: אם הביא\u0004 מפרי שכזה לביכורים — \u0003קדש\u0004 הפרי, וטעמו: \u0003נעשה\u0004 (נחשב) פרי זה \u0003כ\u0004קרבן \u0003כחוש בקדשים,\u0004 שאף שהוא כחוש ואין הנכון לכתחילה להביאו \u0003לקרבן, מכל מקום הריהו מתקדש בקדושת הקרבן.\u0004","ודנים במחלוקתם: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שיטת \u0003ריש לקיש\u0004 הסבורה שקדש הפרי, הריהי מוסברת, ו\u0003כ\u0004דרך שריש לקיש עצמו \u0003אמר טעמא\u0004 \u0005[טעם]\u0006 שיטתו. \u0003אלא ר' יוחנן, מאי טעמא\u0004 \u0005[מה טעם]\u0006 שיטתו, שאין הפרי מתקדש בקדושת הביכורים, ובמה השתנה דין הפרי הגרוע לענין ביכורים מדין הקרבן הכחוש לענין קרבנות? \u0003אמר ר' אלעזר:\u0004 את \u0003ר' יוחנן חזאי\u0004 \u0005[ראיתי]\u0006 \u0003בחלום,\u0004 וידעתי מתוך כך \u0003כי\u0004 \u0003מילתא מעלייתא אמינא\u0004 \u0005[דבר משובח אני אומר]\u0006 בבית המדרש, והרי דבר זה המסביר את שיטתו של ר' יוחנן: בפרשת הביכורים \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"ולקחת מראשית כל פרי האדמה אשר תביא מארצך אשר ה' אלהיך נותן לך...\" (דברים כו, ב), ובא הנאמר \u0003\"מראשית\"\u0004 בלשון מיעוט — לומר: מראשיתם של חלק מהפירות (משבעת המינים שהשתבחה בהם הארץ) מביאים ביכורים, \u0003ולא\u0004 מביאים ביכורים מ\u0003כל ראשית\u0004 פירות האדמה. ועוד נאמר בכתוב בלשון מיעוט \u0003\"מארצך\"\u0004 — לומר: מחלקים מסויימים בארץ (מההרים — פירות, ומהעמקים — תמרים) מביאים ביכורים, \u0003ולא\u0004 מביאים ביכורים מ\u0003כל ארצך.\u0004 ונמצא איפוא כי לימוד מיוחד הוא המלמדנו שאין חלה קדושת ביכורים על התמרים שבהרים ופירות שבעמקים.","ושואלים: \u0003וריש לקיש האי\u0004 \u0005[זה]\u0006 הכתוב \"מ \u0003ארצך\" מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה,\u0006 לומד \u0005בו]?\u0006 ומשיבים: ריש לקיש סבור כי מן המלה \u0003\"מראשית\" כשלעצמה אין אנו יודעים עדיין כי רק משבעת המינים מביאים ביכורים, ולכך\u0004 \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 הכתוב \"מארצך\" ללמדנו שרק משבעת המינים שהשתבחה בהם הארץ מביאים ביכורים. והרי זה \u0003לכדתניא\u0004 \u0005[לכמו ש\u0006היא \u0005שנויה\u0006 בברייתא\u0005].\u0006 שכך שנינו, \u0003רבן גמליאל בר רבי אומר: נאמר כאן\u0004 (בפרשת הביכורים) הלשון \u0003\"ארץ\"\u0004 (\"מארצך\"), \u0003ו\u0004כן \u0003נאמר להלן\u0004 (שם בספר דברים, בדברי משה בשבח \u0003ארץ ישראל ופירותיה)\u0004 \u0003\"ארץ\"\u0004 (\"ארץ חטה ושעורה וגפן ותאנה ורמון ארץ זית שמן ודבש\". שם ח, ט). ומעתה נאמר: \u0003מה להלן\u0004 בדברי משה — הרי אלה שבעת הפירות שיש בהם \u0003שבח ארץ, אף כאן\u0004 בפרשת הביכורים — הרי אלה שבעת הפירות שיש בהם \u0003שבח ארץ.\u0004","ושואלים עתה: \u0003ואידך\u0004 \u0005[והאחר],\u0006 ר' יוחנן, שלמד את דינו בענין תמרים שבהרים ופירות שבעמקים מן הכתוב \"מארצך\", יש להקשות עליו, שהרי נדרש כתוב זה לענין ההיקש \"ארץ\" ארץ\" המלמד כי בפירות שהשתבחה בהם הארץ מביאים דווקא ביכורים? ומשיבים: ר' יוחנן לומד היקש זה על סמך המלים \u0003\"ארץ\"\u0004 (\"ארץ חטה...\") \u0003\"מארץ\"\u0004 (שבכלל המלה \"מארצך\"), ומכינוי השייכות \"מארצך\" הריהו למד את דינו בענין תמרים שבהרים ופירות שבעמקים. ושואלים לצד האחר: \u0003ואידך\u0004 \u0005[והאחר],\u0006 ריש לקיש מדוע אף הוא איננו למד שני דברים מן המלה \"מארצך\" כדרך שלמד ר' יוחנן?","ומשיבים: לצורך ההיקש \"ארץ\" \"ארץ\" נצרכים אנו לכל המלה \"מארצך\", שכן דרך הלימוד (שהציע \u0003ר' יוחנן)\u0004 \u0003\"ארץ\" \"מארץ\" לא משמע ליה\u0004 \u0005[לא משמע,\u0006 נראית \u0005לו].\u0006","ודנים עוד במחלוקתם של ר' יוחנן וריש לקיש. \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]\u0006 בדינם של הפירות \u0003ש\u0004גדלו \u0003בגג ושבחורבה שבעציץ ושבספינה\u0004 לענין הביכורים — הריהם חייבים בשתי מצוות הביכורים, והבעלים \u0003מביא\u0004 מהם ביכורים למקדש, \u0003ו\u0004אף \u0003קורא\u0004 את פרשת הביכורים. \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0003אחרת]\u0004 בדינם של פירות אלה לענין הביכורים — \u0003מביא\u0004 מהם למקדש \u0003ו\u0004אולם \u0003אינו קורא\u0004 פרשת ביכורים עליהם.","ויש לדון בברייתות אלה וליישבן באופן שלא תסתורנה זו את זו: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003ריש לקיש\u0004 הסבור שהמביא ביכורים מפירות שבעמקים ומתמרים שבהרים, קדשו הביכורים, ניתן ליישב יפה את הסתירות שבין הברייתות. שכן הסתירה מהברייתא בה נאמר שפירות שגדלו ב\u0003גג\u0004 מביאים מהם ביכורים וקוראים על הברייתא בה נאמר שפירות שגדלו ב\u0003גג\u0004 מביאים מהם ביכורים אך לא קוראים עליהם — \u0003לא קשיא\u0004 \u0005[לא קשה].\u0006 שכן יש לומר: \u0003הא\u0004 \u0005[זה]\u0006 ששנינו מביאים וקוראים — מדובר \u0003ב\u0004פירות שגדלו על \u0003גג\u0004 של \u0003מערה,\u0004 הנחשב כקרקע, ולכך מביאים מהם וקוראים. ואילו \u0003הא\u0004 \u0005[זה]\u0006 ששנינו מביאים ואין קוראים — מדובר \u0003ב\u0004פירות שגדלו על \u0003גג\u0004 של \u0003בית.\u0004","וכן הסתירה מפירות שגדלו ב\u0003חורבה\u0004 על פירות שגדלו \u0003ב\u0004\u0003חורבה\u0004 — אף היא \u0003לא קשיא\u0004 \u0005[לא קשה].\u0006 שכן יש לומר: \u0003כאן\u0004 בברייתא ששנינו בה שמביאים וקוראים — מדובר בפירות שגדלו \u0003בחורבה עבודה\u0004 (מעובדת), שטרח בה והרי היא בכלל \"מארצך\". ואילו \u0003כאן\u0004 בברייתא ששנינו בה שמביאים אך לא קוראים — מדובר בפירות שגדלו \u0003בחורבה שאינה עבודה.\u0004","וכן הסתירה מפירות שגדלו ב\u0003עציץ\u0004 על פירות שגדלו ב\u0003עציץ\u0004 — אף היא \u0003לא קשיא\u0004 \u0005[לא קשה].\u0006 שכן יש לומר: \u0003כאן\u0004 בברייתא ששנינו בה שמביאים וקוראים — מדובר \u0003בפירות שגדלו\u0004 \u0003ב\u0004עציץ \u0003נקובה,\u0004 ואילו \u0003כאן\u0004 בברייתא ששנינו בה שמביאים אך לא קוראים — מדובר בפירות שגדלו \u0003ב\u0004עציץ \u0003שאינו נקובה.\u0004","וכן הסתירה מפירות שגדלו ב\u0003ספינה\u0004 על פירות שגדלו ב\u0003ספינה\u0004 — אף היא \u0003לא קשיא\u0004 \u0005[לא קשה].\u0006 שכן יש לומר: \u0003כאן\u0004 בברייתא ששנינו בה שמביאים וקוראים — מדובר בפירות שגדלו \u0003בספינה של עץ.\u0004 ואילו \u0003כאן\u0004 בברייתא ששנינו בה שמביאים ואין קוראים — \u0003מדובר בפירות שגדלו\u0004 \u0003בספינה של חרס.\u0004"],["\u0003אלא לר' יוחנן\u0004 הסבור שאם הביא מפירות שבעמקים ומתמרים שבהרים לא התקדשו הפירות בקדושת ביכורים, \u0003קשיא\u0004 \u0005[קשה]\u0006 ממה ששנינו בברייתא כי מביאים ביכורים מן הפירות הגדלים בעציץ ובספינה — הרי שהתקדשו בקדושת ביכורים, והלא אין הם טובים יותר מתמרים שבהרים או מפירות שבעמקים!","ומשיבים: אין ברייתא זו קשה לר' יוחנן, שכן מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא\u0004 אם חלה קדושת ביכורים על הפירות הגדלים בעציץ ובספינה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא אחרת\u0003]:\u0004 פירות \u0003ש\u0004גדלו \u0003בגג וש\u0004גדלו \u0003בחורבה\u0004 — \u0003מביא\u0004 מהם ביכורים \u0003וקורא\u0004 עליהם פרשת ביכורים, ואולם פירות \u0003ש\u0004גדלו \u0003בעציץ וש\u0004גדלו \u0003בספינה\u0004 — לא חלה עליהם כלל קדושת ביכורים ולכך הבעלים \u0003אינו מביא\u0004 מהם \u0003כל עיקר.\u0004 ור' יוחנן סבור כשיטתו של תנא זה.","\u0003ו\u0004עוד שנינו במשנתנו כי המנחות \u0003כולן אינן באות אלא מן\u0004 הסולת \u0003המובחר,\u0004 ואיזהו הסולת המובחר? — זה הבא מהמקומות מכניס וזטחא, ושני להם הוא הסולת הבא מן המקום הנקרא עפוריים בבקעה. ומתוך שמשובחות ומרובות הן תבואות מקום זה, היה הוא לסמל של מקום המשופע בתבואה ברוכה, וכך אף נטבע בניבי שפת העם. וכדרך המסופר במשה רבינו בזמן שעמדו הוא ואהרן לפני פרעה מלך מצרים, והשליך אהרן את המטה שבידו והיה לתנין. ולאחר מכן, לכשעשו חרטומי מצרים בלהטיהם גם כן כדבר הזה והיו מקלותיהם לתנינים, בלע מטה אהרן את מטותם (שמות ז׳:י״ב, י_יב), באותה שעה \u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 \u0003יוחנא וממרא,\u0004 שהיו מראשי \u0005החרטומים של פרעה,\u0006 \u0003למשה\u0004 כפתגם המקובל: \u0003תבן\u0004 (שהוא דבר קל וחסר ערך) \u0003אתה מכניס לעפריים\u0004 (מקום התבואות המשובחות)? וכרוצים לומר לו: וכי למצרים, שהיא ארץ מלאה כשפים, אתה מביא דבר כישוף שכזה. \u0003אמר להו\u0004 \u0005[להם]\u0006 משה בתשובה, שאף היא מיוסדת על פתגם הרווח בעם: כך \u0003אמרי אינשי\u0004 \u0005[אומרים האנשים],\u0006 \u0003למתא ירקא, ירקא שקול\u0004 \u0005[\u0006אם \u0005לעיר\u0006 יש \u0005ירק, הבא\u0006 \u0005ירק\u0006 למכור\u0005],\u0006 שכן במקום זה יימכר הירק היטב. ובדומה לכך, דווקא במצרים מקום הכשפים, ראוי לעשות כן.","אף מהמקומות (שנמנו במשנה הקודמת, פג,ב) בהם הסולת משובחת, \u0003אין מביאין\u0004 סולת \u0003לא מ\u0004התבואה הגדלה ב\u0003בית הזבלים\u0004 (שדה הזקוקה לזיבול כדי שתתן פירותיה כראוי) \u0003ולא מבית השלחים\u0004 (שדה הזקוקה להשקיה בידי אדם, שאין די לה במי הגשמים) \u0003ולא מבית האילן\u0004 (שדה שמצויים בה אילנות, ונמצאים האילנות מכחישים את כוחה של אדמת השדה). שכל אלה, פירותיהם אינם משובחים. \u0003ו\u0004אולם \u0003אם הביא\u0004 מהם — \u0003כשר.\u0004","ומסבירים: \u0003כיצד הוא\u0004 (בעלי השדה) \u0003עושה\u0004 בעבודת שדהו, כדי שתניב שדהו סולת המשובחת ביותר? הריהו \u0003נרה\u0004 (חורש אותה) בלבד, \u0003ב\u0004\u0003שנה\u0004 ה\u0003ראשונה,\u0004 ואין הוא זורע בה דבר. \u0003ובשנה שניה\u0004 (הבאה) הריהו \u0003זורעה\u0004 בזמן הזריעה הנכון, שהוא \u0003קודם ל\u0004חג ה\u0003פסח שבעים יום, ו\u0004בכך הרי \u0003הוא\u0004 מביא את השדה שתהא \u0003עושה סולת מרובה\u0004 ומשובחת.","ועוד מסבירים: \u0003כיצד בודק הגזבר\u0004 של בית המקדש את הסולת המובאת למנחות, אם אכן היא מנופה כל צורכה? — הריהו \u0003מכניס\u0004 את \u0003ידו לתוכן\u0004 פנימה, וחוזר ומעלה את ידו. אם נמצא \u0003ש\u0004\u0003עלה בה,\u0004 על ידו, \u0003אבק\u0004 (קמח דק וגרוע) — הרי זה מורה שלא נופתה הסולת כל הצורך, והריהי \u0003פסולה עד שינפנה\u0004 בנפה דקה, להסיר את האבק הדק שיש בה.","\u0003ואם\u0004 \u0003התליעה\u0004 (נמצאו תולעים בתוך הסולת) המובאת למקדש — הריהי \u0003פסולה\u0004 לשמש למנחה.","שנינו במשנתנו \u0003כיצד\u0004 בעלי השדה \u0003עושה\u0004 בעבודת שדהו, כדי שתניב שדהו סולת המשובחת ביותר? הריהו \u0003נרה\u0004 (חורש אותה) בלבד, \u0003ב\u0004\u0003שנה\u0004 ה\u0003ראשונה,\u0004 ואין הוא זורע בה דבר, ובשנה הבאה הריהו זורעה בזמן הזריעה הראוי. \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים השאלה: \u0003היכי קאמר\u0004 \u0005[כיצד הוא\u0006 התנא של משתננו \u0005אומר,\u0006 מה כוונת דבריו\u0005]?\u0006 האם כוונתו שהריהו \u0003נרה\u0004 ב\u0003שנה\u0004 ה\u0003ראשונה\u0004 בלא לזורעה, \u0003ו\u0004אילו בשנה \u0003השניה\u0004 הריהו \u0003נרה\u0004 שוב \u0003וזורעה.\u0004 \u0003או דלמא\u0004 \u0005[שמא]\u0006 כוונתו שהריהו \u0003נרה\u0004 ב\u0003שנה ראשונה\u0004 ואינו זורעה, \u0003ו\u0004אילו בשנה ה\u0003שניה\u0004 הריהו \u0003זורעה בלא\u0004 שהוא \u0003נרה\u0004 לפני כן?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה \u0003דתניא\u0004 \u0005[ששנויה\u0006 בריייתא\u0005],\u0006 \u0003אמר ר' יוסי:\u0004 כיון שהלכה היא שניתן להביא את העומר מכל איזורי ארץ ישראל, ראויות היו \u0003אף חיטי\u0004 (התבואות) הבאות מהיישובים הנקראים \u0003כרזיים וכפר אחים\u0004 להיות קרבות לעומר, שכן תבואות משובחות הן. ו\u0003אלמלא\u0004 (אילו) היו אלה מקומות \u0003ה\u0004\u0003סמוכות לירושלים, היו מביאין מהן\u0004 את העומר. שכן ראויות הן תבואות שדותיהם של המקומות הללו להיות מובאות לעומר, \u0003לפי שאין מביאין את העומר אלא מן השדות המודרמות\u0004 (הנמצאות בדרום), \u0003והמנונרות\u0004 (הנחרשות) \u0003לכך\u0004 (לשם העומר). \u0003שבהן,\u0004 בשדות הללו שבדרום, \u0003ה\u0004\u0003חמה זורחת\u0004 בתחילה, בשעה מוקדמת של היום ואף בימות החורף, ומבשילה כל היום את הצומח בהן, \u0003ומהן\u0004 (ומשם) ה\u0003חמה\u0004 מעריבה ו\u0003שוקעת\u0004 בסוף היום. והרי מזג אויר זה מועיל מאוד לתבואות.","ועוד בשבח תבואות השדות הללו, \u0003כיצד\u0004 בעלי שדה זה \u0003עושה\u0004 (נוהג בעבודת שדהו) כדי להשביח את תבואתה? \u0003הריהו\u0004 \u0003נרה\u0004 ב\u0003שנה\u0004 ה\u0003ראשונה\u0004 ואין הוא זורעה. \u0003ו\u0004בשנה ה\u0003שניה\u0004 הריהו \u0003חורש ושונה\u0004 (וחוזר וחורש), \u0003וזורעה\u0004 בזמן הראוי לזריעה שהוא \u0003קודם לפסח שבעים יום, כדי שתהא\u0004 הזריעה \u0003סמוכה\u0004 \u0003ל\u0004זמן התגברות כוחה של \u0003חמה. ו\u0004אכן כתוצאה ממיקום זה של השדות ומדרך העבודה הראויה בהן, \u0003עושה\u0004 (מצמיחה) השדה זן תבואה משובח ביותר, שבו אורכו של ה\u0003קנה\u0004 (גבעול) הוא כמידת \u0003זרת\u0004 בלבד, \u0003ו\u0004ראש ה\u0003שיבולת\u0004 אורכה הוא כ\u0003זרתיים. ו\u0004לאחר מכן בעלי השדה","\u0003קוצר\u0004 את התבואה, \u0003ומעמר\u0004 (כורך את השיבולים שנקצרו לכלל עומרים), \u0003ודש\u0004 (חובט את השבלים כדי להוציא מהן את גרעיניהן), \u0003וזורה\u0004 (מניף וזורק מעלה את התבואה כדי שהתבן והמוץ יינשאו על ידי הרוח וגרגרי התבואה ישובו ויפלו ארצה), \u0003ובורר\u0004 את הגרעינים הטובים לקמח, \u0003וטוחן\u0004 אותם לקמח, \u0003ומרקד\u0004 (מקפיץ ומניע מצד לצד את הקמח בנפה כדי לנפותו מאבק ולכלוך). \u0003ו\u0004אחר כל זאת הריהו \u0003מביא\u0004 את הקמח שעלה בידו מתבואה זו \u0003אצל\u0004 ה\u0003גזבר\u0004 שבמקדש. \u0003ו\u0004ה\u0003גזבר מכניס ידו לתוכה\u0004 כדי לבדוק את הקמח אם הוא מנופה כל צורכו. ושב ומעלה הגזבר את ידו, ו\u0003אם עלתה בה אבק\u0004 (קמח דק) — \u0003אומר לו\u0004 הגזבר לבעל השדה: \u0003חזור ונפה אותה\u0004 פעם \u0003שניה. משום\u0004 \u0005[בשם]\u0006 \u0003ר' נתן אמרו\u0004 חכמים בדרך בדיקת הקמח: ה\u0003גזבר\u0004 היה בתחילה \u0003סך ידו\u0004 ב\u0003שמן\u0004 (בו נדבקים אף הדברים היותר דקים), \u0003ו\u0004לאחר מכן היה \u0003מכניס\u0004 את ידו \u0003לתוכה\u0004 של ערימת הקמח שהובאה לפניו לבדיקה, \u0003עד שמעלה\u0004 ידו \u0003כל אבקה\u0004 של הקמח, ובאופן זה היא הבדיקה היותר מדוקדקת.","ולאחר שהובאה הברייתא בכל פרטיה, מנסים להוכיח ממנה לשאלה שנשאלה: \u0003קתני מיהת\u0004 \u0005[שנה\u0006 התנא \u0005על כל פנים]\u0006 בתוך דבריו כי בשנה השניה בעלי השדה \u0003חורש ושונה.\u0004 הרי שכך היא הדרך הנכונה, ולזאת גם כיוונה משנתנו.","ודוחים את הראיה: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שיש להוכיח מדברי ברייתא זו לשיטת משנתנו, ואולם הרי \u0003מתניתין לא קתני\u0004 \u0005[\u0006ב\u0005משנתנו\u0006 התנא \u0005אין הוא שונה],\u0006 בעניינה של השנה השניה את הלשון \"חורש \u0003ו\u0004\u0003שונה\",\u0004"],["בעוד שהתנא שב\u0003ברייתא קתני\u0004 \u0005[הוא שונה]\u0006 את הביטוי \"חורש ו\u0003שונה\",\u0004 וללמד שבשנה השניה חורשים שתי פעמים, והרי אף אם נכריע כי כוונת דברי משנתנו היא שחורשים וזורעים בשנה השניה, ואולם אין חורשים בה אלא פעם אחת, ולא שתי פעמים. ונמצא איפוא שחלוקות הן משנתנו והברייתא, ומשום כך אין להביא ראיה מהברייתא להבנת דברי משנתנו.","ומשיבים: \u0003הא לא קשיא\u0004 \u0005[\u0006שאלה \u0005זו לא קשה],\u0006 ואפשר לומר ש\u0005משנתנו והברייתא מדברות בסוגי שדה שונים:\u0006 \u0003כאן\u0004 במשנתנו מדובר \u0003ב\u0004שדה \u0003עבודה\u0004 (מעובדת), שנחרשה (ולא נזרעה) בשנה הקודמת, ולכך די לה בחרישה אחת השנה. ואילו \u0003כאן\u0004 בברייתא מדובר \u0003ב\u0004שדה \u0003שאינה עבודה,\u0004 שלא נחרשה השדה בשנה שעברה, ולכך יש לחרוש אותה עתה שתי פעמים.","ושואלים: ובסופו של דבר, \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה,\u0006 על \u0005בעיה זו, כיצד היא נפתרת\u0006\u0005]?\u0006 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 את פתרונה ממה \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בדרך עיבודה הראוי של שדה תבואות: בשנה ראשונה יש לעשות בתחילה \u0003ניר\u0004 (חריש) של כל השדה ב\u0003חציה\u0004 הראשון של השנה, \u0003ו\u0004לאחר מכן הבעלים \u0003זורע\u0004 רק את \u0003חציה\u0004 של השדה, ואת חציה השני הריהו משאיר כשדה ניר. וכן בשנה הבאה — בתחילה עושים \u0003ניר\u0004 (חריש) של כל השדה ב\u0003חציה\u0004 הראשון של השנה, \u0003ו\u0004לאחר \u0003מכן\u0004 \u0003זורע\u0004 הבעלים את \u0003חציה\u0004 השני של השדה (במחצית השדה שלא נזרעה בשנה שעברה), ואת המחצית הראשונה של השדה הריהו משאיר עתה כשדה ניר. והרי מכאן ראיה כי אף בשנה השניה, וכל בכל שנה ושנה, חוזרים וחורשים את השדה.","\u0003אמר ר' יוחנן: אין מביאין את העומר אלא מן השדות המודרמות\u0004 (הנמצאות בחלק הדרומי) \u0003שבארץ ישראל, שבהן חמה זורחת\u0004 בתחילה, \u0003ומהן\u0004 ה\u0003חמה\u0004 מעריבה \u0003ו\u0004\u0003שוקעת.\u0004","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה ברייתא האומרת גם כן כך],\u0006 \u0003אבא שאול אומר:\u0004 ה\u0003עומר היה בא מ\u0004שדה תבואה הנמצא ב\u0003בקעת בית מקלה.\u0004 ובתיאורה של שדה זו נמסר, ש\u0003כבת\u0004 (שיעור שטחה) \u0003שלש סאין היתה, ושדה מודרמת היתה, ובה חמה זורחת וממנה חמה שוקעת.\u0004 בשנה ראשונה היה נעשה \u0003ניר\u0004 (חריש) בכל השדה, והיה זה \u0003ב\u0004\u0003חציה\u0004 הראשון של השנה, \u0003ו\u0004לאחר מכן היה הבעלים \u0003זורע\u0004 רק את \u0003חציה\u0004 של השדה. ובשנה הבאה היה נעשה שוב \u0003ניר\u0004 ב\u0003חציה\u0004 הראשון של השנה, \u0003וזורע\u0004 את \u0003חציה\u0004 השני של השדה.","\u0003ו\u0004מסופר כי \u0003רב חלקיה בר טובי הוה ליה קרנא דארעא\u0004 \u0005[היתה לו אדמת זוית,\u0006 קרקע הנמצאת בזוית שבין שתי רוחות השמים\u0003],\u0004 ועיבד אותה כך: בשנה זו — \u0003ניר חציה וזרע חציה,\u0004 ובשנה שלאחריה — \u0003ניר חציה וזרע חציה. ו\u0004מסופר כי כה גדול היה יבולה של שדה זו, עד ש\u0003עבדה\u0004 \u0005[עושה,\u0006 נותנת יבול\u0005]\u0006 בשיעור שהוא \u0003על חד תרי\u0004 \u0005[אחת שתים,\u0006 פי \u0005שתים\u0006\u0005]\u0006 משדה אחרת בגודלה, \u0003ומזבין להו לחיטי לסמידא\u0004 \u0005[והיה מוכר אותם, את החיטים\u0006 שמן השדה הזו \u0005ל\u0006צורך \u0005סולת\u0006 מנחות המקדש\u0005].\u0006","\u0003ו\u0004עוד שנינו במשנתנו ש\u0003אם\u0004 הסולת \u0003התליעה\u0004 — הריהי \u0003פסולה\u0004 מלהיקרב. ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003סולת שהתליעה רובה\u0004 — הריהי \u0003פסולה\u0004 ליקרב במקדש, \u0003ו\u0004כן \u0003חיטין\u0004 שעדיין לא נטחנו לקמח, \u0003שהתליעו רובן — \u0004 הריהן \u0003פסולות,\u0004 שאין לעשות מהן קמח שיוקרב. ובבירורם של דברים אלה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 למה הכוונה בלשון \"חיטין שהתליעו רובן\" \u0003רוב\u0004 של כל \u0003חטה\u0004 שאם התליעה ברובה — הריהי פסולה. \u0003או\u0004 שהדברים מתייחסים לכלל החיטים המובאות עתה, ולהורות שאם באה לפנינו כמות של חיטים יש לבדוק אם ישנם תולעים \u0003ברוב\u0004 ה\u0003סאה\u0004 שלפנינו. ואם נמצאת רוב הסאה מתולעת — פסולה כולה? ומציינים כי שאלה זו לא נפתרה, ולכך \u0003תיקו\u0004 \u0005[תעמוד,\u0006 תישאר\u0005]\u0006 במקומה.","ועוד שאלה הנוגעת לחיטים שהתליעו הפסולות להקרבה במקדש \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 אדם שעבר ו\u0003הקדישן\u0004 את החיטים שהתליעו, \u0003מהו\u0004 דינו לענין זה \u0003שילקה עליהן\u0004 \u0003משום\u0004 שהקדיש דבר שהוא \u0003בעל מום\u0004 (הפסול בגופו) להקרבה? וצדדי השאלה: האם \u0003כיון דפסיל\u0004 \u0005[שפסול]\u0006 הדבר המתולע להקרבה \u0003כבעל מום\u0004 הוא \u0003דמי\u0004 \u0005[נחשב],\u0006 וילקה על הקדשתו כשאר מקדיש בעל מום. \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר כי \u0003אין בעל מום אלא בבהמה\u0004 הפסולה להקרבה, ואין המקדיש חיטים מתולעות לוקה על כך. אף שאלה זו לא נפתרה, ולכך \u0003תיקו\u0004 \u0005[תעמוד,\u0006 תישאר\u0005]\u0006 במקומה.","ובדומה לכך \u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 במשנה במסכת מידות\u0005]\u0006 בתיאור הלשכות במקדש ובכללן לשכת העצים, בה היו בודקים את העצים, משום ש\u0003כל עץ שנמצא בו תולעת\u0004 — \u0003פסול\u0004 להקרבה \u0003לגבי\u0004 ה\u0003מזבח.\u0004 \u0003אמר שמואל: לא שנו\u0004 חכמים שהעץ המתולע נפסל, \u0003אלא\u0004 רק בעץ \u0003לח\u0004 שאין המקום המתולע בעץ ניתן לעקירה, \u0003אבל\u0004 אם היה זה עץ \u0003יבש\u0004 — אין הוא נפסל בכך, אלא הכהן \u0003גוררו\u0004 (חותך את המקום המתולע, ועוקרו), \u0003וכשר\u0004 העץ בכך.","ובדין זה של עצים המתולעים \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 אם עבר אדם ו\u0003הקדישו\u0004 את העץ המתולע, \u0003מהו\u0004 דינו לענין זה \u0003שילקה עליו\u0004 כעובר על איסור תורה, ו\u0003משום\u0004 שהקדיש דבר שהוא \u0003בעל מום\u0004 (הפסול בגופו) להקרבה? וצדדי השאלה: האם \u0003כיון\u0004 ש\u0003פסול\u0004 העץ המתולע להקרבה \u0003כבעל מום\u0004 הוא \u0003דמי\u0004 \u0005[נחשב],\u0006 וילקה על הקדש זה כשאר מקדיש בעל מום. \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר כי \u0003אין בעל מום אלא בבהמה,\u0004 ולא בשאר דברים, לוקה על כך. אף שאלה זו לא נפתרה, ולכך \u0003תיקו\u0004 \u0005[תעמוד,\u0006 תישאר\u0005]\u0006 במקומה.","השמן הבא מהיישוב \u0003תקוע\u0004 — הריהו \u0003אלפא\u0004 (ראשון במעלה) \u0003ל\u0004כל \u0003שמן\u0004 הבא ממקום אחר, והוא הראוי להיות מובא למקדש למנחות. \u0003אבא שאול\u0004 מוסיף ו\u0003אומר\u0004 כי \u0003שניה לה\u0004 לתקוע בחשיבות שמניה היא העיר \u0003רגב\u0004 הנמצאת \u0003בעבר הירדן.\u0004 ומסבירים: אף שמצד הדין \u0003כל הארצות היו כשרות\u0004 להבאת שמן מהן למנחות, לא היו מביאים מהן שמן \u0003אלא\u0004 דווקא \u0003מיכן\u0004 (מתקוע, ומרגב) \u0003היו מביאין.\u0004","\u0003אין מביאין\u0004 שמן למנחות \u0003לא מבית הזבלים\u0004 (שדה מזובלת), \u0003ולא מבית השלחים\u0004 (שדה המושקית בידי אדם), \u0003ו\u0004כן \u0003לא\u0004 מביאים שמן \u0003מן מה\u0004 (מאותם עצים) \u0003שנזרע ביניהם. ו\u0004בכל אלה \u0003אם הביא\u0004 מהם שמן — הריהו \u0003כשר\u0004 למנחות. וכן \u0003אין מביאין אנפקטן\u0004 (שמן הנעשה מזיתים שלא נגמר בישולם), \u0003ו\u0004אף אלה \u0003אם הביא\u0004 מהם — הריהו \u0003כשר.\u0004 אבל \u0003אין מביאין\u0004 שמן למקדש \u0003מן הגרגרין\u0004 של הזיתים \u0003שנשרו במים, ולא מן\u0004 הזיתים \u0003הכבשים\u0004 (הכבושים במלח ובחומץ), \u0003ולא מן\u0004 הזיתים \u0003השלוקים\u0004 (המבושלים קצת או הרבה), \u0003ואם הביא\u0004 שמן מאלה — הריהו \u0003פסול.\u0004","שנינו במשנתנו כי השמן הבא מתקוע הריהו המשובח (\"אלפא\") בשמנים. ומביאים עוד בענין שמנה של תקוע. נאמר: \u0003\"וישלח יואב תקועה ויקח משם אשה חכמה\"\u0004 (שמואל ב יד, ב), על מנת שאותה אשה תאמר דברים לפני המלך. ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה,\u0006 מדוע דווקא\u0005]\u0006 שלח יואב אנשים \u0003תקועה? אמר ר' יוחנן: מתוך שרגילין\u0004 בני המקום תקוע בשימוש \u0003בשמן זית, חכמה מצויה בהן.\u0004 ולכך אף אשה זו היתה חכמה ביותר.","ומתוך שדובר בשמנה של תקוע המצויה בנחלת שבט אשר, מביאים מה שנאמר בשבחה של נחלה זו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בברכת משה לשבט אשר \"יהי רצוי אחיו \u0003וטובל בשמן רגלו\"\u0004 (דברים לג, כד) — \u0003זה חלקו\u0004 (נחלתו) \u0003של\u0004 שבט \u0003אשר, שמושך\u0004 (זורם) בה ה\u0003שמן כמעין.\u0004 ומסופר ש\u0003אמרו: פעם אחת\u0004 אירע ש\u0003נצרכו להן אנשי\u0004 העיר \u0003לודקיא\u0004 שבאסיה \u0003בשמן. מינו\u0004 \u0003להן פולמוסטוס\u0004 (ממונה) \u0003אחד,\u0004 ו\u0003אמרו לו: לך והבא לנו\u0004 כמות \u0003שמן ב\u0004מחיר של \u0003מאה ריבוא\u0004 (רבבות) מנים.","\u0003הלך\u0004 אותו ממונה בתחילה \u0003לירושלים\u0004 כדי לקנות כמות כזו של שמן, \u0003אמרו לו\u0004 בני ירושלים שאין להם שמן כדי כך, ולשם קניית כמות כזו של שמן \u0003לך לצור\u0004 שהיא מרכז המסחר. \u0003הלך לצור, אמרו לו\u0004 בני צור שאף להם אין כמות כזו של שמן למכירה, ואולם \u0003לך לגוש חלב. הלך לגוש חלב, אמרו לו\u0004 בני גוש חלב: \u0003לך אצל פלוני לשדה הלז.\u0004 הלך אותו ממונה \u0003ומצאו\u0004 את בעל הבית \u0003בעת\u0004 \u0003שהיה עוזק\u0004 (עודר) \u0003תחת זיתיו. אמר לו\u0004 אותו ממונה: \u0003יש לך\u0004 למכור לי כמות \u0003שמן ב\u0004מחיר של \u0003מאה ריבוא\u0004 מנים, \u0003שאני צריך? אמר לו\u0004 בעל הזיתים: \u0003המתן לי עד שאסיים מלאכתי\u0004 בעידור. \u0003המתין עד שסיים מלאכתו.\u0004","\u0003לאחר שסיים מלאכתו, הפשיל\u0004 בעל הזיתים את \u0003כליו לאחוריו,\u0004 כדרכם של פועלים, \u0003והיה מסקל ובא בדרך,\u0004 כשהיה מוצא שם אבן היה מסלק אותה. סבור היה אותו ממונה כי פועל עני עומד לפניו, \u0003אמר לו\u0004 בתמיהה: האם אמנם \u0003יש לך שמן במאה ריבוא?\u0004 והוסיף ואמר: \u0003כמדומה אני ששחוק שחקו בי היהודים,\u0004 אותם בני גוש חלב ששלחו אותי לאדם עני זה. \u0003כיון שהגיע\u0004 בעל הזיתים \u0003לעירו\u0004 ולביתו, \u0003הוציאה לו שפחתו\u0004 בתחילה \u0003קומקמום של\u0004 מים \u0003חמין, ורחץ בו ידיו ורגליו.\u0004 ולאחר מכן עמדה ו\u0003הוציאה לו ספל של זהב מליאה שמן, וטבל בו\u0004 את \u0003ידיו ו\u0004את \u0003רגליו, לקיים מה שנאמר\u0004 בבני שבט אשר: \u0003\"וטובל בשמן רגלו\".\u0004","\u0003לאחר שאכלו ושתו,\u0004 עמד בעל הזיתים ו\u0003מדד לו\u0004 מאוצרותיו \u0003שמן ב\u0004מחיר של \u0003מאה ריבוא\u0004 מנים. \u0003אמר לו\u0004 בעל הזיתים לשליח: \u0003כלום\u0004 (האם) \u0003אתה צריך ליותר\u0004 מכמות זו של שמן? \u0003אמר לו: הן, אלא שאין לי\u0004 עוד \u0003דמים\u0004 (כסף) לשלם עבור תוספת שמן, שלא הבאתי אתי אלא מיליון מנים. \u0003אמר לו\u0004 בעל הזיתים: \u0003אם אתה רוצה ליקח\u0004 (לקנות) כמות שמן גדולה יותר — \u0003קח\u0004 (קנה), \u0003ואני אלך עמך\u0004 חזרה ללודקיא, \u0003ואטול\u0004 שם את \u0003דמיו\u0004 (הכסף) עבור תוספת השמן. ומסופר כי \u0003מדד לו\u0004 כמות \u0003שמן ב\u0004עוד \u0003שמונה עשר ריבוא\u0004 מנים. הוסיפו ו\u0003אמרו\u0004 חכמים שכה גדול היה משא השמן שלקח אותו השליח, עד ש\u0003לא הניח\u0004 (השאיר) אחריו \u0003אותו האיש\u0004 (השליח מלודקיא) \u0003לא סוס ולא פרד ולא גמל ולא חמור בארץ ישראל שלא שכרו.\u0004","ועוד מסופר כי \u0003כיון\u0004 (בזמן) \u0003שהגיע\u0004 אותו השליח \u0003לעירו, יצאו\u0004 לקראתו כל \u0003אנשי עירו\u0004 על מנת \u0003לקלסו\u0004 (לשבחו) על שהצליח להביא כל כך הרבה שמן, \u0003אמר להם\u0004 אותו השליח לבני עירו: \u0003לא לי קלסוני, אלא ל\u0004אדם \u0003זה שבא עמי, שמדד לי שמן במאה ריבוא\u0004 מנים, \u0003והרי\u0004 הוא עוד \u0003נושה בי בשמונה עשרה ריבוא\u0004 מנים. ובא סיפור זה \u0003לקיים\u0004 (להמחיש) \u0003מה שנאמר: \"יש מתעשר ואין כל מתרושש והון רב\"\u0004 (משלי יג, ז), שיש אדם הנוהג כעשיר ואין בידו כלום (\"מתעשר ואין כל\"). ויש הנוהג כעני, והריהו עשיר מופלג (\"מתרושש והון רב\"), כבעל זיתים זה שמגוש חלב.","שנינו במשנתנו כי \u0003אין מביאין\u0004 שמן למקדש \u0003לא מבית הזבלים\u0004 ולא מבית השלחים... אין מביאין אנפקטן, ואם הביא — פסול. ומכאן יש להסיק כי אף שמן האנפקטן הריהו בכלל השמנים, אלא שפסול הוא, ועל כך שואלים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אין מביאין אנפקטן,\u0004"]]};
